   \caption{The consensus process of Weighted Byzantine Fault Tolerance (WBFT) with the pipeline mechanism. It allows the \emph{prepare} phase of the $(r+1)$-th round consensus to be initiated during the \emph{commit} phase of the $r$-th round consensus.}
   \label{fig2}
\end{figure*}

\begin{itemize} 


\begin{algorithm}[!t]
\caption{Prepare Phase}\label{alg1}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\underline{Leader Operations:}\\
% \Input{UE query $Q$, public key $PK_j^F$}
% \Output{Encrypted data block $D_{i,k}^r$}
%\BlankLine
1. Generate response: $R_L \leftarrow \text{generate\_response}(Q)$ \\
2. Encrypt data: $D_{i,h}^r \leftarrow \text{encrypt}(Q \parallel R_L, PK_j^F)$ \tcp*{h = current block height} 

3. Broadcast $D_{i,h}^r$ to all followers 
