}
\BlankLine
\underline{Leader Operations:}\\
1. Receive encrypted votes from followers\\
2. \If{ $\sum \text{weight}(v_{j,h}^r = 1) + \text{leader\_self\_weight}>2/3$}{
    Generate proof: $P_{i,h}^r \leftarrow \text{generate\_proof}(D_{i,h}^r)$  \\
}
\Else{
    Consensus termination.
}
\end{algorithm}

