\underline{Leader Operations:}\\
% \Input{UE query $Q$, public key $PK_j^F$}
% \Output{Encrypted data block $D_{i,k}^r$}
%\BlankLine
1. Broadcast $P_{i,h}^r$ to all followers 
\BlankLine

\underline{Follower Operations:}\\
%\Input{Block $D_{i,k}^r$, private key $SK_j^F$, leader's public key $PK_i^L$}
%\BlankLine
1. Decrypt $P_{i,h}^r$ by threshold signature \\
2. Verify the Byzantine character of the leader \\
