            v_{i \cdot}^{\prime(\ell)}=r v_{i \cdot}^{\ell} $}% If 语句，需要和EndIf对应
   \STATE $\, \,$ {\bf end if}
   \STATE  \noindent
\textbf{ $\, $ if} \(
\begin{aligned}
u_{\cdot j}^{w}\left(v_{\cdot j}^{(\ell)} ;\left({rv}_{\cdot j}^{(\ell)}, \boldsymbol{v}_{-\cdot j}^{(\ell)}\right)\right) &> 
u_{\cdot j}^{w}\left(v_{\cdot j}^{(\ell)} ;\left({v^{\prime}}_{\cdot j}^{(\ell)}, \boldsymbol{v}_{-\cdot j}^{(\ell)}\right)\right)
\end{aligned}
\)

