    \STATE $\, \,$ {\bf then}  {$
            v_{\cdot j}^{\prime(\ell)}=r v_{\cdot j}^{\ell} $} % If 语句，需要和EndIf对应

   \STATE $\, \,$ {\bf end if}
  \ENDFOR
  \STATE Compute regret gradient:$\forall \ell \in [Y], i \in M, j \in N:$
  \STATE $\quad$ $g_{\ell, i \cdot}^{t}= \left. \nabla_{w}\left[u_{i \cdot}^{w}\left(v_{i \cdot}^{(\ell)} ;\left({v^{\prime}}_{i \cdot}^{(\ell)}, \boldsymbol{v}_{-i \cdot}^{(\ell)}\right)\right)-u_{i \cdot}^{w}\left(v_{i \cdot}^{(\ell)} ; \boldsymbol{v}^{(\ell)}\right)\right]\right|_{w=w^{t}}$
  \STATE $\quad$ $g_{\ell, \cdot j}^{t}= \left. \nabla_{w}\left[u_{\cdot j}^{w}\left(v_{\cdot j}^{(\ell)} ;\left({v^{\prime}}_{\cdot j}^{(\ell)}, \boldsymbol{v}_{-\cdot j}^{(\ell)}\right)\right)-u_{\cdot j}^{w}\left(v_{\cdot j}^{(\ell)} ; \boldsymbol{v}^{(\ell)}\right)\right]\right|_{w=w^{t}}$
  \STATE Compute Lagrangian gradient and update $w^t$:
  \STATE $\quad$ $w^{t+1} \leftarrow w^{t} - \eta \nabla_{w} \mathcal{C}_{\rho_{t}}\left(w^{t}, \lambda^{t}\right)$
  \STATE Update Lagrange multipliers once in $B$ iterations:
    \STATE $\quad$ {\bf if} {$t$ is a multiple of $B$} {\bf then} % If 语句，需要和EndIf对应
    \STATE $\quad$  $\quad$  $\lambda_{i \cdot}^{t+1} \leftarrow \lambda_{i \cdot}^{t}+\rho_{t} \widetilde{r g t}_{i \cdot}\left(w^{t+1}\right), \quad \forall i \in M$
     \STATE $\quad$  $\quad$  $\lambda_{\cdot j}^{t+1} \leftarrow \lambda_{\cdot j}^{t}+\rho_{t} \widetilde{r g t}_{\cdot j}\left(w^{t+1}\right), \quad \forall j \in N$
  \STATE $\quad$ {\bf else}
    \STATE $\quad$  $\quad$ $\boldsymbol{\lambda}^{t+1} \leftarrow \boldsymbol{\lambda}^t$
   \STATE $\quad$ {\bf end if}
\ENDFOR
% \Statex
\end{algorithmic}
\end{algorithm}

