\section{Separation and Bisimulation}\label{sec:definitions}

We now introduce the basic semantic instruments that are required for determining the decidability and complexity of the decision problems formulated in Sec.~\ref{intro} for the pairs $L/\LS$ of logics such that
%
\begin{itemize}
\item[--] $L$ is any logic with counting defined in Sec.~\ref{sec:logicsabst};

\item[--] $\LS \subseteq L$ is any logic without counting from Sec.~\ref{sec:logicsabst}.
\end{itemize}
%
From now on, we assume that a signature $\sigma$ is fixed, that $L$ and $L'$ range over the logics with and, respectively, without counting defined in Sec.~\ref{sec:logicsabst}, and that $L \supseteq \LS$ in every pair $L/\LS$. (As $\sigma$ in $\CT(\sigma)$ is assumed to be constant-free, we do not consider pairs such as $\CT/\MLn$.) To simplify presentation and since most of our logics are modal, here we only consider formulas $\vp(x)$ with one free variable $x \in \var$.
%, leaving the general case for the  appendix.  

A \emph{pointed structure} is a pair $\Amf,a$ with $a \in \dom(\Amf)$. We write $\mathfrak A \models \varphi(a)$ if $a$ satisfies $\varphi(x)$  in $\mathfrak A$. Given $\varrho \subseteq \sigma$ and  pointed $\sigma$-structures $\Amf,a$ and $\Bmf,b$, we write \mbox{$\Amf,a \equiv_{L(\varrho)} \Bmf,b$} and call $\Amf,a$ and $\Bmf,b$  \emph{$L(\varrho)$-equivalent} in case \mbox{$\Amf\models \varphi(a)$} iff $\Bmf\models \varphi(b)$, for all $L(\varrho)$-formulas $\varphi(x)$.

%Let\nz{ref to intro? define for ML?} $\varphi(x)$ and $\psi(x)$ be $\FO$-formulas. An $\FO$-formula $\chi(x)$ is called a \emph{separator} for $\varphi(x)$ and $\psi(x)$ if $\varphi(x) \models \chi(x)$ and $\chi(x) \models \neg\psi(x)$. 
%%
%If, in addition, $\sig(\chi) \subseteq \sig(\varphi) \cap \sig(\psi)$, we say that $\chi(x)$ is a \emph{Craig separator} for $\varphi(x)$ and $\psi(x)$. 
%%
%A (Craig) separator for modal formulas $\varphi$ and $\psi$ is a modal formula $\chi$ such that $\chi^*_x$ is a (Craig) separator for $\varphi^*_x$ and $\psi^*_x$. 
%
%Given two languages $L$ and $\LS$, the \emph{separation problem for $L$ by $\LS$}---or $L/\LS$-\emph{separation}, for short---is to decide whether any two given $L$-formulas have an $\LS$-separator. If we are only interested in Craig separators, we refer to the problem as \emph{Craig $L/\LS$-separation}. 
%
%Notice that $L$-formulas $\varphi$ and $\psi = \neg \varphi$ have an $\LS$-separator iff there exists an $\LS$-formula $\chi$ that is equivalent to $\varphi$, in which case we call $\varphi$ \emph{$\LS$-definable}. The \emph{definability problem for $L$ by $\LS$}---or $L/\LS$-\emph{definability}, for short---is to decide whether any given $L$-formula is equivalent to some $\LS$-formula.

A non-empty binary relation $\bis \subseteq \dom(\Amf)\times\dom(\Bmf)$ is an \emph{$\FOT(\varrho)$-bisimulation between \Amf and \Bmf} if $\bis$ is \emph{global}---that is, $\dom(\Amf)\subseteq \{a\mid (a,b)\in \bis\}$ and $\dom(\Bmf)\subseteq \{b\mid (a,b)\in \bis\}$---and for
every $(a,b)\in \bis$, the following conditions are satisfied: 
%
\begin{itemize}
\item[--] for every $a'\in\dom(\Amf)$, there is a $b'\in \dom(\Bmf)$ such that $(a',b')\in \bis$ and $(a,a')\mapsto (b,b')$ is a partial  $\varrho$-isomorphism between \Amf and \Bmf;

\item[--] for every $b'\in\dom(\Bmf)$, there is an $a'\in \dom(\Amf)$ such that $(a',b')\in \bis$ and $(a,a')\mapsto (b,b')$ is a partial  $\varrho$-isomorphism between \Amf and \Bmf.
	%$l_{\Bmf,b,b'}^\tau=l_{\Amf,a,a'}^\tau$ and $(a',b')\in S$.    
\end{itemize}
%
We write $\Amf,a \sim_{\FOT(\varrho)} \Bmf,b$ if 
$a\mapsto b$ is a partial $\varrho$-isomorphism between \Amf and
\Bmf and there is an $\FOT(\varrho)$-bisimulation $\bis$ between $\Amf$ and
\Bmf such that $(a,b)\in \bis$.
%

A non-empty $\bis \subseteq \dom(\Amf)\times\dom(\Bmf)$ is an \emph{$\ML(\varrho)$-bisimulation between $\Amf$ and $\Bmf$} if the following conditions hold:
%
\begin{itemize}
\item[--] if $(a,b) \in \bis$, then $a\in A^{\Amf}$ iff $b\in A^{\Bmf}$ for all $A\in \varrho$;

\item[--] if $(a,b) \in \bis$ and $(a,a')\in R^{\Amf}$, for $R\in \varrho$, then there exists $b'\in\dom(\Bmf)$ such that $(a',b')\in \bis$ and $(b,b')\in R^{\Bmf}$;

\item[--] if $(a,b) \in \bis$ and $(b,b')\in R^{\Bmf}$, for $R\in \varrho$, then there exists $a'\in\dom(\Amf)$ such that $(a',b')\in \bis$ and $(a,a')\in R^{\Amf}$. 
\end{itemize}
%
Further, an $\ML(\varrho)$-bisimulation $\bis$ between $\Amf$, $\Bmf$ is called an 
%
\begin{description}
\item[\rm\emph{$\MLi(\varrho)$-bisimulation}] if the second and third conditions also hold for $R = P^{-}$ with $P\in \varrho$;

\item[\rm\emph{$\MLn(\varrho)$-bisimulation}] if $(c^{\Amf},c^{\Bmf})\in \bis$, for each constant $c\in \varrho$;

\item[\rm\emph{$\MLu(\varrho)$-bisimulation}] if it is global.
\end{description}
%
$\MLiu(\varrho)$-, $\MLinu(\varrho)$-, etc.\ bisimulations are those $\bis$ that satisfy all of the conditions for the respective superscripts.
%
For a modal logic $\LS$, we write $\Amf,a \sim_{\LS(\varrho)} \Bmf,b$ if there is an $\LS(\varrho)$-bisimulation $\bis$ between $\Amf$ and $\Bmf$ such that $(a,b)\in \bis$.


The following characterisation is well-known; see, e.g.,~\cite{DBLP:books/el/07/GorankoO07,DBLP:books/daglib/p/Gradel014,Pratt23book} (see also~\cite{modeltheory} for $\omega$-saturated structures).

\begin{restatable}{lemma}{lemguardedbisim}\label{lem:guardedbisim}
For any $\LS$, $\varrho \subseteq \sigma$, and any pointed $\sigma$-structures $\Amf,a$ and $\Bmf,b$,
%
$$
\Amf,a \sim_{\LS(\varrho)} \Bmf,b \quad \text{ implies } \quad
\Amf,a \equiv_{\LS(\varrho)} \Bmf,b
$$
%
and, conversely, if structures $\Amf$ and $\Bmf$ are $\omega$-saturated, then
%
$$
\Amf,a \equiv_{\LS(\varrho)} \Bmf,b \quad \text{ implies } \quad 
\Amf,a \sim_{\LS(\varrho)} \Bmf,b.
$$
\end{restatable} 

An $\LS(\varrho)$-\emph{separator} for $L$-formulas $\varphi(x)$ and $\psi(x)$ is any $\LS(\varrho)$-formula $\chi(x)$ such that $\varphi(x) \models \chi(x)$ and $\chi(x) \models \neg \psi(x)$.
%
The next criterion is similar to Robinson's joint consistency theorem~\cite{Robinson1960}:

\begin{lemma}\label{criterion}
For any pair $L/\LS$, any $L$-formulas $\varphi(x)$, $\psi(x)$ and any $\varrho \subseteq \sigma$, the following conditions are equivalent\textup{:}
%
\begin{itemize}
\item[--] $\varphi(x)$ and $\psi(x)$ do not have an $\LS(\varrho)$-separator\textup{;}

\item[--] there are pointed $\sigma$-structures $\Amf,a$ and $\Bmf,b$ such that 
%
$$
\Amf\models \varphi(a), \quad \Bmf\models \psi(b), \quad \Amf,a \sim_{\LS(\varrho)} \Bmf,b.
$$
\end{itemize} 
\end{lemma}
%
\begin{proof}
The proof is in line with the characterisations of Craig interpolant existence in~\cite{DBLP:conf/lics/JungW21,DBLP:journals/tocl/ArtaleJMOW23}.
\end{proof}

%\begin{corollary}\label{cor-def}
%An $L$-formula $\varphi(x)$ is not $\LS$-definable iff there are pointed $\sigma$-structures $\Amf,a$ and $\Bmf,b$ such that 
%%
%$$
%\Amf\models \varphi(a), \quad \Bmf\models \neg\varphi(b), \quad \Amf,a \sim_{\LS(\sigma)} \Bmf,b.
%$$
%\end{corollary}


We next observe a few reductions between the decision problems from Sec.~\ref{intro}. The next lemma requires the notion of \emph{unary Craig $L/\LS$-separation}, which lies between $L/\LS$-separation and Craig $L/\LS$-separation: an $\LS$-separator $\chi$ for $\varphi$ and $\psi$ is called a \emph{unary Craig $L/\LS$-separator} if all unary $A \in \sig(\chi)$ occur in both $\varphi$ and $\psi$ (non-unary predicates may be arbitrary). In modal logic, where unary predicates are regarded as propositional variables, this notion has actually been frequently considered for Craig interpolation when one does not want to restrict the use of modal operators in interpolants. Also, unary Craig separation makes our undecidability and lower complexity bound proofs more transparent.

%We next observe a few reductions between the decision problems from Section~\ref{intro}. For technical reasons (undecidability and complexity lower bound proofs are much more transparent), we introduce \emph{unary Craig $L/\LS$-separation} which lies between plain separation and Craig separation and in which one requires that the separator only uses common unary relation symbols (but arbitrary non-unary relation symbols). In modal logic (where unary relation symbols=propositional variables), this variant has actually been frequently considered for Craig interpolants when one does not want to put any constraints on the use of modal operators in interpolants).

\begin{restatable}{lemma}{lred}\label{l:red}
For any pair $L/\LS$, 
%
\begin{itemize}
\item[--] $L/\LS$-separation is polytime reducible to Craig $L/\LS$-separation and to unary Craig $L/\LS$-separation\textup{;}

\item[--] unary Craig $L/\LS$-separation is polytime reducible to $L/\LS$-separation.
\end{itemize}
\end{restatable}

While the former reduction is easy, the proof of the latter relies on Lemma~\ref{criterion}. Essentially, one replaces non-shared unary predicates in $\varphi$ and $\psi$ by compound counting formulas over shared symbols. Note also that, for all $L/\LS$, we prove exactly the same (mostly tight) complexity bounds for plain separation and Craig separation. However, we could not find a `black-box' polytime reduction of Craig separation to separation.  

Finally, we lift the well-established link between Craig interpolation and (projective) Beth definability~\cite{craig_1957,Bet56} to a link between Craig $L/\LS$-separation and an appropriate notion of $L/\LS$-definability. 
%
\begin{description}	
\item[relative $L/\LS$-definability:] given a signature $\varrho$ and two $L$-formulas $\varphi$ and $\psi$,  decide whether there exists an \emph{explicit $\LS(\varrho)$-definition of $\psi$ modulo} $\varphi$, i.e., an $\LS(\varrho)$-formula $\delta$ such that $\varphi \models \delta \leftrightarrow \psi$.
\end{description}

\begin{restatable}{lemma}{thmequivdef}
\label{thm:equivdef}
For any pair $L/\LS$, Craig $L/\LS$-separation and relative $L/\LS$-definability are polytime reducible to each other. 
\end{restatable}

Using a standard trick from, e.g.,~\cite{MGabbay2005-MGAIAD}, the proof shows how the construction of separators can be used to construct definitions and the other way round. 

