\section{Separation in Fragments of $\GMLnu$}\label{sec:gmlu}


The aim of this section is to prove the following:

\begin{restatable}{theorem}{complexGMLnu}
\label{thm:gmlu}
Separation and Craig-separation are
%
\begin{description}
\item[\it\textup{$2\ExpTime$}-complete] for the pairs $\GMLnu/\MLnu$, $\GMLnu/\MLn$, $\GMLnu/\MLu$, $\GMLu/\MLu$, and $\GMLu/\ML$\textup{;}

\item[\it\textup{$\coNExpTime$}-complete] for $\GMLn/\MLn$ and $\GML/\ML$. 
\end{description}
\end{restatable}

We begin by establishing the upper bounds. By Lemma~\ref{l:red}, it suffices to consider Craig separation. Let $\varphi_{1}$, $\varphi_{2}$ be $\GMLnu$-formulas, $\sigma = \sig(\varphi_{1}) \cup \sig(\varphi_{2})$ and $\varrho = \sig(\varphi_{1}) \cap \sig(\varphi_{2})$. 
%Denote\nb{!!} by $\mx$ the maximal number $k$ such that $\Diamond_R^{\ge k}$ occurs in $\varphi_{1}$ or $\varphi_{2}$, for some $R$. 
%
A \emph{type} (\emph{for $\varphi_{1}$ and $\varphi_{2}$}) is any set $\type \subseteq \sub(\varphi_{1},\varphi_{2})$, for which there is a pointed $\sigma$-structure $\Amf, a$ such that $\type=\type(\Amf,a)$, where 
%
\[
\type(\Amf,a) = \{ \chi\in \sub(\varphi_{1},\varphi_{2})\mid \Amf \models \chi(a)\}
\] 
%
is the \emph{type} \emph{realised by $a$ in $\Amf$}. Denote by $\Types$ the set of all such types. Clearly, $|\Types| \le 2^{|\sub(\varphi_{1},\varphi_{2})|}$ and $\Types$ can be computed in time exponential in $|\varphi_{1}| + |\varphi_{2}|$.
%
Types $\type_1$ and $\type_2$ are called \emph{$\Du$-equivalent}
in case $\Du\chi\in \type_1$ iff $\Du\chi\in \type_2$, for all $\Du\chi\in \sub(\varphi,\psi)$. Note that the types realised in the same structure are $\Du$-equivalent to each other. 

We check the existence of $\sigma$-structures $\Amf_1,a_1$ and $\Amf,a_2$ such that $\Amf_i\models \varphi_i(a_i)$, $i=1,2$,  and $\Amf_1,a_1 \sim_{\MLnu(\varrho)} \Amf_2,a_2$ using a mosaic-elimination procedure, a generalisation of the standard type-elimination procedure for satisfiability-checking; see, e.g.,~\cite[p.~72]{GabEtAl03}. 

A \emph{mosaic} (\emph{for $\varphi_{1}$ and $\varphi_{2}$}) is a pair $M=(M_{1},M_{2})$ of non-empty sets $M_{1},M_{2}$ of types satisfying the following conditions: 
%, for any $\type,\type'\in M_{1}\cup M_{2}$,
%
\begin{itemize}
\item[--] $A\in \type$ iff $A\in \type'$, for all $A\in \varrho$ and $\type,\type'\in M_{1}\cup M_{2}$;

\item[--] $N_c\in \type$ iff $N_c\in \type'$, for all $c \in \varrho$ and $\type,\type'\in M_{1}\cup M_{2}$; 

\item[--] 
%{\color{red} if $N_c\in \type\in M_{i}$, then $N_c\not\in\type'$ for any $\type'\in M_{i}$ with $\type'\not=\type$, for all $c\in \sigma$;} 
if $\type, \type' \in M_{i}$, $i \in \{1,2\}$, $N_c\in \type \cap \type'$, $c\in \sigma$, then $\type = \type'$; %, for all $c\in \sigma$;

\item[--] all types in each $M_{i}$ are $\Du$-equivalent to each other.
\end{itemize}
%
%{\color{red} Observe that it follows from Points~2 and 3 that if $N_c\in \type\in M_{i}$, then $M_{i}=\{\type\}$, for $i = 1,2$ and all $c\in \varrho$.}
We say that $N_c$ \emph{occurs} in $M$ if $N_c \in \type\in M_{i}$, for some $\type$ and $i\in \{1,2\}$.
%
As follows from the second and third items, if $N_c$ occurs in  $M$, for some $c\in \varrho$, then $M_1$ and $M_2$ are singletons. 


There are at most doubly exponentially many mosaics, and they can be computed in double exponential time. Let $f$ be the function defined by taking $f(M) = 1$ if $M$ contains a type with a nominal 
%\textcolor{blue}{$N_c$, for some $c \in\sigma$,} 
and $f(M) = \mx$ otherwise, where $\mx$ is the maximal $k$ such that $\Diamond_R^{\ge k}$ occurs in $\varphi_{1}$ or $\varphi_{2}$, for some $R$.

The definition of mosaic above is an abstraction from the following semantical notion. Given structures $\Amf_{1}$ and $\Amf_{2}$, the
\emph{mosaic defined by $a\in \dom(\Amf_{i})$ in $\Amf_{1},\Amf_{2}$}, $i \in \{1,2\}$, 
is the pair $M(\Amf_{1},\Amf_{2},a)=(M_{1}(\Amf_{1},a),M_{2}(\Amf_{2},a))$, where, for $j \in \{1,2\}$,
% 
\[
M_{j}(\Amf_{j},a) = \{ \type(\Amf_{j},b) \mid b\in
\dom(\Amf_{j}), \ \Amf_{i},a \sim_{\MLnu(\varrho)}\Amf_{j},b\}.
\] 
%
%\tony{Suggestion: I may misunderstand what the notation $\Amf_{1/2}$ means. Is it $\Amf_1$ %or $\Amf_2$?
%If so, maybe it is better to use $M(\Amf_1,\Amf_2,a)$?}
Clearly, $M(\Amf_{1},\Amf_{2},a)$ is a mosaic and $M(\Amf_{1},\Amf_{2},a) = M(\Amf_{1},\Amf_{2},a')$ if $a \sim_{\MLnu(\varrho)} a'$, for any $a,a' \in \dom(\Amf_{1}) \cup \dom(\Amf_{2})$.

We aim to build the required structures $\Amf_{i}$, $i=1,2$, and bisimulation $\bis$ between them from copies of suitable pairs $(\type,M)$ with a mosaic $M=(M_{1},M_{2})$ and a type $\type\in M_i$, for which we, roughly, aim to  set $(\type_{1},M) \bis (\type_{2},M)$. 
To satisfy the modalities $\Diamond_{R}^{\geq k}\chi$ in the $\Amf_{i}$, we require the following definition.
%take sufficiently many copies of suitable $(\type,M)$. 
%Slightly abusing notation, we write $\type\in M$ if $\type \in M_{1}\cup M_{2}$.
%
Let $M=(M_{1},M_{2})$ be a mosaic, $\mathcal{M}$ a set of mosaics, and some type in $M_1\cup M_2$ contain $\Diamond_{R}^{\geq k}\chi$. We call $\mathcal{M}$ an \emph{$R$-witness for $M$} if there exists a relation $R^{M,\mathcal{M}} \subseteq (\Delta_{1} \times \Gamma_{1})\cup(\Delta_{2}\times \Gamma_{2})$ with  
%
\begin{align*}
& \Delta_{i} =\{ (\type,M) \mid \type\in M_{i}\},\\ 
& \Gamma_{i}=\{ (\type',M',j) \mid \type'\in M_{i}',\ M'=(M_{1}',M_{2}')\in \mathcal{M},\ 1 \le j \le f(M')\}
\end{align*}
%
satisfying the following for $\Delta=\Delta_{1} \cup \Delta_{2}$ and $\Gamma= \Gamma_{1}\cup \Gamma_{2}$:
% 
\begin{description}
%\item[(nominals)] $f(M')=1$ iff\nz{iff} $M'$ contains a nominal;

\item[($\Du$-harmony)] all types in $M_{i}$ and $M_{i}'$, for any $M'=(M_{1}',M_{2}')$ in $\mathcal{M}$, are $\Du$-equivalent to each other, $i=1,2$;

\item[(witness)] for any $\Diamond^{\geq k}_R\chi \in \sub(\varphi_1,\varphi_2)$ and $(\type,M)\in \Delta$, we have 
%
$$
\mbox{}\hspace*{-7mm}\Diamond^{\geq k}_R\chi \in \type \text{ iff } \big| \{ (\type',M',j) \in \Gamma \mid \chi\in \type', (\type,M) R^{M,\mathcal{M}} (\type',M',j) \}\big| \ge k;
$$
%
%$\Diamond^{\geq k}_R \chi \in \type$ iff $(\type,M)$ has $\ge k$ $R^{M,\mathcal{M}}$-successors $(\type',M',j)$ with $\chi\in \type'$; 

\item[(bisim)] if $R\in \varrho$, $M'\in \mathcal{M}$, and $(\type_{0},M)\in \Delta$ has an $R^{M,\mathcal{M}}$-successor $(\type_{0}',M',j)\in \Gamma$, then each $(\type_{1},M)\in \Delta$ has an $R^{M,\mathcal{M}}$-successor of the form $(\type_{1}',M',j')\in \Gamma$. 
\end{description}
%
The intuition behind conditions {\bf ($\Du$-harmony)} and {\bf (witness)} should be clear, and {\bf (bisim)} is needed to ensure that if, for any fixed $M'$, all $(\type',M',j)\in \Gamma$ are mutually $\MLnu(\varrho)$-bisimilar, then all $(\type,M)\in \Delta$ are also $\MLnu(\varrho)$-bisimilar to each other. 
%
It should also be clear that if $\Amf_1, a_1 \sim_{\MLnu(\varrho)}\Amf_2,a_2$, then every mosaic $M(\Amf_{1},\Amf_{2},a)$, for $a \in \dom(\Amf_i)$, $i=1,2$, has an $R$-witness for any relevant $R$, namely, the set $\mathcal{M}$ of all mosaics $M(\Amf_{1},\Amf_{2},b)$ such that $a' R^{\Amf_j} b$, for some $j \in \{1,2\}$ and $a' \in \dom(\Amf_j)$ with $M(\Amf_{1},\Amf_{2},a) = M(\Amf_{1},\Amf_{2},a')$.
%
Observe also that every $R$-witness $\mathcal{M}$ for $M$ contains a subset $\mathcal{M}'\subseteq \mathcal{M}$ such that $\mathcal{M}'$ is an $R$-witness for $M$ and $|\mathcal{M}'|\leq \mx 2^{|\sub(\varphi_{1},\varphi_{2})|}$. 
%and\nz{remove} the maximal value of the copying function $f$ for $\mathcal{M}'$ not exceeding $\mx (|\varphi_{1}|+|\varphi_{2}|)$.
%
So, from now on, we assume all witnesses to be of size $\leq \mx 2^{|\sub(\varphi_{1},\varphi_{2})|}$. 

We can now define the mosaic elimination procedure for a set $\mathfrak{S}$ of mosaics. Call $M=(M_{1},M_{2})\in \mathfrak{S}$ \emph{bad} in $\mathfrak{S}$ if at least one of the following conditions is \emph{not} satisfied for $i = 1,2$:
%\mathfrak{S}
\begin{itemize}
\item[--] if $\Diamond_{R}^{\geq k} \chi\in \type\in M_{i}$, then there is an $R$-witness for $M$ in $\mathfrak{S}$;

\item[--] if $\Du\chi \in \type\in M_{i}$, then there are $(M_{1}',M_{2}')\in \mathfrak{S}$ and $\type'\in M'_{i}$ such that $\chi\in \type' \in M_{i}'$ and $\type,\type'$ are $\Du$-equivalent.
\end{itemize}
%
Given a set $\mathfrak{S}$ of mosaics and $M\in \mathfrak{S}$, it can be decided in double exponential time in $|\varphi_{1}|+|\varphi_{2}|$ whether $M$ is bad in $\mathfrak{S}$.

Let $\mathfrak{S}_{0}$ be the set of all mosaics. Let $h$ be a function that, for any $c \in \sigma$ and $i \in \{1,2\}$, picks one mosaic $h(N_c,i) = (M_1,M_2)$ such that $N_c \in \type$, for some $\type \in M_i$, and if $N_{c'} \in \type'$, for some $\type' \in M_j$, $j \in \{1,2\}$ and $c'\in \sigma$, then $h(N_c,i) = h(N_{c'},j)$.
%
By the definition of mosaics, $h(N_c,1)=h(N_c,2)$ for all $c\in \varrho$.

Given such $h$, let $\mathfrak{S}_{0}^{h} \subseteq \mathfrak{S}_{0}$ comprise all mosaics of the form $h(N_c,i)$ and those that do not have occurrences of nominals. Starting from $\mathfrak{S}_{0}^{h}$, we construct inductively sets $\mathfrak{S}_{n+1}^{h}$, $n \ge 0$, by looking through the mosaics in $\mathfrak{S}_{n}^{h}$ and eliminating the bad ones. We stop when $\mathfrak{S}_{n+1}^{h} = \mathfrak{S}_{n}^{h}$ and set $\mathfrak{S}_{\ast}^{h}= \mathfrak{S}_{n}^{h}$. This can be done in double-exponential time (see the appendix).

%By Lemma~\ref{lem:decidebad1},\nb{?} $\mathfrak{S}_{\ast}^{h}$ can be constructed in double exponential time.

\begin{restatable}{lemma}{mosaicsGMLnu}
\label{lem:main1} 
The following conditions are equivalent\textup{:}
%
\begin{description}
\item[\rm $(i)$] there exist pointed $\sigma$-structures $\Amf_i,a_i$, $i=1,2$, such that $\Amf_i\models \varphi_i(a_i)$ and $\Amf_1,a_1 \sim_{\MLnu(\varrho)} \Amf_2,a_2$ \textup{(}and so $\varphi_1$ and $\varphi_2$ are not $\LS$-separable\textup{)}\textup{;}

\item[\rm $(ii)$] there exist $h$, $M^* =(M^*_{1},M^*_{2})\in \mathfrak{S}_{\ast}^{h}$ and $\type^*_i \in M^*_i$, $i=1,2$, such that $\varphi_{i}\in \type^*_{i}\in M^*_{i}$, $h(N_c,j)=(M_{1},M_{2})\in \mathfrak{S}_{\ast}^{h}$, for all $c\in \sigma$ and $j=1,2$, and all types in $M^*_{j}\cup M_{j}$ are $\Du$-equivalent to each other.
\end{description} 
\end{restatable}

Here, we only sketch how, given $(ii)$, to construct the required $\Amf_i,a_i$. For any $M = (M_1,M_2)\in \mathfrak{S}_{\ast}^{h}$ and $\Diamond_{R}^{\geq k}\chi\in \type\in M_i$, for some $\Diamond_{R}^{\geq k}\chi$, $\type$ and $i \in \{1,2\}$, we take an $R$-witness $\mathcal{M}_{R,M}\subseteq \mathfrak{S}_{\ast}^{h}$ for $M$ with the  relation $R^{M,\mathcal{M}_{R,M}}$ and define the $\dom(\Amf_{i})$ as the sets of all words
%
\begin{equation}\label{eq1m}
s=(\type_{0},M_{0},i_{0})R_{1}(\type_{1},M_{1},i_{1}) R_2 \dots R_{n}(\type_{n},M_{n},i_{n}) 
\end{equation}
%
such that $\omega > n\geq 0$, $M_{j}=(M_{j,1},M_{j,2})\in \mathfrak{S}_{\ast}^{h}$, for $j\leq n$, 
%
\begin{itemize}
\item[--] $\type_{j}\in M_{j,i}$ and $1 \le i_j \le f(M_{j,i})$, for all $j\leq n$; 

\item[--] $M_{j+1}\in \mathcal{M}_{R_{j+1},M_{j}}$ and no nominal occurs in $M_{j+1}$;

\item[--] all types in $M_{k}^{\ast}$ and $M_{0,k}$ are $\Du$-equivalent, $k=1,2$.
\end{itemize}
%
For a propositional variable $A$ and $s$ in~\eqref{eq1m}, we set $s\in A^{\Amf_{i}}$ iff $A\in \type_{n}$; for $N_c$, we set $c^{\Amf_{i}} = s$ iff $n=0$, $N_c\in \type_{0}$ and $h(N_c,i) = M_0$, and for a binary $R \in \sigma$, we set:
%
\begin{itemize}
\item[--] $(s',s)\in R^{\Amf_{i}}$  if  $s'$ is obtained by dropping $R_{n}(\type_{n},M_{n},i_{n})$ from $s$, $R=R_{n}$ and
%
$
(\type_{n-1},M_{n-1})R_{n}^{M_{n-1},\mathcal{M}_{R_n,M_{n-1}}}
(\type_{n},M_{n},i_{n});
$

\item[--] $(s,(\type,M,j))\in R^{\Amf_{i}}$ if $(\type,M,j)\in \dom(\Amf_{i})$, a nominal occurs in $M$ and $(\type_{n},M_{n})R^{M_{n},\mathcal{M}_{R,M_{n}}} (\type,M,j)$.
\end{itemize}
% 	
Finally, the bisimulation $\bis$ between the $\Amf_{i}$ is defined by taking $s\bis s'$, for $s$ in~\eqref{eq1m} and 
%
$s'=(\type_{0}',M_{0}',i_{0}')R_{1}' \dots R_{m}'(\type_{m}',M_{m}',i_{m}')$, 
%
if $n=m$, $R_{i}=R_{i}'$ and $M_{i}=M_{i}'$, for all $i\leq n$. 


Lemma~\ref{lem:main1} gives a $2\ExpTime$ upper bound for deciding (Craig) $\GMLnu/\MLnu$-separation, and the construction can be modified to show the same bound for the other logics with $\Du$. 
%
To establish the \coNExpTime upper bounds of Theorem~\ref{thm:gmlu} for  the $\Du$-free languages, we restrict the $\Amf_{i}$ to $s$ in  \eqref{eq1m} with $n$ not exceeding the modal depth of $\varphi_i$ and such that either $\type_0 \in \{\type^*_1, \type^*_2\}$ and $M_0 = M^*$ or $h(N_c,i) = M_0$, for some $c \in \sigma$.
%
The size of the resulting structures is exponential in $|\varphi_{1}|+|\varphi_{2}|$ and their existence can clearly be checked in \NExpTime. 

By Lemma~\ref{l:red}, it suffices to prove the matching lower bounds for unary Craig separation. 
%
The underlying idea, inspired by~\cite{DBLP:journals/tocl/ArtaleJMOW23}, is to construct polysize formulas $\varphi_n$ and $\psi_n$, $n < \omega$, in the required language such that if $\Amf\models \varphi_n(a)$, $\Bmf\models \psi_n(b)$, and $\Amf,a \sim_{\LS(\varrho)} \Bmf,b$, then there is $E\subseteq \dom(\Bmf)$
of size $2^{n}$ whose elements are $\LS(\varrho)$-bisimilar and satisfy all pairwise distinct combinations of variables $A_{0},\dots,A_{n-1} \notin \varrho$. 
%
For example, $\varphi_n = \Diamond_{R}^{=1}\dots \Diamond_{R}^{=1}\top$ with $n$-many $\Diamond_{R}^{=1}$ is such that $\Amf \models \varphi_n(a)$ iff $\Amf$ has a unique $R$-chain of length $n$ starting from $a$ and  
%
\begin{multline*}
\psi_n = \bigwedge_{0 \le i <n} \Big[ \Box_{R}^{i}\Diamond_{R}^{=2}\top \land \Box_{R}^{i}(\Diamond_{R}A_{i} \wedge \Diamond_{R}\neg A_{i}) \land{}\\[-3pt] 
\bigwedge_{0 \le j < i} \Box_{R}^{i}\big((A_{j} \rightarrow \Box_{R}A_{j}) \wedge (\neg A_{j} \rightarrow \Box_{R}\neg A_{j}) \big) \Big].
\end{multline*}
%
is such that $\Bmf \models \psi_n(b)$ iff the $n$-long $R$-chains from $b$ comprise a binary tree of depth $n$ whose leaves satisfy binary numbers encoded by the $A_{i}$. So, if $\Amf\models \varphi_n(a)$, $\Bmf\models \psi_n(b)$, and $\Amf,a\sim_{\ML(\varrho)} \Bmf,b$, then there is a unique $a'$ in $\Amf$ reachable via an $R$-chain of length $n$ from $a$, and there are leaves $E = \{e_{0},\dots,e_{2^{n}-1}\}$ of the binary tree with root $b$ in $\Bmf$ such that $e_{i}$ satisfies the binary encoding of $i$ via $A_{0},\dots,A_{n-1}$, and so 
$\Amf,{a'} \sim_{\LS(\varrho)}  \Bmf,e_{0} \sim_{\LS(\varrho)}\cdots \sim_{\LS(\varrho)}\Bmf,e_{2^{n}-1}$.
%
The set $E$ can now be used, following~\cite[Secs.\ 7, 9]{DBLP:journals/tocl/ArtaleJMOW23}, to encode exponential space-bounded alternating Turing machines for the \TwoExpTime-lower bound, and  $2^{n}\times 2^{n}$-torus tiling for the $\coNExpTime$ one.



