\section{Separation in Fragments of $\GMLiu$}\label{inverse-sep}

Our next aim is to generalise the mosaic technique of Sec.~\ref{sec:gmlu} to nominal-free graded modal logics with inverse and universal modalities and prove the following:

\begin{restatable}{theorem}{mosaicGMLiu}
\label{thm:gmliu}
Separation and Craig-separation are
%
\begin{description}
\item[\it\textup{$\TwoExpTime$}-complete] for all pairs of the form $\GMLiu/\LS$, where $\LS \in \{\MLiu, \MLi,\MLu, \ML\}$, and %\textup{;}

\item[\it\textup{$\coNExpTime$}-complete] for $\GMLi/\MLi$ and $\GMLi/\ML$. 
\end{description}
%
\end{restatable}

To show the upper bound for Craig $\GMLiu/\MLiu$-separation, suppose $\varphi_{1}$ and $\varphi_{2}$ are $\GMLiu$-formulas, $\sigma = \sig(\varphi_1) \cup \sig(\varphi_2)$ and $\varrho = \sig(\varphi_{1}) \cap \sig(\varphi_{2})$. Our task is to check the existence of pointed $\sigma$-structures $\Amf_{i},a_{i}$, $i=1,2$, and an $\MLiu(\varrho)$-bisimulation $\bis$ between $\Amf_{1}$ and $\Amf_2$ such that $\Amf_{1}\models\varphi_{1}(a_{1})$, $\Amf_{2}\models \varphi_{2}(a_{2})$ and $a_{1}\bis a_{2}$. 
%
We use the notion of type from Sec.~\ref{sec:gmlu} adapted in the obvious way for $\GMLiu$.

\begin{example}\em\label{ex1sec6}
Consider the $\GMLiu$-formulas
%
\begin{align*}
& \varphi_1 = B \land \blacksquare \big(B \rightarrow( \neg A \wedge \Diamond^{=1}_{R}\top \wedge \neg \Diamond_{R^{-}}\top \wedge \Diamond_R A)\big) \land{}\\
& \hspace*{1.82cm} \blacksquare \big(A \rightarrow (\Diamond_{R}^{=1}\top \wedge \Diamond_{R^{-}}^{=1}\top \wedge \Diamond_{R}\neg A) \big) \land{}\\ 
& \hspace*{2.8cm} \blacksquare \big( (\neg A \wedge \neg B) \rightarrow (\Diamond_{R}^{=1}\top \wedge \Diamond_{R^{-}}^{=1}\top \wedge \Diamond_{R} A) \big),\\
%
& \varphi_2 = \Diamond^{=2}_{R}A \land \blacksquare \big(A \rightarrow \Diamond_{R}^{=2}\neg A \wedge (\neg \Diamond_{R^{-1}} B \rightarrow
	\Diamond_{R^{-}}^{=2}\neg A) \big) \land{} \\
& \hspace*{3.9cm}	\blacksquare \big( (\neg A \wedge \neg B) \rightarrow (\Diamond_{R}^{=2}A \wedge \Diamond_{R^{-}}^{=2}A) \big).
\end{align*}	
%
