\begin{restatable}{lemma}{expcardinality}
\label{lem:cardin}
There is a polytime computable number \mbox{$k_{\varphi_{1}\varphi_{2}} = O(2^{|\varphi_{1}|+|\varphi_{2}|})$} such that, for any mosaic $M=(M_1,M_2)$ and witness $\mathcal{M}$ for $M$, there exist a mosaic $N=(N_1,N_2)$ and a witness $\mathcal{N}$ for $N$ satisfying the following\textup{:}
%
\begin{itemize}
\item[--] $|N|$, $|\mathcal{N}|$, and all $|N'|$ with $N' \in \mathcal{N}$ do not exceed $k_{\varphi_{1}\varphi_{2}}$,

%	\item[--] $|N_1|+|N_2|\leq k_{\varphi_{1},\varphi_{2}}$,
%	\item[--] $|\mathcal{N}|\leq k_{\varphi_{1},\varphi_{2}}$,
%	\item[--] $|N_1'|+|N_2'|\leq k_{\varphi_{1},\varphi_{2}}$ for all $N'=(N_1',N_2')\in \mathcal{N}$,

\item[--] $M$ and $N$ are parent profile-equivalent,

\item[--] every $N'\in\mathcal{N}$ has a child profile-equivalent $M'\in \mathcal{M}$,

\item[--] $N_i \subseteq M_i$ and, for every $N'=(N_1',N_2')\in \mathcal{N}$, there is $M'=(M_1',M_2')\in \mathcal{M}$ with $N_i'\subseteq M_i'$, for $i=1,2$.
\end{itemize}
%
\end{restatable}  

