Let $\Amf = (\dom(\Amf),(R^{\Amf})_{R\in \sigma},(c^{\Amf})_{c\in \sigma})$ be a $\sigma$-structure and let $\mathbb{N}^{\infty} = \{1,2, \dots\}\cup \{\omega\}$ with $k<\omega$, for all $k\in \mathbb{N}$. For $\kappa\in \mathbb{N}^{\infty}$, the \emph{$\kappa$-expansion} $\Amf^\kappa$ of $\Amf$ is defined by taking
%
\begin{itemize}
	\item[--] $\dom(\Amf^\kappa) = \bigcup_{a\in \dom(\Amf)}\bar{a}$, where
	$\bar{a} = \{(a,0)\}$ if $a=c^{\Amf}$, for some constant $c$, and $\bar{a} = \{(a,i)\mid 0\leq i < \kappa\}$ otherwise;

	\item[--] $A^{\Amf^\kappa} = \bigcup_{a\in A^\Amf} \bar{a}$, for a unary predicate $A\in \sigma$;

	\item[--] $R^{\Amf^\kappa} = \bigcup_{(a,b)\in R^\Amf}\bar{a}\times \bar{b}$, for a binary predicate $R\in \sigma$;

	\item[--] $c^{\Amf^\kappa} = (c^\Amf,0)$, for a constant $c\in \sigma$.
\end{itemize}
%
In other words, $\Amf^\kappa$ creates $\kappa$-many copies of each element of $\dom(\Amf)$ except for those that interpret constants in $\sigma$, in which case we only keep a single copy. The next lemma follows directly from the definition by a straightforward induction:

\begin{lemma}\label{lemma:bisim_omega}
	If $L$ is equality-free $\FO$ or a fragment of $\MLinu$, then, for any  pointed $\sigma$-structure $\Amf,a$ and any $i<\kappa$, we have $\Amf,a \equiv_{L(\sigma)} \Amf^\kappa, (a,i)$.
\end{lemma}

