%The flattening $\Flat_{\sigma_{c}}(\Diamond_R^{\ge k}\psi)$ says that either $(i)$ there %is at least one `generic' (i.e., not satisfying any nominal in $\sigma_{c}$) $R$-successor %that satisfies $\Flat_{\sigma_{c}}(\psi)$ or $(ii)$ there are $k$ different $R$-successors %that satisfy a nominal in $\sigma_{c}$ and $\Flat_{\sigma_{c}}(\psi)$.\footnote{Note that %the conjunct $\bigwedge_{d\in \varrho\setminus \{c\}}\neg N_d$ is necessary because we do %not have a unique name assumption. The set $\varrho$ therefore must contain only one name %per named element.}
It is straightforward to lift Lemma~\ref{lemma:equivalenceomega} and 
Theorem~\ref{prop:definability1} to pairs $L/\LS$ from Table~\ref{table:results} with $L$ admitting nominals and the function $\Flat_{\sigma_{c}}(\varphi)$. In this case, we do not immediately get a polytime reduction of definability to validity since $\Flat_{\sigma_{c}}(\Diamond\!^{\ge k}_R\varphi)$ contains exponentially-many disjuncts and 
because $\Flat_{\sigma_{c}}(\varphi)$ occurs more than once in $\Flat_{\sigma_{c}}(\Diamond\!^{\ge k}_R\varphi)$. A polytime reduction is obtained, however, by replacing the second disjunct of $\Flat_{\sigma_{c}}(\Diamond\!^{\ge k}_R\varphi)$ by the equivalent $L$-formula
%
$\Diamond_{R}^{\geq k} \big(\Flat_{\sigma_{c}}(\varphi) \wedge \bigvee_{c\in \sigma_{c}}N_{c}\big)$ and by working with a DAG-representation.
%
\begin{corollary}
	Let $L/\LS$ be any pair of modal logics from Table~\ref{table:results} such that $L$ admits nominals. Then $L/\LS$-definability is polytime reducible to $L$-validity.
\end{corollary}
%
We next consider the pair $\CT/\FOTNE$. Observe that the flattening defined above does not work now even if we admit equality in both logics. For example, $\varphi=\exists^{\geq 2}y \, \big(x=y \wedge A(y)\big)$ is unsatisfiable (and so equivalent to an $\FOTNE$-formula) but it is not equivalent to $\exists y\, \big(x=y \wedge A(y)\big)$. 
To define $\Flat(\exists^{\geq k}x \, \varphi)$ in this case so that Lemma~\ref{lemma:equivalenceomega} holds, we distinguish between $k=1$ and $k\geq 2$, decomposing $\exists^{\geq k}x \, \psi$ into  
%
$$
\exists^{\geq k}x \, \big[ \big((x=y) \wedge \psi\big) \vee \big((x\not=y) \wedge \psi\big) \big],
$$ 
%
where $\{x,y\} = \var$. 
For $k=1$, we rewrite the disjuncts separately into formulas without equality, and for $k=2$, we only take a flattening of the second disjunct without equality; details are given in the appendix. One can then again lift Theorem~\ref{prop:definability1} and obtain a polytime
reduction of $\CT/\FOTNE$-definability to $\CT$-validity.
We note that the decidability status of $\CT/\FOT$-definability remains open. 

In contrast to separation, the upper bounds for definability shown above cannot be easily extended from $L/\LS$ to $L/L''$, where $\ML\subseteq L''\subseteq \LS$.
A fundamental difference from the pairs of logics considered above is that  equivalent formulas in the weaker logic are sometimes exponentially larger even in DAG-size as demonstrated by the following:

\begin{restatable}{lemma}{lemsuccinctness}
	\label{lem:succinctness}
The formulas  
%
$$
\varphi_{n}(x) = \exists y \, \big[ R(x,y) \wedge \bigwedge_{1\leq i \leq n} \big(A_{i}(x) \leftrightarrow A_{i}(y) \big) \big], \ \ n < \omega,
$$ 
%
are $\ML$-definable, but any equivalent $\MLiu$-formulas are of exponential DAG-size.
\end{restatable}

Using a succinct version of modal logic, we nevertheless prove the following result:

\begin{theorem}\label{thm:succ}
Let $\LS\in \{\MLiu,\MLi,\ML\}$. Then $\CT/\LS$-defina\-bility is polytime reducible to $\CT$-validity.
\end{theorem}

As we know, $\CT/\FOTNE$-definability is polytime reducible to $\CT$-validity. So it remains to reduce $\FOTNE/\LS$-definability to $\CT$-validity. Here, we only provide a high-level overview of the proof and give details in the appendix.  
%As the proof is only concerned with $\FOTNE/\LS$-definability and not with counting at all,
%we provide a high-level overview only and give details in the appendix.
%
The \emph{succinct version} suc$\MLiu$ of $\MLiu$ is obtained from $\FOTNE$ by admitting binary
atoms $R(x,y)$ only if $x\not=y$ and $R(x,y)$ occurs in  
%
$$
\exists y \, \big( R(x,y) \wedge \psi(x,y) \big) \quad \text{or} \quad 
\exists y\, \big(R(y,x) \wedge \psi(x,y)\big). 
$$
%
Further, suc$\MLi$ is obtained by admitting quantifiers only in such formulas, while suc$\ML$ is obtained by admitting formulas of the former type only.

For $\FOTNE/\text{suc}\MLiu$-definability, given any structure $\mathfrak{A}$, we take its \emph{twin-unfolding} $\Amf^{\ast}$ that  consists of the standard unfoldings of $\Amf$ along binary relations and their inverses, with at least two unrelated copies of any node. The structures $\Amf$ and $\Amf^{\ast}$ cannot be distinguished in suc$\MLiu$. Next, define a polysize \emph{modal reduct} $m(\varphi(x))$ in $\text{suc}\MLiu$ of any $\FOTNE$-formula $\varphi(x)$ so that we have  $\Amf^{\ast}\models \varphi(a)$ iff $\Amf^{\ast}\models m(\varphi)(a)$,  for all pointed $\Amf,a$. Then one can prove analogues of Lemmas~\ref{lemma:bisim_omega} and \ref{lemma:equivalenceomega} to show that $\varphi(x)$ is suc$\MLiu$-definable iff $\models \varphi \leftrightarrow m(\varphi(x))$.
%

For $\text{suc}\MLiu/\text{suc}\MLi$- and $\text{suc}\MLiu/\text{suc}\ML$-definability, we  
say that $\Amf_{0}$ is a \emph{generated substructure} of $\Amf_{1}$ if it is a substructure of $\Amf_{1}$ and whenever $a\in \text{dom}(\Amf_{0})$ and $(a,a')\in R^{\Amf_{1}}$ or
$(a',a)\in R^{\Amf_{1}}$, then $a'\in \dom(\Amf_{0})$. We call 
$\Amf_{0}$ a \emph{forward generated substructure} of $\Amf_{1}$ if it is a substructure of $\Amf_{1}$ and whenever $a\in \text{dom}(\Amf_{0})$ and $(a,a')\in R^{\Amf_{1}}$, then $a'\in \dom(\Amf_{0})$.
We say that $\varphi$ is \emph{invariant under $($forward$)$ generated substructures} if, for all pointed $\Amf,a$ and all (forward) generated substructures $\Amf'$ of $\Amf$ with $a\in \dom(\Amf')$, we have $\Amf\models\varphi(a)$ iff $\Amf'\models \varphi'(a)$.
We then show that $\varphi\in \MLiu$ is $\MLi$-definable ($\ML$-definable) iff $\varphi$ is invariant under (forward) generated substructures and that the latter conditions can be reduced in polytime to $\text{suc}\MLiu$-validity.

