\section{Uniform Separation}\label{sec:uniformseparation}

Let $L,\LS$ be a pair of logics, $\sigma$ a signature,
and $\varphi$ an $L(\sigma)$-formula. An $\LS(\sigma)$-formula $\varphi'$ is called an \emph{$\LS(\sigma)$-uniform separator for $\varphi$}
if it is a logically strongest $\LS(\sigma)$-formula that follows from $\varphi$ in the sense that $\varphi\models \varphi'\models \chi$, for every $\LS(\sigma)$-formula $\chi$ with $\varphi\models \chi$. The \emph{uniform $L/\LS(\sigma)$-separation problem} is to decide, given an $L(\sigma)$-formula $\varphi$, whether it has an $\LS(\sigma)$-uniform separator. If such a separator for $\varphi$ exists, it is unique up to logical equivalence and separates any $\LS(\sigma)$-separable $L(\sigma)$-formulas $\varphi$ and $\psi$. Note, however, that uniform $\LS(\sigma)$-separators for distinct $\sigma$ can be non-equivalent and that a uniform $L(\sigma)$-separator might only exist for some $\sigma$.

We show that, for $L,\LS$ from Table~\ref{table:results}, the flattenings $\Flat$ and $\Flat_{\sigma_{c}}$ defined in the previous section provide uniform separators iff such separators exist. The following example is easily verified using the results to be established below.
%
\begin{example}\em
	Let $\varphi=\Diamond_{R}^{\geq k}A$. The formula $\Flat(\varphi)= \Diamond_{R} A$ is a uniform $\MLinu(\sigma)$-separator for $\varphi$ if $\sigma$ contains infinitely-many unary and binary predicates (including $R$ and $A$) and no constants. If $\sigma_{\ell}=\sigma\cup \sigma_{c}^{\ell}$, where $\sigma_{c}^{\ell}$ contains $\ell$-many constants, then $\varphi_{\ell}=\Flat_{\sigma_{c}^{\ell}}(\varphi)$ is a uniform $\MLinu(\sigma_{\ell})$-separator for $\varphi$. Note that  $\varphi_{\ell'}\models \varphi_{\ell}$, for $\sigma_{c}^{\ell'}\supseteq \sigma_{c}^{\ell}$, but the converse entailment does not hold. There is no uniform $\MLinu(\sigma_{\omega})$-separator for $\varphi$ if $\sigma_{\omega}$ contains infinitely-many constants.
	\hfill $\dashv$
\end{example}

Following what is customary for uniform interpolation and most robust~\cite{Visser96,DBLP:series/lncs/KonevLWW09,DBLP:journals/apal/KowalskiM19},
we assume that $\sigma$ contains countably-infinite sets of unary and binary predicates. If $L$ admits nominals, we consider $\sigma$ with either a finite or an infinite set of constants, denoted $\sigma_{c}$. Unless otherwise indicated, we assume $\sigma$ to be fixed. 
%This assumption ensures that the existence of uniform separators is syntax independent (e.g., %does not dependent on having conjuncts of the form $(A \vee \neg A$ in $\varphi$). 
%Recall that  denotes the set of constants in $\sigma$.
We first consider nominal-free logics.

\begin{restatable}{theorem}{thmuniformsepone}
	\label{thm:uniformsep1}
	Let $L/\LS$ be either $\CT/\FOTNE$ or any pair of nominal-free modal logics from Table~\ref{table:results}. Then, for any signature $\sigma$ with $\sigma_{c}=\emptyset$ and any $L(\sigma)$-formula $\varphi$, the following conditions are equivalent\textup{:}
	%
	\begin{enumerate}
		\item[$(a)$] $\varphi$ has a uniform $\LS(\sigma)$-separator\textup{;}

		\item[$(b)$] $\Flat(\varphi)$ is a uniform $\LS(\sigma)$-separator for $\varphi$\textup{;}

		\item[$(c)$] $\varphi\models \Flat(\varphi)$\textup{;}

		\item[$(d)$] $\varphi$ is preserved under $\omega$-expansions of $\sigma$-structures $\Amf$ in the sense that $\Amf\models \varphi(a)$ implies $\Amf^{\omega}\models \varphi(a,0)$, for any pointed $\sigma$-structure $\Amf,a$.
	\end{enumerate}
\end{restatable}
%
\begin{proof}
	We prove $(a) \Rightarrow (d)$ for $\GMLu/\MLu$. The implications $(d)\Rightarrow (c) \Rightarrow (b) \Rightarrow (a)$ can be proved using Lemmas~\ref{lemma:bisim_omega} and \ref{lemma:equivalenceomega}; the remaining pairs $L/\LS$ are considered in the appendix.

	For a proof by contradiction, assume that $\varphi'$ is a uniform $\MLu(\sigma)$-separator for $\varphi$ but there is a pointed $\sigma$-structure $\Amf,a$ such that $\Amf\models \varphi(a)$ and $\Amf^{\omega}\not\models \varphi(a,0)$. By Lemma~\ref{lemma:equivalenceomega}, we have $\Amf^{\kappa}\not\models\varphi(a,0)$ for all $\kappa > \mx$. By Lemma~\ref{lemma:bisim_omega}, $\Amf^{\kappa}\models\varphi'(a,0)$ for all $\kappa> \mx$.

	For any signature $\varrho$ and any $k\geq 0$, let $\MLu_{k}(\varrho)$ be the set of all $\MLu(\varrho)$-formulas of modal depth at most $k$. If $\varrho$ is finite, then $\MLu_{k}(\varrho)$ is finite modulo logical equivalence. Take propositional variables $A_{0},\ldots,A_{\mx}$ in $\sigma\setminus(\sig(\varphi)\cup \sig(\varphi'))$ and let $\varrho=\{A_{0},\ldots,A_{\mx}\} \cup \sig(\varphi)\cup \sig(\varphi')$. Define $\Bmf^{\mx+1}$ as $\Amf^{\mx+1}$ with the exception that, for $0\leq i \leq \mx$,
	% 
	$$
	A_{i}^{\Bmf^{\mx+1}}= \{(a,i) \mid a\in \dom(\Amf)\}.
	$$
	%
Consider the set $\Gamma$ of $\MLu_{\md(\varphi)+2}(\varrho)$-formulas $\chi$ such that $\Bmf^{\mx+1}\models\chi(a,0)$. Let $\gamma = \bigwedge_{\chi\in \Gamma}\chi$. 
	We show that $\gamma \models \varphi \leftrightarrow \Flat(\varphi)$. 
	Observe that $\Gamma$ contains 
	%
	$$
	\blacksquare(A_{i}\rightarrow \neg A_{j}), \quad \text{for $0\leq i < j \leq \mx$}, 
	$$
	%
	and, for every $\chi\in \sub(\Flat(\varphi))$ and $R\in \varrho$, it also contains
	%
	$$
	\blacksquare \big[\Diamond_{R} \chi \rightarrow \big(\Diamond_{R}(\chi \wedge A_{0}) \wedge \dots \wedge \Diamond_{R}(\chi \wedge A_{\mx}) \big) \big].
	$$
	%
	It follows that, for all $\chi\in \sub(\Flat(\varphi))$ and $R\in \varrho$, 
	%
	$$
	\gamma\models \blacksquare(\Diamond_{R} \chi \rightarrow \Diamond_{R}^{\geq \mx+1}\chi)
	$$
	%
	and one can now easily prove by induction that $\gamma \models \varphi \leftrightarrow \Flat(\varphi)$. 

	It follows that $\varphi\models \gamma \rightarrow \Flat(\varphi)$, and so, by the definition of uniform $\MLu(\sigma)$-separators, we have $\varphi'\models \gamma \rightarrow \Flat(\varphi)$. In view of $\Bmf^{\mx+1}\models \varphi'(a,0)$ and $\Bmf^{\mx+1}\models \gamma(a,0)$, we obtain $\Bmf^{\mx+1}\models \Flat(\varphi)(a,0)$. Therefore, $\Amf^{\mx+1}\models \Flat(\varphi)(a,0)$ as $\Flat(\varphi)$ does not contain $A_{0},\ldots,A_{\mx}$. It follows from Lemma~\ref{lemma:equivalenceomega} that $\Amf^{\mx+1}\models\varphi(a,0)$, which is impossible.
\end{proof}

By Theorem~\ref{thm:uniformsep1}~(b), uniform separator existence is polytime reducible to $L$-validity. 
We next discuss the case of modal logics with nominals. We first note a straightforward extension of Theorem~\ref{thm:uniformsep1} to signatures $\sigma$ with \emph{finite} $\sigma_{c} \ne \emptyset$:

\begin{theorem}\label{thm:uniformsep2}
Let $L$ and $\LS$ be any pair of modal logics with nominals from Table~\ref{table:results}. Let $\sigma$ be a signature with finite $\sigma_{c} \ne \emptyset$. Then conditions $(a)$--$(d)$ of Theorem~\ref{thm:uniformsep1} with $\Flat$ replaced by $\Flat_{\sigma_{c}}$ are equivalent to each other.
\end{theorem}

We illustrate Theorem~\ref{thm:uniformsep2} by an example.

\begin{example}\em 
	%Observe that also restricted to finite signatures, the size of the signature matters for uniform separator existence.
	Suppose $\sigma_{c}=\emptyset$ and consider the $\GMLn$-formula $\varphi=\Diamond_{R}A \wedge \Diamond_{S}A \wedge (\Diamond_{R}^{\geq 2}A \leftrightarrow \Diamond_{S}^{\geq 2}A)$. Then $\Flat(\varphi)\equiv \Diamond_{R}A \wedge \Diamond_{S}A$, $\varphi\models \Flat(\varphi)$, and so $\Flat(\varphi)$ is a uniform $\MLn(\sigma)$-separator for $\varphi$.
	% 
	However, if $\sigma_{c} = \{c_1,c_2\}$, then $\varphi \models \neg\Flat_{\sigma_{c}}(\varphi)$ as shown below,\\
%
\centerline{
%\includegraphics[scale=0.6]{../Pics/GL3-2'}
%
\begin{tikzpicture}[>=latex,line width=0.5pt,xscale = 1,yscale = 1]
\node[point,scale = 0.5,label=above:{\footnotesize $\varphi$},label=below:{\footnotesize $\neg\Flat_{\sigma_{c}}(\varphi)$}] (0) at (0,0) {};
\node[point,scale = 0.5,label=right:{\footnotesize $A$}] (2) at (1.5,0.5) {};
\node[point,scale = 0.5,label=right:{\footnotesize $A$},label=above:{\footnotesize $N_{c_1},N_{c_2}$}] (1) at (1.5,-0.5) {};
\draw[->,below] (0) to node[] {\scriptsize $S$} (1);
\draw[->,above] (0) to node[] {\scriptsize $R$} (2);
