}
%
\\
%%	
%\centerline{\includegraphics[scale=0.5]{../mod-ex}}\\
	%
	and so there is no uniform $\MLn(\sigma)$-separator for $\varphi$. \hfill $\dashv$
\end{example}

Finally, we consider the case when the set $\sigma_{c}$ of constants in $\sigma$ is infinite. We write $\varphi\models_{\it fin}\psi$ if 
$\Amf\models \varphi(a)$ implies $\Amf\models \psi(a)$, for all \emph{finite} pointed $\sigma$-structures $\Amf,a$. Note that $\varphi\models_{\it fin}\psi$ iff $\varphi\models\psi$, for all counting-free logics considered in this paper and also for $\GML$,
$\GMLn$, $\GMLu$, and $\GMLnu$ because these logics enjoy the \emph{finite model property} (FMP). All other logics we deal with here do not have the FMP~\cite{handbookDL,Pratt23book}.

\begin{restatable}{theorem}{thmuniformsepthree}\label{thm:uniformsep3}
Let $L$ and $\LS$ be any pair of modal logics with nominals from Table~\ref{table:results}. Let $\sigma$ be a signature with $\sigma_{c}$ infinite and $\sigma_{0}\subseteq \sigma_c$ finite, non-empty, and containing all constants in an $L(\sigma)$-formula $\varphi$. Then the following conditions are equivalent\textup{:}
	%
	\begin{enumerate}
		\item[$(a)$] $\varphi$ has a  uniform $\LS(\sigma)$-separator\textup{;}

		\item[$(b)$] $\Flat_{\sigma_{0}}(\varphi)$ is a uniform $\LS(\sigma)$-separator for $\varphi$\textup{;}

		\item[$(c)$] $\varphi\models\Flat_{\sigma_{0}}(\varphi)$ and $\Flat_{\sigma_{0}}(\varphi)\models_{\it fin} \varphi$.		
	\end{enumerate}
\end{restatable}
%
\begin{proof}
	We sketch the proof of (b) $\Rightarrow$ (c) for $\GMLinu/\MLinu$. $(c) \Rightarrow (b)$ is straightforward and $(a) \Leftrightarrow (b)$ is shown using Theorem~\ref{thm:uniformsep2}. Observe that, for a finite pointed $\sigma_{f}$-structure $\Amf,a$ with finite $\sigma_{f}$, one can construct an $\MLinu(\sigma)$-formula $\text{diag}_{\sigma_{f}}(\Amf,a)$ with fresh constants for elements of $\dom(\Amf)$ such that $(i)$ if $\Bmf\models \text{diag}_{\sigma_{f}}(\Amf,a)(b)$, then $\Amf,a \cong_{\sigma_{f}}\Bmf,b$ and $(ii)$ by interpreting the fresh constants in $\text{diag}_{\sigma_{f}}(\Amf,a)$ as elements of $\dom(\Amf)$,
	$\Amf'\models \text{diag}_{\sigma_{f}}(\Amf,a)(a)$ for the resulting structure $\Amf'$.
	Now suppose $\Flat_{\sigma_{0}}(\varphi)$ is a uniform $\LS(\sigma)$-separator for $\varphi$. By definition,
	% Then clearly it is the uniform $\LS(\sigma')$-separator for $\varphi$ with $\sigma'$ obtained %from $\sigma$ by dropping all constants not in $\sigma_{0}$. By Theorem~\ref{thm:uniformsep2},
	$\varphi\models\Flat_{\sigma_{0}}(\varphi)$. To show 
	$\Flat_{\sigma_{0}}(\varphi)\models_{\it fin}\varphi$, assume this is not the case and  there is a finite pointed $\sig(\varphi)\cup\sigma_{0}$-structure $\Amf,a$ with $\Amf\models \Flat_{\sigma_{0}}(\varphi)(a)$ but
	$\Amf\not\models \varphi(a)$. 
	%We may assume that $\Amf$ is a $\sig(\varphi)\cup\sigma_{0}$-structure. 
	Then $\varphi\models \neg \text{diag}_{\sigma_{f}}(\Amf,a)$ for $\sigma_{f}= \sig(\varphi)\cup\sigma_{0}$.
	By the definition of uniform separators, we have $\Flat_{\sigma_{0}}(\varphi)\models\neg \text{diag}_{\sigma_{f}}(\Amf,a)$. But then $\Amf\not\models \Flat_{\sigma_{0}}(\varphi)(a)$, which is a contradiction.  
\end{proof}

It follows that, for the pairs $L/\LS$ considered in Theorem~\ref{thm:uniformsep3}, uniform $\LS(\sigma)$-separator existence for $\sigma$ containing infinitely many constants reduces in polytime to finite and general $L$-validity. For logics $L$ with the FMP, it follows from Theorem~\ref{thm:uniformsep3} that uniform $\LS$-separator existence and $\LS$-definability coincide. For $L$ without the FMP, this is not the case.

