& \varphi'(x) ~=~ \varphi(x) \land \hspace*{-2mm} \bigwedge_{A \in \sig(\psi) \setminus \sig(\varphi)} \hspace*{-6mm} \big( A(x) \to A(x) \big) \land{} \\ 
&\hspace*{2.2cm} \bigwedge_{R \in \sig(\psi) \setminus \sig(\varphi)} \hspace*{-6mm} \big( R(x,x) \to R(x,x) \big) \land \hspace*{-2mm} \bigwedge_{c \in \sig(\psi) \setminus \sig(\varphi)} \hspace*{-6mm} (c=c),\\
& \psi'(x) ~=~ \psi(x) \land \hspace*{-2mm} \bigwedge_{A \in \sig(\varphi) \setminus \sig(\psi)} \hspace*{-6mm} \big( A(x) \to A(x) \big) \land{} \\ 
& \hspace*{2.2cm}\bigwedge_{R \in \sig(\varphi) \setminus \sig(\psi)} \hspace*{-6mm} \big( R(x,x) \to R(x,x) \big) \land \hspace*{-2mm} \bigwedge_{c \in \sig(\varphi) \setminus \sig(\psi)} \hspace*{-6mm} (c=c).
\end{align*}
%
Then $\varphi(x)$ and $\psi(x)$ are $L/\LS$-separable iff $\varphi'(x)$ and $\psi'(x)$ are Craig $L/\LS$-separable, and so unary Craig separable. 
% 
If $L$ is a modal logic, we take $\Diamond_R \top \to \Diamond_R \top$ and $N_c \to N_c$ in the last two conjuncts of $\varphi'(x)$ and $\psi'(x)$.

For the second claim, let $\Amf$ be a $\sigma$-structure. For a non-empty set $D\subseteq \dom(\Amf)$, denote by $\Amf_{|D}$ the \emph{restriction} of $\Amf$ to $D$ defined by taking $\dom(\Amf_{|D})=D$ and by relativising all predicates in $\sigma$ to $D$, that is,  by setting $(a_{1},\dots,a_{n})\in R^{\Amf_{|D}}$ iff $a_{1},\dots,a_{n}\in D$ and $(a_{1},\dots,a_{n})\in R^{\Amf}$, for all $a_{1},\dots,a_{n}\in \dom(\Amf)$ and all $R\in \sigma$. If $\sigma$ contains constants $c$, we demand that $c^{\Amf} \in D$ and set $c^{\Amf_{|D}} = c^{\Amf}$.
% 
We remind the reader that the \emph{relativisation} $\varphi_{|A}(x)$ of a formula $\varphi(x)$ to a unary predicate $A \notin \sig(\varphi)$  has the following property \cite{modeltheory}: for all structures $\Amf$ and all $a\in \dom(\Amf)$, 
%
\begin{itemize}
\item[--] $\Amf\models \varphi_{|A}(a)$ implies  $A^{\Amf}\ne \emptyset$;

\item[--] $\Amf\models \varphi_{|A}(a)$ iff $\Amf_{|A^{\Amf}}\models \varphi(a)$.
\end{itemize}
%
For a $\CT$-formula $\varphi(x)$, its $\CT$-relativisation $\varphi(x)_{|A}$ is constructed in polynomial time. 

We are now in a position to give the reduction
for $\CT/\FOT$. Assume $\varphi(x)$ and $\psi(x)$ in $\CT$ are given. Let $A_{1},\ldots, A_{n}$ be the unary predicate symbols that either occur in $\varphi$ and not in $\psi$ or vice versa. Let $\varrho=(\sig(\varphi) \cup \sig(\psi))\setminus \{A_{1},\dots,A_{n}\}$. Let
$U$ be a fresh unary predicate symbol and $R$ a fresh binary predicate symbol.
Let $\varphi_{|U}$ and $\psi_{|U}$ be the relativisations of $\varphi$ and $\psi$ to $U$.
Consider the formulas $\varphi'$ and $\psi'$ obtained by 
%adding the conjuncts 
%$$
%\blacksquare (U \rightarrow \Diamond_{R}^{\geq 1}\neg %U)
%$$
%$$
%\blacksquare (\neg U \rightarrow (\Box_{R}\neg U %\wedge \Diamond_{R}^{\geq 1}\top))
