replacing in $\varphi_{|U}$ and $\psi_{|U}$ every occurrence of $A_{i}$ by a formula $\varphi_{A_{i}}$ stating that there is an $R$-chain of length $i$ with the final node having exactly two $R$-successors. In $\GML$ terms,
%
$$
\varphi_{A_{i}} = \underbrace{\Diamond_{R} \dots \Diamond_{R}}_{i} \Diamond_{R}^{=2}\top.
$$
%
Let $\tau=\sig(\varphi')\cup \sig(\psi')$. By Lemma~\ref{criterion}, it suffices to show that the following conditions are equivalent:
%
\begin{enumerate}
\item there exist $\Amf,a$ and $\Bmf,b$ such that \mbox{$\Amf\models \varphi(a)$}, $\Bmf\models \psi(b)$, and $\Amf,a\sim_{\FOT(\varrho)}\Bmf,b$;

\item there exist $\Amf',a'$ and $\Bmf',b'$ such that $\Amf'\models \varphi'(a')$, \mbox{$\Bmf'\models \psi'(b')$}, and $\Amf',a'\sim_{\FOT(\tau)}\Bmf',b'$. 
\end{enumerate}
%
For the implication $(1) \Rightarrow (2)$, suppose  
$\Amf\models \varphi(a)$, $\Bmf\models \psi(b)$ and $\Amf,a\sim_{\FOT(\varrho)}\Amf,b$.
Define $\Amf',a'$ and $\Bmf',b'$ as follows: the domain of
$\Amf'$ contains $\dom(\Amf)$ and, for every $d\in \dom(\Amf)$,  mutually disjoint sets $A_{d}$ we define later.
We set $a'=a$. Similarly, the domain of
$\Bmf'$ contains $\dom(\Bmf)$ and, for every $d\in \dom(\Bmf)$,  mutually disjoint sets $B_{d}$ to be defined later. Set $b'=b$.
The symbols in $\varrho$ are interpreted in $\Amf'$ and $\Bmf'$ exactly as in $\Amf$ and $\Bmf$, respectively. Set $U^{\Amf'}=\dom(\Amf)$ and $U^{\Bmf'}=\dom(\Bmf)$.
It remains to interpret $R$. We interpret $R$ in $\Amf'$ in such a way that, for $d\in \dom(\Amf)$, we have $\Amf\models A_{i}(d)$ iff $\Amf'\models \varphi_{A_{i}}(d)$, for $i=1,\dots,n$. Hence, we use the additional points in $A_{d}$ as the domain of an $\{R\}$-structure $\Amf_{d}$ consisting of $n$-many $R$-chains all starting at $d$, with the $i$th $R$-chain having length $i$ and such that its final node has \emph{two} $R$-successors if $d\in A_{i}^{\Amf}$ and \emph{three} $R$-successors if $d\not\in A_{i}^{\Amf}$. For $d\in \dom(\Amf)$, the $\Amf_{d}$ are hooked to $\Amf$ at $d$ to obtain $\Amf'$. Observe that we have  $\Amf_{d}\models \varphi_{A_{i}}(d)$ iff $\Amf\models A_{i}(d)$, for $i=1,\dots,n$, and that $\Amf_{d},d\sim_{\FOT(\{R\})}\Amf_{d'},d'$, for any $d,d'\in \dom(\Amf)$, since $\FOT$ cannot distinguish between nodes having two or three $R$-successors.
The interpretation of $R$ in $\Bmf'$ is analogous.

It follows that $\Amf'\models \varphi'(a')$ and $\Bmf'\models \psi'(b')$. Moreover, any $\bis$ witnessing $\Amf,a\sim_{\FOT(\varrho)}\Bmf,b$ can be extended to a $\bis'$ witnessing $\Amf',a'\sim_{\FOT(\tau)}\Bmf',b'$ 
in a straightforward manner.

For $(2) \Rightarrow (1)$, assume that 
$\Amf'\models \varphi'(a')$, $\Bmf'\models \psi'(b')$, and $\Amf',a'\sim_{\FOT(\tau)}\Bmf',b'$. 
Let $\Amf=\Amf'_{|U^{\Amf'}}$ be expanded by setting 
%
$$
A_{i}^{\Amf}=\{d\in U^{\Amf'}\mid \Amf'\models \varphi_{A_{i}}(d)\},
$$
%
for $i=1,\dots,n$, and let $\Bmf =\Bmf'_{|U^{\Bmf'}}$ be expanded by setting 
%
$$
A_{i}^{\Bmf}=\{d\in U^{\Bmf'}\mid \Bmf'\models \varphi_{A_{i}}(d)\},
$$
%
for $i=1,\dots,n$. Let $a=a'$ and $b=b'$. By construction, we have $\Amf\models \varphi(a)$ and $\Bmf\models \psi(b)$. Moreover, let $\bis$ be a bisimulation witnessing $\Amf',a'\sim_{\FOT(\tau)}\Bmf',b'$. Then the restriction of $\bis$ to $U^{\Amf'}\times U^{\Bmf'}$ witnesses $\Amf,a\sim_{\FOT(\varrho)}\Bmf,b$. 

The polynomial reduction given above works for all pairs $\CT/\LS$ with $\LS \in \{\MLiu,\MLi,\MLu,\ML\}$ since the formulas $\varphi_{A_{i}}$ are in $\CT$.

Next consider $\GMLinu/\MLinu$. As before, we can construct the relativisation $\varphi_{|A}$ of a $\GMLinu$-formula $\varphi$ in $\GMLinu$ to a propositional variable $A$. To ensure that all nominals are interpreted in the relativised structure, we add to $\varphi_{|A}$ the conjunct $\Du (N_{c} \wedge A)$ for $c\in \sig(\varphi) \cup \sig(\psi)$. With this amendments, the proof above works for $\GMLinu/\LS$ and all $\LS\in \{\MLiu,\MLin,\MLnu,\MLu,\MLi,\MLn,\ML\}$.

The proof for the relevant pairs $\GMLiu/\LS$, $\GMLnu/\LS$, $\GMLu/\LS$, $\GMLi/\LS$, and $\GML/\LS$ is a straightforward modification of the proof above.

For the relevant pairs of the form $\GMLin/\LS$ and $\GMLn/\LS$, some care is required since one cannot now ensure that nominals are interpreted in the relativised structure by adding $\Du(N_{c} \wedge U)$ as a conjunct to $\varphi_{|U}$.
%In contrast, we now do not demand that nominals denote in relativised structures but add, 
Instead, when constructing $\Amf$ and $\Bmf$ from $\Amf'_{|U^{\Amf'}}$ and $\Bmf'_{|U^{\Bmf'}}$ in the proof of $(2) \Rightarrow (1)$, we add new elements to the domains of $\Amf$ and $\Bmf$ to interpret the nominals not yet interpreted in $\Amf'_{|U^{\Amf'}}$ and $\Bmf'_{|U^{\Bmf'}}$.
\end{proof}


The following criterion of relative definability is proved similarly to Lemma~\ref{criterion}:

\begin{lemma}\label{p:pbdpsem}
For any relevant pair $L/\LS$, any $L(\sigma)$-formulas $\varphi(x)$, $\psi(x)$ and any $\varrho \subseteq \sigma$, the following conditions are equivalent\textup{:}
%
\begin{itemize}
\item[--]
there is no explicit $\LS(\varrho)$-definition of $\psi$ modulo $\varphi$\textup{;}

\item[--] there are pointed $\sigma$-structures $\Amf,a$ and $\Bmf,b$ such that 
%
$$
\Amf\models (\varphi \land \psi)(a), \quad \Bmf\models (\varphi \land \neg\psi)(b), \quad \Amf,a \sim_{\LS(\varrho)} \Bmf,b.
$$
%
\end{itemize}
\end{lemma}

\thmequivdef*
%
\begin{proof}
We only consider modal logics $L$ and $\LS$; the first-order case is similar. Let $\varrho \subseteq \sigma$. We show that an  $L$-formula $\psi$ has an explicit $\LS(\varrho)$-definition modulo $\varphi$ in $L$ iff the formulas $\varphi \land \psi$ and $\varphi^\varrho \land\neg \psi^\varrho$ have a Craig $L/\LS$-separator, where $\varphi^\varrho$, $\psi^\varrho$ are obtained by replacing each variable $A \notin \varrho$ with a fresh variable $A^\varrho$ (cf.~\cite{MGabbay2005-MGAIAD}). Indeed, suppose first that $\chi$ is an $\LS(\varrho)$-formula with $\varphi \models \psi\leftrightarrow\chi$. Let $\chi'$ be the result of replacing every variable in $\chi$ that does not occur in $\sig(\varphi \land \psi)$ by $\top$, so $\sig(\chi') \subseteq \sig(\varphi \land \psi) \cup \sig(\varphi^\varrho \land \psi^\varrho)$. We clearly still have $\varphi \models \psi\leftrightarrow\chi'$, and so $\varphi \land \psi \models \chi'$ and $\chi' \models \varphi \to \psi$. The latter implies $\chi' \models \varphi^\varrho \to \psi^\varrho$ and $\chi' \models \neg(\varphi^\varrho \land \neg \psi^\varrho)$. Therefore, $\chi'$ is a Craig $L/\LS$-separator for $\varphi \land \psi$ and $\varphi^\varrho \land\neg \psi^\varrho$. 
%
Conversely, it is readily seen that any Craig $\LS$-separator of $\varphi \land \psi$ and $\varphi^\varrho \wedge\neg \psi^\varrho$ is an explicit $\LS(\varrho)$-definition of $\psi$ modulo $\varphi$.

For the other reduction, we observe first that the decision problem for $L$ is polynomial time reducible to relative $L/\LS$-definability: for $\psi = A \notin \sig(\varphi)$ and $\varrho = \emptyset$, we have $\models \neg \varphi$ iff there is an explicit $\LS(\varrho)$-definition of $\psi$ modulo $\varphi$.
%
We show now that $L$-formulas $\varphi$ and $\neg\psi$ have a Craig $L/\LS$-separator iff $\models \varphi\to \psi$ and there is an $\LS(\sig(\varphi) \cap \sig(\psi))$-definition of $\psi$ modulo $\psi \to \varphi$. 

Indeed, if $\chi$ is a Craig $L/\LS$-separator for $\varphi$ and $\neg\psi$, then we have $\sig(\chi) \subseteq \sig(\varphi) \cap \sig(\psi)$, $\varphi \models \chi$ and $
\chi \models \psi$. It follows that $\models \varphi \to \psi$ and $\psi \to \varphi \models \psi \leftrightarrow \chi$, which means that $\chi$ is an $\LS(\sig(\varphi) \cap \sig(\psi))$-definition of $\psi$ modulo $\psi \to \varphi$. Conversely, suppose $\models \varphi \to \psi$ but $\varphi$ and $\neg \psi$ do not have a Craig $L/\LS$-separator. By Lemma~\ref{criterion}, there are structures $\Amf,a$ and $\Bmf,b$ such that $\Amf\models\varphi(a)$, $\Bmf\models\neg\psi(b)$ and $\Amf,a \sim_{\LS(\varrho)} \Bmf,b$. But then $\Amf\models ((\psi\to\varphi)\land\psi)(a)$ and $\Bmf \models ((\psi\to\varphi)\land\neg\psi)(b)$, and so, by Lemma~\ref{p:pbdpsem}, there is no explicit $\LS(\varrho)$-definition of $\psi$ modulo $\psi \to \varphi$.
\end{proof}

