As in Section~\ref{sec:gmlu}, we are going to use mosaics for building  the structures $\Amf_{1}$ and $\Amf_{2}$ we are after. To this end, we require the following definition. Let $M=(M_{1},M_{2})$ be a mosaic and $\mathcal{M}$ a set of mosaics. Set $\Delta=\Delta_{1}\cup \Delta_{2}$ and $\Gamma=\Gamma_{1} \cup \Gamma_{2}$, where, for $i=1,2$,
%
\begin{align*}
& \Delta_{i} = \{(\ftype,j)\mid j<\omega ,\ \ftype\in M_{i}\},\\ 
&\Gamma_{i} = \{(\ftype',j',M')\mid j<\omega,\ \ftype'\in M_{i}',\ M'=(M_{1}',M_{2}')\in \mathcal{M}\}.
\end{align*}
%
Intuitively, $\Delta_i$ consists of $\omega$-many copies of each star-type in $M_i$, and $\Gamma_i$ of $\omega$-many copies of each `pointed mosaic' $(\ftype',M')$ in $\mathcal{M}$.

We call $\mathcal{M}$ a \emph{witness} for $M$ if, for each $S$, there is a relation
%
$$
S^{M,\mathcal{M}} \subseteq (\Delta_{1} \times \Gamma_{1})\cup (\Delta_{2} \cup \Gamma_{2})
$$
%
such that the following conditions are satisfied:
%
\begin{description}
\item[(witness$_1$)] if $(\ftype,j)\in \Delta$, $\ftype=(\type,\frak{s}_{p},\frak{s}_{c})$ and $\Diamond_{S}^{=n}\type'\in \frak{s}_{c}$, then $(\ftype,j)$ has exactly $n$ different $S^{M,\mathcal{M}}$-successors of type $\type'$---i.e., of the form $((\type',\frak{s}_{p}',\frak{s}_{c}'),j',M')$---in $\Gamma$; if $\Diamond_{S}^{>\mx}\type'\in \frak{s}_{c}$, then $(\ftype,j)$ has at least $\mx+1$ different $S^{M,\mathcal{M}}$-successors of type $\type'$ in $\Gamma$;

%\item[(witness$_2$)] if $(\ftype,j)\in \Delta$, $\ftype=(\type,\frak{s}_{p},\frak{s}_{c})$ and $\Diamond_{S}^{>\mx}\type'\in \frak{s}_{c}$, then $(\ftype,j)$ has at least $\mx+1$ different $S^{M,\mathcal{M}}$-successors of type $\type'$ in $\Gamma$;

\item[(witness$_2$)] if $(\ftype',k,M')\in \Gamma$, $\ftype'= (\type',\frak{s}_{p}',\frak{s}_{c}')$ and $\Diamond_{S}^{=n}\type\in \frak{s}_{p}'$, then $(\ftype',k,M')$ has exactly $n$ $S^{M,\mathcal{M}}$-successors of type $\type$ in $\Delta$; if $\Diamond_{S}^{>\mx}\type\in \frak{s}_{p}'$, then $(\ftype',k,M')$ has $> \mx$  $S^{M,\mathcal{M}}$-successors of type $\type$ in $\Delta$;

%\item[(witness$_4$)] if $(\ftype',k,M')\in \Gamma$, $\ftype'=(\type',\frak{s}_{p}',\frak{s}_{c}')$ and $\Diamond_{S}^{>\mx}\type\in \frak{s}_{p}'$, then $(\ftype',k,M')$ has $> \mx$  $S^{M,\mathcal{M}}$-successors of type $\type$ in $\Delta$;

\item[(bisim$_1$)] if $R\in \varrho$, $S \in \{R,R^-\}$ and some element of $\Delta$ has an $S^{M,\mathcal{M}}$-successor $(\ftype',j',M') \in \Gamma$, then every element of $\Delta$ has an $S^{M,\mathcal{M}}$-successor of the form $(\ftype'',j'',M') \in \Gamma$;

\item[(bisim$_2$)] if $R\in \varrho$, $S \in \{R,R^-\}$ and some $(\ftype',j',M') \in \Gamma$ is an $S^{M,\mathcal{M}}$-successor of an element of $\Delta$, then all $(\ftype'',j'',M')$ in $\Gamma$ are  $S^{M,\mathcal{M}}$-successors of some element of $\Delta$.
\end{description}

