Our aim is to show that there exist pointed structures $\Amf_{i},a_{i}$, $i=1,2$,  satisfying $\varphi_{i}$ with $\Amf_{1},a_{1}\sim_{\MLiu(\varrho)}\Amf_{2},a_{2}$ iff there exists a set $\mathfrak{S}$ of mosaics such that
%
\begin{description}
\item[(m1)] if $M=(M_{1},M_{2})\in \mathfrak{S}$, then $M_{1}\not=\emptyset$ and $M_{2}\not=\emptyset$;

\item[(m2)] there are a root mosaic $M=(M_{1},M_{2})\in \mathfrak{S}$ and star-types $\ftype_{i}\in M_{i}$ containing $\varphi_{i}$ in their types, for $i=1,2$;

\item[(m3)] every $M\in \mathfrak{S}$ has a witness $\mathcal{M}\subseteq \mathfrak{S}$;

\item[(m4)] if $\Du\chi\in \type$ for some $(\type,\frak{s}_{p},\frak{s}_{c})\in M_{i}$ and $M=(M_{1},M_{2})\in \mathfrak{S}$, then there exists a root mosaic $M'=(M_{1}',M_{2}')\in \mathfrak{S}$ such that $\chi\in \type'$ for some $(\type',\frak{s}_{p}',\frak{s}_{c}')\in M_{i}'$ such that $\type$ and $\type'$ are $\Du$-equivalent, for $i=1,2$.
\end{description}
%
Moreover, we also aim to show that it suffices to look for $\mathfrak{S}$ with mosaics and witnesses of exponential size, which would make it possible to check the existence of such an $\mathfrak{S}$ in double exponential size. With this in mind, we first give a somewhat different, but equivalent `syntactic' definition of witnesses.

We say that star-types $\ftype=(\type,\frak{s}_{p},\frak{s}_{c})$ and $\ftype'= (\type',\frak{s}_{p}',\frak{s}_{c}')$ are \emph{$S$-coherent} and write $\ftype \rightsquigarrow_{S} \ftype'$ if $\Diamond_{S}^{>0}\type'\in \frak{s}_{c}$ and $\Diamond_{S^{-}}^{>0}\type\in \frak{s}'_{p}$.
%Intuitively, $S$-coherence captures that we can draw an $S$-edge between a node representing $\ftype$ and a node representing $\ftype'$. \nz{better words?}
%
Let $M=(M_{1},M_{2})$ be a mosaic, $\mathcal{M}$ a set of mosaics and 
%
$$
\mathcal{M}_{i}^{\bullet}= \{(\ftype',M')\mid M'=(M_{1}',M_{2}')\in \mathcal{M}, \ftype'\in M_{i}'\}, \quad i=1,2. 
$$
%
Call $\mathcal{M}$ is a \emph{syntactic witness} for $M$ if, for every $S$, there is a relation 
%
$$
\S^{M,\mathcal{M}} \subseteq (M_{1}\times \mathcal{M}_{1}^{\bullet}) \cup (M_{2}\times \mathcal{M}_{2}^{\bullet})
$$
%
satisfying the following conditions, for $i=1,2$:
%
\begin{description}
\item[(coherence)] if $(\ftype, (\ftype',M'))\in \S^{M,\mathcal{M}}$, then $\ftype \rightsquigarrow_{S} \ftype'$;

\item[(bisim)] if $R\in \varrho$, $S \in \{R,R^-\}$, and $M'=(M_{1}',M_{2}')\in \mathcal{M}$, then either
%
\begin{itemize}
\item[--] for any $\ftype\in M_{i}$, there is $\ftype'\in M_{i}'$ with $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$ and, for any $\ftype'\in M_{i}'$, there is $\ftype\in M_{i}$ with $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$,
\end{itemize}
%
in which case $M'$ is called an \emph{$S$-successor of $M$},  
or 
%
\begin{itemize}
\item[--] $(\ftype,(\ftype',M'))\notin \S^{M,\mathcal{M}}$ for any $\ftype\in M_{i}$ and $\ftype'\in M_{i}'$;
\end{itemize}

\item[(wit$_1$)] if $\ftype=(\type,\frak{s}_{p},\frak{s}_{c}) \in M_{i}$ and $\Diamond_{S}^{>0}\type'\in \frak{s}_{c}$, then there are $M'=(M_{1}',M_{2}')\in \mathcal{M}$ and 
$\ftype'=(\type',\frak{s}_{p}',\frak{s}_{c}')\in M_{i}'$ such that 
$(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$;
	%	\item for every $(t,E)\in M$, if $(=n st')\in E_{down}$, then there are at most $n$ different $E'$ and $M'$ such that $((t,E),((t',E'),M'))\in s$,

\item[(wit$_2$)] if $M'=(M_{1}',M_{2}')\in \mathcal{M}$, $\ftype'=(\type',\frak{s}_{p}',\frak{s}_{c}')\in M_{i}'$ and $\Diamond_{S^{-}}^{>0}\type\in \frak{s}_{p}'$, then there is $\ftype=(\type,\frak{s}_{p},\frak{s}_{c})\in M_{i}$ with $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$;

\item[(wit$_3$)] if $R\in \varrho$, $S \in \{R,R^-\}$ and $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$, where $\ftype=(\type,\frak{s}_{p},\frak{s}_{c})\in M_{i}$, then there is a function $g$ that assigns to each $S$-successor $M^*=(M_{1}^*,M_{2}^*)$ of $M$ in $\mathcal{M}$ a star-type in $M_{i}^*$ such that $g(M')= \ftype'$ and, for any $\Diamond_{S}^{=n}\type_1\in \frak{s}_{c}$, we have 
%
$$
|\{M^*\in \mathcal{M}\mid g(M^*)=(\type_1,\frak{s}_{p}^*,\frak{s}_{c}^*), \text{ for some } \frak{s}_{p}^*,\frak{s}_{c}^*\}|\leq n. 
$$
\end{description}

The intuition behind the concept of a syntactic witness is as follows. If $\mathcal{M}$ is a witness for $M$, then for every $\ftype = (\type,\frak{s}_p,\frak{s}_c)\in M_1\cup M_2$, if $\Diamond^{=n}_S\type'\in \frak{s}_c$ then we require $(\ftype,j)$ to be $S^{M,\mathcal{M}}$-related to exactly $n$ different star-types based on type $\type'$. A similar constraint holds for $(\ftype',\frak{s}_p',\frak{s}_c')\in M_1'\cup M_2'$, where $(M_1',M_2')\in \mathcal{M}$. For a syntactic witness, we relax this requirement: if $\Diamond^{=n}_S\type'\in \frak{s}_c$ for some $n>0$ we do require $\ftype$ to be $\S^{M,\mathcal{M}}$-related to at least one star-type that is based on $\type'$, but we do not require there to be exactly $n$. The reason for this relaxation is that we can create multiple copies of each star-type: if, say, $\Diamond^{=2}_S\type'\in \frak{s}_c$ and $\ftype$ is $\S^{M,\mathcal{M}}$-related to exactly one $(\ftype',M')$, where $\ftype'$ is based on type $\type'$, then every $(\ftype,j)$ will be $S^{M,\mathcal{M}}$-related to $(\ftype',j_1',M')$ and $(\ftype,j_2',M')$ with $j_1'\neq j_2'$.

	Similarly, if $\Diamond^{=1}_S\type'\in \frak{s}_c$ and $\ftype$ is $\S^{M,\mathcal{M}}$-related to both $(\ftype',M')$ and $(\ftype'',M'')$, where $\ftype'$ and $\ftype''$ are based on type $\type'$, then there will be different $j_1$ and $j_2$ such that $(\ftype,j_1)$ is $S^{M,\mathcal{M}}$-related to $(\ftype',j',M')$ and $(\ftype,j_2)$ is $s^{M,\mathcal{M}}$-related to $(\ftype'',j'',M'')$.

	Such copying does, of course, require there to be at least one $\S^{M,\mathcal{M}}$-successor when $\Diamond^{>0}_S\type'\in \frak{s}_c$. This is enforced by \textbf{(wit$_1$)}, while \textbf{(wit$_2$)} is the corresponding requirement for $\Diamond^{>0}_S\type\in \frak{s}_p'$. 

	There is one other requirement, however, that is slightly harder to explain. Suppose that $\Diamond^{=1}\type'\in \frak{s}_c$ and that $(\ftype,(\ftype_1',M')), (\ftype, (\ftype_2',M''))\in \S^{M,\mathcal{M}}$, where $\ftype_1'$ and $\ftype_2'$ are both based on $\type'$ and $M'\neq M''$. Suppose furthermore that $\ftype_1'$ and $\ftype_2'$ are the only $\S^{M,\mathcal{M}}$-successors of $\ftype$ in their respective mosaics. If we were to try to create a witness $S^{M,\mathcal{M}}$ from this $\S^{M,\mathcal{M}}$, we would take $((\ftype,j),(\ftype_1',j_1',M'))\in S^{M,\mathcal{M}}$ and $((\ftype,j),(\ftype_2',j_2',M''))\in S^{M,\mathcal{M}}$. But there would be no $\ftype_2''$ and $j_2''$ such that $((\ftype,j),(\ftype_2'',j_2'',M''))\in S^{M,\mathcal{M}}$ and no $\ftype_1''$ and $j_1''$ such that $((\ftype,j),(\ftype_1'',j_1'',M'))\in S^{M,\mathcal{M}}$. Therefore, the \textbf{(bisim$_1$)} condition would not be satisfied.

	In order to prevent this kind of situation, we must ensure that if $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$, then there is some way to choose $\ftype',M'$ as a successor of $\ftype$ that respects both graded modalities and bisimulation restrictions. This means it must be possible to choose one $\ftype''$ per $S$-successor $M''$ of $M$ such that (i) for the mosaic $M'$ we choose $\ftype'$ and (ii) if $\Diamond^{=n}_S\type''\in \frak{s}_c$ then we choose at most $n$ star-types based on type $\type''$. In our definition of a syntactic witness, this requirement is included as \textbf{(wit$_3$)}.

	Now that we have explained the intuition behind syntactic witnesses, we can show that syntactic witnesses are witnesses, and vice versa.

\begin{lemma}\label{lem:syntactic witness1} 
$\mathcal{M}$ is a witness for $M$ iff $\mathcal{M}$ is a syntactic witness for $M$.
\end{lemma}
%
\begin{proof}
	$(\Rightarrow)$ Suppose $\mathcal{M}$ is a witness for $M=(M_1,M_2)$ and, for each $S$, let $S^{M,\mathcal{M}}$ be the witnessing relation with respect to $S$. Let $\S^{M,\mathcal{M}}$ be the relation given by $(\ftype,(\ftype',M')\in \S^{M,\mathcal{M}}$ iff there are $j,j'$ such that $((\ftype,j),(\ftype',j',N'))\in S^{M,\mathcal{M}}$. 
	%Because $S^{M,\mathcal{M}}$ satisfies 

	We show that $\S^{M,\mathcal{M}}$ satisfies the conditions for $\mathcal{M}$ being a syntactic witness for $M$.
	\begin{description}
		\item[(coherence)] Suppose that $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$, where $\ftype=(\type,\frak{s}_p,\frak{s}_c)$ and $\ftype' = (\type',\frak{s}_p',\frak{s}_c')$. Then, by the definition of $\S^{M,\mathcal{M}}$, there are $j,j'$ such that $((\ftype,j),(\ftype',j',M'))\in S^{M,\mathcal{M}}$.

		By the \textbf{(witness$_1$)} condition, $((\ftype,j),(\ftype',j',M'))\in S^{M,\mathcal{M}}$ implies that $\Diamond^{=0}\type'\not\in \frak{s}_c$, and hence that $\Diamond^{>0}\type'\in \frak{s}_c$. Similarly, by \textbf{(witness$_2$)}, it implies that $\Diamond^{=0}_{S^-}\type\not\in \frak{s}'_p$, and hence $\Diamond^{>0}_{S^-}\type\in \frak{s}'_p$. This shows that $\ftype \rightsquigarrow_S \ftype'$, so the \textbf{(coherence)} condition is satisfied.

		\item[(bisim)] Consider any $M'=(M_1',M_2')\in \mathcal{M}$ and any $i\in \{1,2\}$. Assume $R\in \varrho$ and $S \in \{R,R^-\}$. We distinguish two cases. As a first case, suppose that there are $\ftype_1\in M_i$, $\ftype_1'\in M_i'$ and $j_1,j_1'<\omega$ such that $((\ftype_1,j_1),(\ftype_1',j_1',M_i')\in S^{M,\mathcal{M}}$. Then  \textbf{(bisim$_1$)} implies that for every $\ftype_2\in M_i$ and every $j_2<\omega$ there are $\ftype_2'\in M_i'$ and $j_2'<\omega$ such that $((\ftype_2,j_2),(\ftype_2',j_2',M')\in S^{M,\mathcal{M}}$. 

		So, for every such $\ftype_2$, there is a $\ftype_2'$ such that $(\ftype_2,(\ftype_2,M'))\in \S^{M,\mathcal{M}}$.
		Similarly, \textbf{(bisim$_2$)} implies that for every $\ftype_2'\in M_i'$ there is a $\ftype_2\in M_i$ such that $(\ftype_2,(\ftype_2,M'))\in \S^{M,\mathcal{M}}$. Hence, in this case $M'$ is an $S$-successor of $M$.

		As a second case, suppose there are no $\ftype_1\in M_i$, $\ftype_1'\in M_i'$ and $j_1,j_1'<\omega$ such that $((\ftype_1,j_1),(\ftype_1',j',M'))\in S^{M,\mathcal{M}}$. Then for every such $\ftype,\ftype'$ we have $((\ftype,(\ftype',M'))\not\in\S^{M,\mathcal{M}}$.

		These cases are exhaustive, so the \textbf{(bisim)} condition is satisfied.
		\item[(wit$_1$)] Suppose $\ftype = (\type,\frak{s}_p,\frak{s}_c)\in M_i$ and $\Diamond^0_S\type'\in \frak{s}_c$. Then, because $S^{M,\mathcal{M})}$ satisfies \textbf{(witness$_1$)}, every $(\ftype,j)$ has $>0$ $S^{M,\mathcal{M}}$-successors $(\ftype',j',M')$. Therefore, $(\ftype',M')$ is an $\S^{M,\mathcal{M}}$ successor of $\ftype$. Hence \textbf{(wit$_1$)} is satisfied.
		\item[(wit$_2$)] As with \textbf{(wit$_1$)}, except here we use the fact that $S^{M,\mathcal{M}}$ satisfies \textbf{(witness$_2$)}.
		\item[(wit$_3$)] Assume $R\in \varrho$ and $S \in \{R,R^-\}$. 
		Take any $(\ftype,(\ftype',M'))\in \S^{M,\mathcal{M}}$. Let $\ftype = (\type,\frak{s}_p,\frak{s}_c)\in M_i$. Fix any $j,j'<\omega$ such that $((\ftype,j),(\ftype',j',M'))\in S^{M,\mathcal{M}}$. For every $M^\ast=(M_1^\ast,M_2^\ast)\in \mathcal{M}$, we say that $M^\ast$ is an $S$-successor mosaic of $(\ftype,j)$ if there are $\ftype^\ast,j^\ast$ such that $((\ftype,j),(\ftype^\ast,j^\ast,M^\ast))\in S^{M,\mathcal{M}}$.

		Let $g$ be any function that (1) assigns to every $S$-successor mosaic $M^\ast$ of $(\ftype,j)$ an $\ftype^\ast$ such that there is a $j^\ast$ with $((\ftype,j),(\ftype^\ast,j^\ast,M^\ast))\in S^{M,\mathcal{M}}$ and (2) satisfies $g(M')=\ftype'$.

		As $S^{M,\mathcal{M}}$ satisfies \textbf{(witness$_1$)}, we have that if $\Diamond_S^{=n}\type'\in \frak{s}_C$ then there are at most $n$ mosaics $M^\ast$ such that $g(M^\ast)=\ftype^\ast = (t^\ast,\frak{s}^\ast_p,\frak{s}^\ast_c)$ for some $\frak{s}^\ast_p,\frak{s}^\ast_c$. Furthermore, because of the \textbf{(bisim$_1$)} condition, the set of $S$-successor mosaics does not depend on the choice of $j$.

		It follows that $g$ is a function that satisfies the requirements of \textbf{(wit$_3$)}, so that property is satisfied for $\S^{M,\mathcal{M}}$.
	\end{description}
	We have now shown that $\S^{M,\mathcal{M}}$ satisfies all of the conditions for $\mathcal{M}$ to be a syntactic witness of $M$.
	%Checking the implication $(\Rightarrow)$ is straightforward.\nz{some comments?}

	$(\Leftarrow)$ Suppose $\mathcal{M}$ is a syntactic witness for $M$ and the elements of $\Gamma\cup \Delta$ are enumerated. For $R\in \sigma$ and $S\in \{R,R^{-}\}$, let $\S^{M,\mathcal{M}}$ be the witnessing relation. We will create the relation $S^{M,\mathcal{M}}$ by adding $S$- and $S^-$-edges to elements $x\in \Delta\cup\Gamma$ in the enumeration order. Throughout the process, we keep invariant the property that, by the time we reach $x\in \Delta \cup \Gamma$, there is at most one $S$- or $S^{-1}$-edge to or from $x$ already. Four cases are possible. 

