\section*{Proofs for Section~\ref{sec:definability}}
%
We start by giving the precise recursive definition of the flattening $\Flat(\varphi)\in \FOTNE$ for $\CT$-formulas $\varphi$ without equality:
%  
\[\begin{array}{ll}
	\Flat(A(x))=A(x), & \Flat(R(x,y)) = R(x,y), \\
	\Flat(\exists^{\geq k}x \, \varphi)= \exists x \, \Flat(\varphi), & \Flat(\neg \varphi) = \neg \Flat(\varphi),\\
	\Flat(\varphi\wedge\varphi') = \Flat(\varphi)\wedge\Flat(\varphi'). & 
\end{array}\]
%
We require the following observation.
%
\begin{lemma}\label{lem:withoueq}
	Let $\sigma$ be constant-free and let $\kappa\in \mathbb{N}^{\infty}$. Then, for all $\FOTNE(\sigma)$-formulas $\psi_{1}(x)$ and $\psi_{2}(x,y)$, all $a,b\in \dom(\Amf)$, and all $i,j,i',j'<\kappa$, we have\textup{:}
%
	\begin{itemize}
		\item[--] $\Amf^{\kappa}\models \psi_{1}(a,i)$ iff $\Amf^{\kappa}\models \psi_{1}(a,j)$\textup{;}
		\item[--] $\Amf^{\kappa}\models \psi_{2}((a,i),(b,j))$ iff $\Amf^{\kappa}\models \psi_{2}((a,i'),(b,j'))$.
	\end{itemize}
\end{lemma}

\lemmaequivalenceomega*

\begin{proof}
	Let $\mx<\kappa \in \mathbb{N}^{\infty}$. First, we note that, because the signature contains no constants, for every $a\in \dom(\Amf)$ and every $i<\kappa$, we have $(a,i)\in \dom(\Amf^\kappa)$.

	We show that $\Amf^{\kappa}\models \varphi(a,i)$ iff $\Amf^{\kappa}\models \Flat(\varphi)(a,i)$ for all elements $a\in \dom(\Amf)$ and $i<\kappa$. Observe that $\Amf^{\kappa}\models \Flat(\varphi)(a,i)$ iff $\Amf^{\kappa'}\models \Flat(\varphi)(a,i)$ follows from Lemma~\ref{lemma:bisim_omega}, for all $i<\kappa$ and $\kappa'\in \mathbb{N}^{\infty}$. 

	Now the proof proceeds by induction on the construction of $\varphi$. Assume first that $\varphi\in \GMLiu$. We only discuss the critical induction step, where $\varphi$ is of the form $\Diamond\!^{\ge k}_R \psi$ for some $\psi$, in which case $\Flat(\varphi)$ is of the form $\Diamond\!_R\,\Flat(\psi)$.

	Suppose that $\Amf^\kappa\models \Diamond\!^{\ge k}_R \psi(a,i)$. We assumed that $k>0$, so there is at least one $(b,j)$ such that $\Amf^\kappa \models \psi(b,j)$ and $((a,i), (b,j))\in R^{\Amf^{\kappa}}$. By the induction hypothesis, we then also have $\Amf^\kappa\models \Flat(\psi)(b,j)$, and therefore $\Amf^\kappa\models \Diamond_R\, \Flat(\psi)(a,i)$.

	For the other direction, suppose that $\Amf^\kappa\models \Diamond_R\Flat(\psi)(a,i)$, so there is some $(b,j)$ such that $\Amf^\kappa\models \Flat(\psi)(b,j)$ and $((a,i),(b,j))\in R^{\Amf^{\kappa}}$. By Lemma~\ref{lem:withoueq}, this implies that we have $\Amf^\kappa\models \Flat(\psi)(b,j')$ for every $j'<\kappa$. 

	By the induction hypothesis, this implies that $\Amf^\kappa \models \psi(b,j')$ for all $j'<\kappa$. Furthermore, by the construction of $\Amf^\kappa$, it follows that $((a,i), (b,j'))\in R^{\Amf^{\kappa}}$ for all $j'<\kappa$. From $\mx< \kappa$ we obtain $\Amf^\kappa\models\Diamond\!^{\ge k}_R\psi(a,i)$. This completes the induction step.

	The proof for $\varphi\in \CT$ is a straightforward extension of the proof above. It is again by induction on the construction of $\varphi$. For formulas $\psi(x,y)$, we claim that $\Amf^{\kappa}\models \psi((a,i),(b,j))$ iff $\Amf^{\kappa}\models \Flat(\psi)((a,i'),(b,j'))$. We consider the step $\varphi= \exists^{\geq k}x \,\psi(x,y)$ (we may assume that $y$ is free in $\psi$). 	
	Suppose that $\Amf^\kappa\models \exists^{\geq k}x \, \psi(a,i)$. We assumed that $k>0$, so there is at least one $(b,j)$ such that $\Amf^\kappa \models \psi((b,j),(a,i))$. By the induction hypothesis, we then also have $\Amf^\kappa\models \Flat(\psi)((b,j),(a,i))$, and therefore $\Amf^\kappa\models \exists x \, \Flat(\psi)(a,i)$.

	For the other direction, suppose that $\Amf^\kappa\models \exists x \, \Flat(\psi)(a,i)$, so there is some $(b,j)$ such that $\Amf^\kappa\models \Flat(\psi)((b,j),(a,i))$. By Lemma~\ref{lem:withoueq}, this implies that $\Amf^\kappa\models \Flat(\psi)((b,j'),(a,i))$ for every $j'<\kappa$. 

	By IH, this implies that $\Amf^\kappa \models \psi((b,j'),(a,i))$ for all $j'<\kappa$. From $\mx< \kappa$ we obtain $\Amf^\kappa\models \exists^{\geq k}x\, \psi(a,i)$. This completes the induction step and thereby the proof.
\end{proof}

The following lemma can be shown similarly to Lemma~\ref{lemma:equivalenceomega}.

\begin{lemma}\label{lem:equivonomega2}
	Suppose $\varphi$ is a $\GMLinu(\sigma)$-formula with finite $\sigma_{c}$ and $\mx<\kappa<\kappa'\in \mathbb{N}^{\infty}$. Then 
	$\Amf^\kappa\models \varphi(a,i)$ iff $\Amf^\kappa\models \Flat_{\sigma_{c}}(\varphi)(a,i)$
	iff $\Amf^{\kappa'}\models \Flat_{\sigma_{c}}(\varphi)(a,i)$ iff $\Amf^{\kappa'}\models \varphi(a,i)$, for all pointed $\sigma$-structures $\Amf,a$ and all $i <\kappa$.
\end{lemma}

Note that, according to the definition of $L$/$\LS$-definability, defining $\LS$-formulas $\varphi'$ are allowed to contain fresh symbols not occurring in $\varphi$. While fresh propositional variables or modal operators do not affect definability (see below), we 
leave it open whether using a fresh nominal has an effect on definability of formulas without nominals.

\begin{theorem}\label{prop:equivonomega2}
	Let $L/\LS$ be any pair of modal logics from Table~\ref{table:results}, with $L$ admitting nominals, and let $\sigma$ contain at least one constant. Then an $L(\sigma)$-formula $\varphi$ is $\LS(\sigma)$-definable iff $\models \varphi \leftrightarrow \Flat_{\sigma_{c}}(\varphi)$.
\end{theorem}
%
\begin{proof}
	Note that if $\models \varphi \leftrightarrow \varphi'$ and $\varphi'$ uses symbols not in $\sigma$, then we can replace any variable $A\not\in\sigma$ by $\top$, any $\Diamond_{R}\chi$ with $R\not\in\sigma$ by $\neg \top$, and any $N_{c}$ with $c\not\in\sigma$ by an $N_{c'}$ with $c'\in \sigma$, and obtain $\models \varphi \leftrightarrow \varphi''$ for the resulting formula $\varphi''$. Now the proof is similar to the proof of Theorem~\ref{prop:definability1}.
\end{proof}

It remains open whether there are polynomial DAG-size formulas in $\LS$ 
equivalent to $\Flat_{\sigma_{c}}(\Diamond\!^{\ge k}_R \psi)$. Note that the problem is that distinct constants can denote the same domain element.
In contrast, under the unique name assumption, polynomial DAG-size formulas
are easily constructed. Indeed, let $Th_{k}^{n}(p_{0},\dots, p_{n-1})$ be a propositional formula that is true under a propositional assignment iff at least $k$ variables among $p_{0},\dots,p_{n-1}$ are true. It is folklore that there are such formulas of polynomial DAG-size. Let $0,1,\ldots,n-1$ be the constants in $\sigma_{c}$.
Then the formula obtained by replacing in $\Flat_{\sigma_{c}}(\Diamond\!^{\ge k}_R \psi)$ the second conjunct by the formula obtained from $Th_{k}^{n}$ by replacing each $p_{i}$ by $\Diamond_{R}(i\wedge \Flat_{\sigma_{c}}(\psi))$ is as required.

We note that the complexity results for the validity/satisfi\-ability problems for the logics considered in this paper do not depend on whether one defines the size of an input $\varphi$ as the \emph{formula-size} of $\varphi$ (the length of $\varphi$ as a word) or the \emph{DAG-size} $|\varphi|$ of $\varphi$ (the number of subformulas of $\varphi$).
Here, we sketch a reduction from DAG-size to formula-size by introducing 
abbreviations. 
Recall that $\Flat_{\sigma_{c}}(\varphi)$ is equivalent to the $L$-formula $f(\varphi)$ defined recursively in the same way as 
$\Flat_{\sigma_{c}}(\varphi)$ except that
%
$$
f_{\sigma_{c}}(\Diamond\!^{\ge k}_R\psi))=\big[\Diamond_R \big(\Flat_{\sigma_{c}}(\psi)\wedge \bigwedge_{c\in \sigma_{c}} \neg N_c\big)\vee{} \Diamond_{R}^{\geq k}(\Flat_{\sigma_{c}}(\psi) \wedge \bigvee_{c\in \sigma_{c}}N_{c}) \big].
$$
%
Let $\Flat'_{\sigma_{c}}$ be also defined in the same way as $\Flat_{\sigma_{c}}$ except that we set, for a fresh propositional variable $A_\psi$,
%
$$
\Flat'_{\sigma_{c}}(\Diamond\!^{\ge k}_R \psi) = 
\big[\Diamond_R \big(A_\psi \wedge \bigwedge_{c\in \sigma_{c}} \neg N_c\big)\vee{} \Diamond_{R}^{\geq k}(A_\psi \wedge \bigvee_{c\in \sigma_{c}}N_{c})\big].
$$
%
The formula-size of $\Flat'_{\sigma_{c}}(\varphi)$ is clearly polynomial in the formula-size of $\varphi$. 
If $L$ contains the universal modality, then $\models \varphi \leftrightarrow \Flat_{\sigma_{c}}(\varphi)$ iff the following $L$-formula (of polynomial formula-size) is valid:
%
$$
\blacksquare \bigwedge \{A_\psi \leftrightarrow \Flat'_{\sigma_{c}}(\psi) \mid \Diamond\!^{\ge k}_R \psi \in \sub (\varphi)\} \rightarrow \big( \varphi \leftrightarrow \Flat'_{\sigma_{c}}(\varphi) \big).
$$
%
If $L$ does not admit the universal modality, instead of $\blacksquare$ we take all sequences of the form $\Box_{R_1} \dots \Box_{R_m}$ such that $\varphi$ contains nested $\Diamond^{\ge k_1}_{R_1} \dots \Diamond^{\ge k_m}_{R_m}$, with each $\Diamond^{\ge k_i}_{R_i}$, $i =1,\dots,m-1$, being an immediate predecessor of $\Diamond^{\ge k_{i+1}}_{R_{i+1}}$.

\medskip

We now give the detailed definition of $\Flat(\varphi)$ for $\CT/\FOTNE$. Recall that the straightforward extension of the flattening $\Flat$ defined above for $\CT$ without equality does not work. So we now define a new flattening $\Flat$ from $\CT$ to $\FOTNE$. Suppose we are given a $\CT$-formula $\varphi$.
As before, only the definition of $\Flat(\exists^{\geq k}x \, \psi)$ is non-trivial. Assume that $\psi$ is a Boolean combination $\beta$ of the form 
%
$$
\psi = \beta(\rho_{1},\ldots,\rho_{k_{1}}, \gamma_{1}(x),\dots,\gamma_{k_{2}}(x),\xi_{1}(y),\dots,\xi_{k_{3}}(y)),
$$
%
where
% 
\begin{itemize}
	\item[--] the $\rho_{i}$ are binary atoms $R(x,y)$, $R(y,x)$, or $x=y$; 

	\item[--] the $\gamma_{i}(x)$ are unary atoms of the form $A(x)$, $x=x$, or $R(x,x)$, or a formula of the form $\exists^{\geq k'} y\, \gamma_{i}'$; 

	\item[--] the $\xi_{i}(y)$ are unary atoms of the form $A(y)$, $y=y$ or $R(y,y)$, or a formula of the form $\exists^{\geq k'} x \, \xi_{i}'$.
\end{itemize}
%
We may assume that $y$ is free in $\psi$. Consider the formula
%
$$
\varphi_{1} = \exists^{\geq k} x \, \big(((x=y) \wedge \psi_{1}) \vee ((x\not=y) \wedge \psi_{2})\big),
$$
%
in which $\psi_{1}$ is obtained from $\psi$ by replacing 
%
\begin{itemize}
	\item[--] all $\rho_{i}$ of the form $x=y$ by $\top$;

	\item[--] all $\gamma_{i}(x)$ of the form $x=x$ by $\top$;

	\item[--] all $\xi_{i}(y)$ of the form $y=y$ by $\top$; 
\end{itemize}
%
and $\psi_{2}$ is obtained from $\psi$ by replacing
%
\begin{itemize}
	\item[--] all $\rho_{i}$ of the form $x=y$ by $\neg \top$;

	\item[--] all $\gamma_{i}(x)$ of the form $x=x$ by $\top$;

	\item[--] all $\xi_{i}(y)$ of the form $y=y$ by $\top$.
\end{itemize}
%
Clearly, $\varphi$ and $\varphi_{1}$ are logically equivalent. Also, the formula $\exists x\, ((x=y)\wedge \psi_{1})$
is logically equivalent to the formula $\psi_{1}'$ obtained from $\psi_{1}$ by replacing all
$\rho_{i}$ of the form $R(x,y)$ or $R(y,x)$ by $R(y,y)$, all $\gamma_{i}(x)$ of the form $A(x)$ 
by $A(y)$, and all $\gamma_{i}(x)$ of the form $\exists^{\geq k'}\! y\, \gamma_{i}'$ by the result of swapping $x$ and $y$. Now set, recursively, 
%
\begin{align*}
	& \Flat(\exists^{\geq k}x\,\psi)= \Flat(\psi_{1}')\vee \exists x\, \Flat(\psi_{2}), \quad \text{for $k=1$},\\
	& \Flat(\exists^{\geq k}x\,\psi)= \exists x\, \Flat(\psi_{2}), \hspace*{1.4cm} \text{for $k>1$}.
\end{align*}
%
Observe that we do not define $\Flat(\psi(x,y))$ for formulas $\psi(x,y)$ in $\CT$ with occurrences of equality that are not in the scope of a quantifier.

It is now straightforward to prove analogues of Lemma~\ref{lemma:equivalenceomega}
and Theorem~\ref{prop:definability1} for $\CT/\FOTNE$.


\begin{lemma}\label{lem:equivonomega27}
	Let $\sigma$ be constant-free, let $\varphi(x)$ be a $\CT(\sigma)$-formula $($with equality$)$, and let $\mx<\kappa<\kappa'\in \mathbb{N}^{\infty}$. Then, for all pointed $\sigma$-structures $\Amf,a$ and all $i <\kappa$, we have 
	$\Amf^\kappa\models \varphi(a,i)$ iff $\Amf^\kappa\models \Flat(\varphi)(a,i)$
	iff $\Amf^{\kappa'}\models \Flat(\varphi)(a,i)$ iff $\Amf^{\kappa'}\models \varphi(a,i)$.
\end{lemma}
%
\begin{proof}
As before, the interesting part is to show that we have $\Amf^{\kappa}\models \varphi(a,i)$ iff $\Amf^{\kappa}\models \Flat(\varphi)(a,i)$, for all $a\in \dom(\Amf)$ and $i<\kappa$. 

	The proof is by induction on the construction of $\varphi$. For $\CT$-formulas $\psi(x,y)$ without occurrences of equality that are not in the scope of a quantifier, we claim that $\Amf^{\kappa}\models \psi((a,i),(b,j))$ iff $\Amf^{\kappa}\models \Flat(\psi)((a,i'),(b,j'))$, for all $a,b\in \dom(\Amf)$ and all $i,j,i',j'<\kappa$. Observe that the induction step for such formulas follows from Lemma~\ref{lem:withoueq}. 

	We consider the step $\varphi= \exists^{\geq k}x \, \psi(x,y)$, where we may assume that $y$ is free in $\psi$. Assume from above:
%
	\begin{itemize}
		\item[--] $\psi=\gamma(\rho_{1},\ldots,\rho_{k_{1}}, \gamma_{1}(x),\ldots,\gamma_{k_{2}}(x),\xi_{1}(y),\ldots,\xi_{k_{3}}(y))$;

		\item[--] $
		\varphi_{1} = \exists^{\geq k} x \, \big[ \big((x=y) \wedge \psi_{1} \big) \vee \big((x\not=y) \wedge \psi_{2}\big)\big]$;

		\item[--] 
		for $k=1$, 
		$\Flat(\exists^{\geq k}x \, \psi)= \Flat(\psi_{1}')\vee \exists x \, \Flat(\psi_{2})$;

		\item[--] for $k>1$,
		$
		\Flat(\exists^{\geq k}x \, \psi)= \exists x \, \Flat(\psi_{2}).
		$
	\end{itemize}
%
Suppose that $\Amf^\kappa\models \exists^{\geq k}x \, \psi(a,i)$. 

If $k=1$, then we have either $\Amf^{\kappa}\models \psi((a,i),(a,i))$, and so $\Amf^{\kappa} \models \psi_{1}'(a,i)$, or $\Amf^{\kappa}\models \psi((b,j),(a,i))$, for some $(b,j)\not=(a,i)$, and so $\Amf^{\kappa} \models \psi_{2}((b,j),(a,i))$. Then, by IH, $\Amf^{\kappa} \models \Flat(\psi_{1}')(a,i)$ or $\Amf^{\kappa} \models \Flat(\psi_{2})((b,j),(a,i))$. In both cases $\Amf^\kappa\models \Flat(\varphi)$.

	If $k>1$, then $\Amf^{\kappa}\models \psi((b,j),(a,i))$, for some $(b,j)\not=(a,i)$, and so again $\Amf^{\kappa} \models \psi_{2}((b,j),(a,i))$ and $\Amf^\kappa\models \Flat(\varphi)$ by IH.

	For the other direction, suppose $\Amf^\kappa\models \Flat(\varphi)(a,i)$. 

	Let $k=1$. If $\Amf^\kappa\models \Flat(\psi_{1}')(a,i)$, then by IH, $\Amf^{\kappa}\models \psi_{1}'(a,i)$, and so $\Amf^{\kappa}\models \varphi(a,i)$. If $\Amf^{\kappa}\models \exists x \, \Flat(\psi_{2})(a,i)$, then there is some $(b,j)$ such that $\Amf^\kappa\models \Flat(\psi_{2})((b,j),(a,i))$. By Lemma~\ref{lem:withoueq}, we have $\Amf^\kappa\models \Flat(\psi_{2})((b,j'),(a,i))$ for some $(b,j')\not=(a,i)$.  
	By the induction hypothesis, this implies that $\Amf^\kappa \models \psi_{2}((b,j'),(a,i))$. Thus, we obtain $\Amf^\kappa\models \exists^{\geq k}x \, \psi(a,i)$. 

	Let $k>1$. Then $\Amf^{\kappa}\models \exists x \, \Flat(\psi_{2}(a,i)$. We then have some $(b,j)$ such that $\Amf^\kappa\models \Flat(\psi_{2})((b,j),(a,i))$. By Lemma~\ref{lem:withoueq}, $\Amf^\kappa\models \Flat(\psi_{2})((b,j'),(a,i))$ for every $j'<\kappa$. 
	By the induction hypothesis, this implies that $\Amf^\kappa \models \psi_{2}((b,j'),(a,i))$ for all $j'<\kappa$. Since $\mx< \kappa$, we obtain $\Amf^\kappa\models \exists^{\geq k}x \, \psi(a,i)$, as required. 
\end{proof}

For the polynomial reduction of checking $\models\varphi \leftrightarrow \Flat(\varphi)$ to $\CT$-validity, 
observe that, 
although $\Flat(\varphi)$ is exponential in formula-size as we duplicate the formulas $\gamma_{i}(x)$ and $\xi_{i}(y)$, we can again   use the DAG-representation instead. 

\begin{corollary}
	$\CT/\FOTNE$-definability is polytime reducible to $\CT$-validity.
\end{corollary}


\lemsuccinctness*

\begin{proof}
Suppose otherwise, that is, $\chi_{n}\in \MLiu$ is of polynomial DAG-size 
	and $\Amf\models \varphi_{n}(a)$ iff $\Amf\models \chi_{n}(a)$ holds for all $\Amf,a$.
	Consider the model $\Amf_{n}=(W_{n},R^{\Amf_{n}},A_{0}^{\Amf_{n}},\ldots,A_{n-1}^{\Amf_{n}})$ with domain $W_{n}=\{w\} \cup X_{n} \cup X_{n}'$, where  
	$X_{n}=\{0,\ldots,2^{n}-1\}$ and $X_{n}'=\{0,\ldots,2^{n}-1\}\times \{1\}$, and
%
\begin{itemize}
\item[--] $R^{\Amf_{n}} = (\{w\} \times X_{n}) \cup (X_{n} \times X_{n}')$,

\item[--] $A_{i}^{\Amf_{n}}$ is such that the nodes $k\in X_{n}$ and $(k,1)\in X_{n}'$ satisfy $k$ encoded in binary using $A_{0},\ldots,A_{n-1}$.   
\end{itemize}
%
Clearly, $\Amf_{n}\models \Box_{R}\varphi_{n}(w)$, and so $\Amf_{n}\models \Box_{R}\chi_{n}(w)$. Then, for every $\Diamond_{R} \chi\in \text{sub}(\chi_{n})$ such that $\Amf_{n}\models \Diamond_{R}\chi(v)$. for some $v\in X_{n}$, we can select from $X_{n}'$ a $v_{\chi}\in X_{n}'$ with $\Amf_{n}\models\chi(v_{\chi})$. Denote the set of selected nodes by $X_{n}''$.
	Then the restriction of $\Amf_{n}$ to the set $\{w\}\cup X_{n}\cup X_{n}''$ satisfies $\Box_{R}\chi$ and $X_{n}''\subsetneq X_{n}'$ for sufficiently large $n$ as the size of $X_{n}''$ is bounded by the number of subformulas of $\chi_{n}$. By the semantics of $\Box_R\varphi_{n}$, we clearly have
	$\Amf_{n}\not\models\Box_{R}\varphi_{n}(w)$ for all $n>0$, which is  a contradiction. 
\end{proof}

We now introduce a more succinct version of $\MLiu$, which is included in the two-variable guarded fragment of first-order logic (and so satisfiability is still \ExpTime-complete). Fix variables $x,y$. Then the formulas of suc$\MLiu$, \emph{succinct $\MLiu$}, are constructed from atoms $A(z)$ and $\top(z)$ with $z\in \{x,y\}$ 
by taking the closure under the following rules:
%
\begin{enumerate}
	\item if $\varphi,\psi\in \text{suc}\MLiu$, then $\neg\varphi,\varphi\wedge \psi \in \text{suc}\MLiu$;

	\item if $\chi(x,y)\in \text{suc}\MLiu$ and $x,y$ are both free in $\chi(x,y)$, then $\exists y\, (R(x,y) \wedge \chi(x,y))\in \text{suc}\MLiu$, $\exists x\, (R(y,x) \wedge \chi(x,y))\in \text{suc}\MLiu$;

	\item if $\chi(x,y)\in \text{suc}\MLiu$ and $x,y$ are both free in $\chi(x,y)$, then $\exists y\, (R(y,x) \wedge \chi(x,y))\in \text{suc}\MLiu$, $\exists x\, (R(x,y) \wedge \chi(x,y))\in \text{suc}\MLiu$;
	\item if $\chi(x,y)\in \text{suc}\MLiu$ and $x,y$ are both free in $\chi(x,y)$, then
	$\exists y \, \chi(x,y)\in \text{suc}\MLiu$ and $\exists x \, \chi(x,y)\in \text{suc}\MLiu$.
\end{enumerate} 
%
The languages suc$\MLi$ and suc$\MLu$ are obtained by dropping items 4) and 3), respectively. The language suc$\ML$ is defined by dropping 3) and 4).

\begin{lemma}
	Let $L\in \{\ML,\MLi,\MLu,\MLiu\}$. Then suc$L$ and $L$ have the same expressive power in the sense that
%
\begin{enumerate}
\item[$(i)$] for every $\varphi\in L$, one can construct in polynomial time a formula $\varphi'(x)\in \text{suc}L$
		such that $\Amf\models \varphi(a)$ iff $\Amf\models \varphi'(a)$ for all pointed $\Amf,a$\textup{;}

\item[$(ii)$] for every $\varphi(x)\in \text{suc}L$, one can construct in exponential time a formula $\varphi'\in L$
		such that $\Amf\models \varphi(a)$ iff $\Amf\models \varphi'(a)$ for all pointed $\Amf,a$.
	\end{enumerate}
\end{lemma}
%
\begin{proof}
$(i)$ is trivial. $(ii)$ We construct $\varphi'$ by induction. The case of atomic formulas is clear. Assume $\chi(x,y)$ is a Boolean combination $\beta$ of the form 
	%
	$$
	\chi = \beta(\gamma_{1}(x),\dots,\gamma_{k_{1}}(x),\xi_{1}(y),\dots,\xi_{k_2}(y)),
	$$
	%
	where
	% 
	\begin{itemize}
		\item[--] the $\gamma_{i}(x)$ are unary atoms of the form $A(x)$, $\top(x)$, or a formula of the form $\exists y\, \gamma_{i}^\ast$; 

		\item[--] the $\xi_{i}(y)$ are unary atoms of the form $A(y)$, $\top(y)$, or a formula of the form $\exists x \, \xi_{i}^\ast$.
	\end{itemize} 
	A \emph{$\gamma$-type} $t$ is a maximal satisfiable subset of $$
	\{\gamma_{1}(x),\dots,\gamma_{k_{1}}(x),\neg\gamma_{1}(x),\dots,\neg\gamma_{k_{1}}(x)\}.
	$$
	A \emph{$\xi$-type} $t$ is a maximal satisfiable subset of 
	$$
	\{\xi_{1}(y),\dots,\xi_{k_{2}}(y),\neg\xi_{1}(y),\dots,\neg\xi_{k_{2}}(y)\}.
	$$
	Let $S$ be the set of all pairs $(t_{1},t_{2})$ of $\gamma$-types $t_{1}$ and $\xi$-types $t_{2}$ such that $t_{1}\cup t_{2}\models \chi$. Consider now, inductively, the equivalent translations $\gamma_{i}'$ and $\xi_{i}'$ of $\gamma_{i}(x)$ and $\xi_{i}(y)$ into $L$, respectively. For any $\gamma$-type $t$, let $t'=\bigwedge_{\gamma\in t}\gamma'$ and, for any $\xi$-type $t$, let 
	$t'=\bigwedge_{\xi\in t}\xi'$. Now define
%
\begin{itemize}
\item[--] $(\exists y \, (R(x,y) \wedge \chi(x,y)))'= \bigvee_{(t_{1},t_{2})\in S}(t_{1}' \wedge \Diamond_{R}t_{2}')$;

\item[--] $(\exists x \, (R(y,x) \wedge \chi(x,y)))'= \bigvee_{(t_{1},t_{2})\in S}(t_{2}' \wedge \Diamond_{R}t_{1}')$;

\item[--] $(\exists y \, (R(y,x) \wedge \chi(x,y)))'= \bigvee_{(t_{1},t_{2})\in S}(t_{1}' \wedge \Diamond_{R}^{-}t_{2}')$;

\item[--] $(\exists x \, (R(x,y) \wedge \chi(x,y)))'= \bigvee_{(t_{1},t_{2})\in S}(t_{2}' \wedge \Diamond_{R}^{-}t_{1}')$;

\item[--] $(\exists y \, \chi(x,y))' = \bigvee_{(t_{1},t_{2})\in S}(t_{1}' \wedge \Du t_{2}')$;

\item[--] $(\exists x \, \chi(x,y))' = \bigvee_{(t_{1},t_{2})\in S}(t_{2}' \wedge \Du t_{1}')$.
\end{itemize} 
%
It is straightforward to see that $\cdot'$ is a map from suc$L$ to $L$ and that
$\Amf\models \varphi(a)$ iff $\Amf\models \varphi'(a)$, for all pointed $\Amf,a$.
\end{proof}

We now consider $\FOTNE/\MLiu$-definability, where $\MLiu$ is represented in suc$\MLiu$. For every $\mathfrak{A}$, we take the \emph{twin-unfolding} $\Amf^{\ast}$ of $\mathfrak{A}$ whose domain $\dom(\Amf^{\ast})$ is the set of 
%
\begin{equation}\label{eq:def1}
