It remains to define $m(\exists x \, \psi)$. Assume $\psi$ is a Boolean combination $\beta$ of the form 
%
$$
\psi = \beta(\rho_{1},\ldots,\rho_{k_{1}}, \gamma_{1}(x),\dots,\gamma_{k_{2}}(x),\xi_{1}(y),\dots,\xi_{k_{3}}(y)),
$$
%
where
% 
\begin{itemize}
	\item[--] the $\rho_{i}$ are binary atoms $R(x,y)$, $R(y,x)$; 

	\item[--] the $\gamma_{i}(x)$ are unary atoms of the form $A(x)$, or $R(x,x)$, or a formula of the form $\exists y\, \gamma_{i}'$; 

	\item[--] the $\xi_{i}(y)$ are unary atoms of the form $A(y)$, or $R(y,y)$, or a formula of the form $\exists x \, \xi_{i}'$.
\end{itemize}
%
We may assume that $y$ is free in $\psi$. For $R\in \sig(\varphi)$, we construct from $\psi$ the formulas 
%
\begin{itemize}
\item[--] $\psi_{R(x,y)}$ by replacing all $\rho_{i}$ of the form $S(x,y)$ and $S(y,x)$ with $S\not=R$ or of the form $R(y,x)$ by $\neg\top(x)$, all $\gamma_{i}$ of the form $S(x,x)$ by $\neg\top(x)$, all $\xi_{i}$ of the form $S(y,y)$ by $\neg\top(y)$, and all $\rho_{i}$ of the form $R(x,y)$ by $\top(x)$;

\item[--] $\psi_{R(y,x)}$ by replacing all $\rho_{i}$ of the form $S(x,y)$ and $S(y,x)$ with $S\not=R$ or of the form $R(x,y)$ by $\neg \top(x)$, all $\gamma_{i}$ of the form $S(x,x)$ by $\neg\top(x)$, all $\xi_{i}$ of the form $S(y,y)$ by $\neg\top(y)$, and replace all $\rho_{i}$ of the form $R(x,y)$ by $\top(x)$;

\item[--] $\psi_{N}$ by replacing all $\rho_{i}$ of the form $S(x,y)$ and $S(y,x)$ and all
	$\gamma_{i}$ of the form $S(x,x)$ and all $\xi_{i}$ of the form $S(y,y)$ by $\neg\top(x)$. 
\end{itemize}
%
Now, consider the formula
%
\begin{eqnarray*}
	\psi_{1} & = & \bigvee_{R\in \sig(\varphi)} (R(x,y) \wedge \psi) 
	\vee \bigvee_{R\in \sig(\varphi)} (R(y,x) \wedge \psi) \vee\\
	& & \big[\psi \wedge \bigwedge_{R\in \sig(\varphi)} \big(\neg R(x,y) \wedge \neg R(y,x) \big) \big],
\end{eqnarray*}
%
which is equivalent to $\psi$. Next, we obtain from $\exists x \, \psi_{1}(x)$ the modal reduct $m(\exists x\, \psi)$ by replacing

\begin{itemize}
\item[--] $\psi$ in $(R(x,y) \wedge \psi)$ by $m(\psi_{R(x,y)})$;

\item[--] $\psi$ in $(R(y,x) \wedge \psi)$ by $m(\psi_{R(y,x)})$;

\item[--] $(\psi \wedge \bigwedge_{R\in \sig(\varphi)} (\neg R(x,y) \wedge \neg R(y,x))$ by $m(\psi_{N})$.
\end{itemize}
%
The resulting formula is in suc$\MLiu$ and of polynomial DAG-size (but of exponential formula-size) in the size of $\varphi$.

\begin{lemma}\label{lem:twinunfoldingequiv}
For all pointed structures $\Amf,a$ and $j=0,1$, we have $\Amf^{\ast}\models \varphi(a^{j})$ iff $\Amf^{\ast}\models m(\varphi)(a^{j})$.
\end{lemma}
\begin{proof}
	The proof uses the following properties of $\Amf^{\ast}$: (1) for all $a,b\in \dom(\Amf^{\ast})$,
	if $(a,b)\in R^{\Amf^{\ast}}$, then $(a,b)\not\in S^{\Amf^{\ast}}$ for any $S\not=R$ and $(b,a)\not\in S^{\Amf^{\ast}}$ for any $S$; (2) for all $a\in \dom(\Amf^{\ast}$ and all Boolean combination of subformulas $\psi$ of $m(\varphi)$ with one free variable, if $\Amf^{\ast}\models \psi(a)$, then there exists $b\in \dom(\Amf^{\ast})$ such that $\Amf^{\ast}\models \psi(b)$, $b\not=a$, and $(a,b),(b,a)\not\in S^{\Amf^{\ast}}$ for any $S\in \sig(\varphi)$.
\end{proof}

We are now in a position to show that $m(\varphi)$ is a suc$\MLiu$-formula defining $\varphi$ whenever such a definition exists.

\begin{theorem}\label{prop:definability111}
An $\FOTNE$-formula $\varphi(x)$ %without equality 
is suc$\MLiu$-definable iff $\models \varphi \leftrightarrow m(\varphi)$.
\end{theorem}
\begin{proof}
Follows from Lemmas~\ref{lem:twinunfoldingtrans} and~\ref{lem:twinunfoldingequiv}.
\end{proof}

As $m(\varphi)$ is constructed in polytime in DAG-representation, we obtain:
%
\begin{corollary}
	$\CT/\MLiu$-definability is polytime reducible to $\CT$-validity.
\end{corollary}

We next consider the elimination of the universal and inverse modalities.

Define the \emph{$\omega$-unfolding} $\Amf^{\updownarrow\omega}$ of
a structure $\Amf$ as follows. Its domain $\dom(\Amf^{\updownarrow\omega})$ is the set of 
all
%
\begin{equation}\label{eq:def5}
	\vec{a}=a_{0}^{j_{0}}S_{0}\cdots S_{n-1}a_{n}^{j_{n}},
\end{equation}
%
where $n\geq 0$, $j_{i}\in \omega$, $a_{i}\in \dom(\Amf)$ for all $i\leq n$, and $S_{i}$ is either a binary predicate symbol in $\sig(\varphi)$ or its inverse such that $(a_{i},a_{i+1})\in S_{i}^{\Amf}$ for $i\leq n$. Let $\text{tail}(\vec{a})=a_{n}^{j}$.
%
For $\vec{a}$ of the form \eqref{eq:def5}, we set $\vec{a}\in A^{\Amf^{\updownarrow\omega}}$ iff $a_{n}\in A^{\Amf}$. Let $\vec{a}$ be of the form \eqref{eq:def5} and let $\vec{a}'= a_{0}^{j_{0}}S_{0}\cdots a_{n}^{j_{n}}S_{n}a_{n+1}^{j_{n+1}}$ be an extension of $\vec{a}$. Then $(\vec{a},\vec{a}')\in R^{\Amf^{\updownarrow\omega}}$ iff $R=S_{n}$ and 
$(\vec{a}',\vec{a})\in R^{\Amf^{\updownarrow\omega}}$ iff $R^{-}=S_{n}$.
%
\begin{lemma}\label{lem:updownarrow}
	For all pointed structures $\Amf,a$, we have $\Amf^{\updownarrow\omega},a^{0}\sim_{\MLiu}\Amf,a$.
\end{lemma}

$\Amf_{0}$ is a \emph{generated substructure} of $\Amf_{1}$ if it is a substructure of $\Amf_{1}$ and $a\in \text{dom}(\Amf_{0})$ and $(a,a')\in R^{\Amf_{1}}$ or
$(a',a)\in R^{\Amf_{1}}$ imply $a'\in \dom(\Amf_{0})$.
$\Amf_{0}$ is a \emph{forward generated substructure} of $\Amf_{1}$ if it is a substructure of $\Amf_{1}$ and $a\in \text{dom}(\Amf_{0})$ and $(a,a')\in R^{\Amf_{1}}$ imply $a'\in \dom(\Amf_{0})$. By $\Amf_{a}$ we denote the smallest
generated substructure of $\Amf$ containing $a\in \dom(\Amf)$.    

Define the \emph{forward $\omega$-unfolding} $\Amf^{\uparrow\omega}$  as the
substructure of $\Amf^{\updownarrow\omega}$, in which $\dom(\Amf^{\uparrow\omega})$ is the set of all
%
$$
\vec{a}=a_{0}^{j_{0}}R_{0}\cdots R_{n-1}a_{n}^{j_{n}}, 
$$
% 
where each $R_{i}$ is a binary predicate symbol in $\sig(\varphi)$. Forward $\omega$-unfoldings have been considered before in the context of $\ML$-definability~\cite{DBLP:journals/igpl/AndrekaBN95,DBLP:conf/concur/JaninW96}.
Note that $\Amf^{\uparrow\omega}$ is a forward generated substructure of $\Amf^{\updownarrow\omega}$ and we have the following:

\begin{lemma}\label{lem:uparrow}
	$\Amf^{\uparrow\omega},a^{0}\sim_{\MLu}\Amf,a$.
\end{lemma}

For pointed structures $\Amf,a$ and $\Bmf,b$, we write $\Amf,a\cong\Bmf,b$ if there is an isomorphism from $\Amf$ onto $\Bmf$ mapping $a$ to $b$. 

\begin{lemma}\label{lem:lemfrombisimtoiso} 
For any at most countable structures $\Amf,\Bmf$ with 
	$a\in \dom(\Amf)$ and $b\in \dom(\Bmf)$,
%
		\begin{itemize}
		\item[--] if $\Amf,a\sim_{\MLi} \Bmf,b$, then
		$\Amf_{a^{0}}^{\updownarrow\omega},a^{0}\cong \Bmf_{b^{0}}^{\updownarrow\omega},b^{0}$\textup{;}
		%\item if $\Amf,w \sim_{\MLu} \Bmf,v$, then
		%$\Amf^{\uparrow\omega},w^{0}\cong\Bmf^{\uparrow\omega},v^{0}$.
		\item[--] if $\Amf,a\sim_{\ML} \Bmf,b$, then
		$\Amf_{a^{0}}^{\uparrow\omega},a^{0}\cong\Bmf_{b^{0}}^{\uparrow\omega},b^{0}$.	
	\end{itemize}
\end{lemma}
%A substructure $\Amf_{0}$ of $\Amf_{1}$ is \emph{$\varphi$-exhaustive} if all $\Du \psi\in %\sub(\varphi)$ satisfied in  $\Amf_{1}$ there exists $w\in \dom(\Amf_{0})$ satisfying $\psi$. 

We say that $\varphi$ is \emph{invariant under} (\emph{forward}) \emph{generated substructures} if, for all pointed $\Amf,a$ and all (forward) generated substructures $\Amf'$ of $\Amf$ with $a\in \dom(\Amf')$, we have $\Amf\models\varphi(a)$ iff $\Amf'\models \varphi(a)$.
%We say that $\varphi$ is \emph{invariant under $\varphi$-exhaustive generated substructures} if %for all pointed $\Amf,w$ and all generated substructures $\Amf'$ of $\Amf$ which are %$\varphi$-exhaustive and with $w\in \dom(\Amf')$, $\Amf\models\varphi(w)$ iff $\Amf'\models %\varphi'(w)$.

\begin{lemma}\label{lem:semcrit}
	The following hold\textup{:}
	\begin{enumerate}
		\item $\varphi\in \MLiu$ is $\MLi$-definable iff $\varphi$ is invariant under generated substructures\textup{;}

		%\item $\varphi\in \MLiu$ is $\MLu$-definable iff $\varphi$ is invariant under %$\varphi$-exhaustive forward generated substructures;

		\item $\varphi\in \MLiu$ is $\ML$-definable iff $\varphi$ is invariant under forward generated substructures.
	\end{enumerate}
\end{lemma}
\begin{proof}
	(1) It is straightforward to show that every formula in $\MLi$ is invariant under generated substructures. Hence the direction from left to right follows. Conversely, assume that $\varphi\in\MLiu$ is not $\MLi$-definable but is invariant under generated substructures. We find countable $\Amf,a$ and $\Bmf,b$ with $\Amf\models \varphi(a)$, $\Bmf\models\neg\varphi(b)$, and $\Amf,a\sim_{\MLi}\Bmf,b$.
	By Lemma~\ref{lem:lemfrombisimtoiso}, we have 
	$\Amf_{a^{0}}^{\updownarrow\omega},a^{0}\cong \Amf_{b^{0}}^{\updownarrow\omega},b^{0}$.
	By invariance of $\varphi$ under generated substructures, $\Amf_{a^{0}}^{\updownarrow\omega}\models \varphi(a^{0})$ because
	$\Amf_{a^{0}}^{\updownarrow\omega}$ is a generated substructure of
	$\Amf^{\updownarrow\omega}$ and $\Amf^{\updownarrow\omega}\models \varphi(a^{0})$
	because, by Lemma~\ref{lem:updownarrow}, $\Amf^{\updownarrow\omega},a^{0}\sim_{\MLiu}\Amf,a$.

	By invariance of $\varphi$ under generated substructures, we obtain $\Bmf_{b^{0}}^{\updownarrow\omega}\models \neg\varphi(b^{0})$ because
	$\Bmf_{b^{0}}^{\updownarrow\omega}$ is a generated substructure of
	$\Bmf^{\updownarrow\omega}$ and $\Bmf^{\updownarrow\omega}\models \neg\varphi(b^{0})$
	because, by Lemma~\ref{lem:updownarrow}, $\Bmf^{\updownarrow\omega},b^{0}\sim_{\MLiu}\Bmf,b$.

	We have derived a contradiction as isomorphic pointed structures satisfy the same formulas.

	(2) It is straightforward to show that every formula in $\ML$ is invariant under forward generated substructures. Hence the direction from left to right follows. Conversely, assume that $\varphi\in\MLiu$ is not $\ML$-definable but is invariant under forward generated substructures. We find countable $\Amf,a$ and $\Bmf,b$ with $\Amf\models \varphi(a)$, $\Bmf\models\neg\varphi(b)$, and $\Amf,a\sim_{\ML}\Bmf,b$.
	By Lemma~\ref{lem:lemfrombisimtoiso}, 
	$\Amf_{a^{0}}^{\uparrow\omega},a^{0}\cong \Amf_{b^{0}}^{\uparrow\omega},b^{0}$.
	By invariance of $\varphi$ under forward generated substructures, $\Amf_{a^{0}}^{\uparrow\omega}\models \varphi(a^{0})$ because
	$\Amf_{a^{0}}^{\uparrow\omega}$ is a forward generated substructure of
	$\Amf^{\updownarrow\omega}$ and $\Amf^{\updownarrow\omega}\models \varphi(a^{0})$
	because, by Lemma~\ref{lem:updownarrow}, $\Amf^{\updownarrow\omega},a^{0}\sim_{\MLiu}\Amf,a$.

	By invariance of $\varphi$ under forward generated substructures, $\Bmf_{b^{0}}^{\uparrow\omega}\models \neg\varphi(b^{0})$ because
	$\Bmf_{b^{0}}^{\uparrow\omega}$ is a forward generated substructure of
	$\Bmf^{\updownarrow\omega}$ and $\Bmf^{\updownarrow\omega}\models \neg\varphi(b^{0})$
	because, by Lemma~\ref{lem:updownarrow}, $\Bmf^{\updownarrow\omega},b^{0}\sim_{\MLiu}\Bmf,b$.  

	We have derived a contradiction as isomorphic pointed structures satisfy the same formulas.    
\end{proof}
