We consider uniform $\FOTNE/\MLiu$-separation.

\begin{theorem}\label{thm:uniformsep20}
	For any signature $\sigma$ with $\sigma_{c}=\emptyset$ and any $\FOTNE(\sigma)$-formula $\varphi$, the following conditions are equivalent\textup{:}
	%
	\begin{enumerate}
		\item[$(a)$] $\varphi$ has a uniform $\MLiu(\sigma)$-separator\textup{;}

		\item[$(b)$] $m(\varphi)$ is a uniform $\MLiu(\sigma)$-separator for $\varphi$\textup{;}

		\item[$(c)$] $\varphi\models m(\varphi)$\textup{;}

		\item[$(d)$] $\varphi$ is preserved under twin-unfoldings of $\sigma$-structures $\Amf$ in the sense that $\Amf\models \varphi(a)$ implies $\Amf^{\ast}\models \varphi(a^{0})$, for any $\Amf,a$.
	\end{enumerate}
\end{theorem}
%
\begin{proof}
	$(a) \Rightarrow (d)$. Given a uniform $\MLiu(\sigma)$-separator $\varphi'$ for $\varphi$, we need to show that $\varphi$ is preserved under twin unfoldings of $\sigma$-structures. Suppose this is not so. Take a pointed $\sigma$-structure $\Amf,a$ such that $\Amf\models \varphi(a)$ and $\Amf^{\ast}\not\models \varphi(a^0)$. 
	From (a) we obtain $\Amf\models \varphi'(a)$, and so, by By Lemma~\ref{lem:twinunfoldingtrans}, $\Amf^{\ast}\models\varphi'(a^{0})$.

	For any signature $\varrho$ and $k\geq 0$, let suc$\MLiu_{k}(\varrho)$ be the set of all suc$\MLiu(\varrho)$-formulas of rank $\le k$. If $\varrho$ is finite, then suc$\MLiu(\varrho)$ is finite modulo logical equivalence. 

	The proof is now similar to the proof of Theorem~\ref{thm:uniformsep1}. We construct a formula $\gamma(x) \in \text{suc}\MLiu$ using fresh unary relation symbols such that $\Amf^{\ast}$ can always be expanded to a model of $\gamma$ and $\gamma\models \varphi\leftrightarrow m(\varphi)$. The latter is achieved by constructing $\gamma$
	in such a way that it ensures conditions (1) and (2) of the proof of Lemma~\ref{lem:twinunfoldingequiv}.

	Consider fresh unary $A_{0}^{S},A_{1}^{S},A_{2}^{S},B_{0},B_{1}$,  for 
	$S\in \mathcal{R}(\varphi)$ with $\mathcal{R}(\varphi)=\{ R \mid R\in \sig(\varphi)\} \cup \{R^{-} \mid R\in \sig(\varphi)\}$. Let $\varrho$ be the union of the set of fresh symbols and $\sig(\varphi)\cup \sig(\varphi')$. We first ensure condition~2 by stating that $B_{0},B_{1}$ partition the domain, satisfy the same formulas in suc$\MLiu_{k}(\varrho)$, and that elements satisfying $B_{0}$ and $B_{1}$ are not related by any $R\in \sigma$. So let $\gamma$ contain the conjuncts
	\begin{align*}
		& \blacksquare ((B_{0}\rightarrow \neg B_{1}) \wedge (B_{0} \vee B_{1})),\\
		& \blacksquare ((B_{0} \rightarrow \neg \Diamond_{R}B_{1}) \wedge (B_{1} \rightarrow \neg \Diamond_{R}B_{0})), \\ 
		& \Du (\chi \wedge B_{0}) \leftrightarrow \Du(\chi \wedge B_{1}),
	\end{align*}  
%
	for all $\chi\in \text{suc}\MLiu_{k}(\varrho)$. To enforce condition~1, $\gamma$ states that the $A_{0}^{S},A_{1}^{S},A_{2}^{S}$ partition the domain:
	\begin{align*}
		&\blacksquare \bigvee_{0\leq i\leq 2,S\in \mathcal{R}(\varphi)}A_{i}^{S},\\
	    &\blacksquare \bigwedge_{A_{i}^{S}\not=A_{j}^{S'}}(A_{I}^{S} \rightarrow \neg A_{j}^{S'}),\\
	\end{align*}
	and that the relations $S$ can link the $A_{i}^{S'}$ only in a certain way: for all  $S,S',S''\in \mathcal{R}(\varphi)$ and all $i\leq 2$: 
	\begin{align*}
		& \blacksquare (A_{i}^{S}\rightarrow \Box_{S'}\neg A_{i\oplus_{3} 1}^{S''}), \text{ if $S'\not=S''$},\\
		& \blacksquare (A_{i}^{S}\rightarrow \Box_{S'}\neg A_{i}^{S''}).
	\end{align*}
%
	Then $\gamma$ is satisfied in any $\varrho$-structure $\Bmf^{\ast}$ obtained from some $\Amf^{\ast}$ by satisfying $B_{0}$ in all nodes of the form \eqref{eq:def1} with $j=0$, $B_{1}$ in all nodes of the form \eqref{eq:def1} with $j=1$ and by satisfying $A_{i}^{S}$ in a node of the form \eqref{eq:def1} if there is $k\geq 0$ with $n=3k+i$ and $S_{n-1}=S$. Then $\Bmf^{\ast}\models \gamma(a^{0})$.
	By construction, $\gamma \models \varphi \leftrightarrow m(\varphi)$.
	As a consequence, we have $\varphi\models \gamma \rightarrow m(\varphi)$, and so, by the definition of uniform $\MLiu(\sigma)$-separators, $\varphi'\models \gamma \rightarrow m(\varphi)$. Since $\Bmf^{\ast}\models \varphi'(a^{0})$ and $\Bmf^{\ast}\models \gamma(a^{0})$, we obtain $\Bmf^{\ast}\models m(\varphi)(a^{0})$. Therefore, $\Amf^{\ast}\models m(\varphi)(a^{0})$ as $m(\varphi)$ does not contain any fresh symbols. It follows from Lemma~\ref{lem:twinunfoldingtrans} that $\Amf^{\ast}\models\varphi(a^{0})$, which is impossible.

	The implication $(b) \Rightarrow (a)$ is trivial.

	$(c) \Rightarrow (b)$ Let $\varphi\models m(\varphi)$. To prove  that $m(\varphi)$ is a uniform $\MLiu(\sigma)$-separator for $\varphi$, suppose $\varphi\models\chi$, for an $\MLiu(\sigma)$-formula $\chi$, aiming to show $m(\varphi)\models \chi$. Let $\Amf\models m(\varphi)(a)$. Then $\Amf^{\ast}\models m(\varphi)(a)$, by Lemma~\ref{lem:twinunfoldingequiv}. Then $\Amf^{\ast}\models \varphi(a)$ 
	by Lemma~\ref{lem:twinunfoldingtrans}, and so $\Amf^{\ast}\models \chi(a)$. Using again Lemma~\ref{lem:twinunfoldingequiv}, we obtain $\Amf\models \chi(a)$, as required.

	$(d) \Rightarrow (c)$ Suppose $\Amf\models \varphi(a)$. As $\varphi$ is  preserved under twin-unfoldings, $\Amf^{\ast}\models \varphi(a^{0})$. Hence $\Amf^{\ast}\models m(\varphi)(a^{0})$, by Lemma~\ref{lem:twinunfoldingtrans}. By Lemma~\ref{lem:twinunfoldingequiv}, $\Amf\models m(\varphi)(a)$, as required.
\end{proof}


