	\maxnorm{\Delta_{d_{i,j}}}&\leq\maxnorm{\comp{p_{i,j}\comp{\mat{\mat{H}_i}}}-p_{i,j}\comp{\mat{H}_i}}+\maxnorm{p_{i,j}\comp{\mat{H}_i}-p_{i,j}\mat{H}_i},\\
