%
%
%
%
%
%
%
%
By~\cref{lem:valuebound}, the following inequality holds
%
\begin{equation}\label{eq:betadeltaL}
  \maxnorm{\beta^{(\ell-1)}(\Delta_\mat{L},\row{\mat{R}}{i}\cdot v)}
%
  \leq \Theta_{0} \Theta^{\ell-1} \textmaxnorm{\Delta_\mat{L}}\dualnorm{\row{\mat{R}}{i}}\norm{v}
\end{equation}
for~\((\Theta,\Theta_0)
%
=(k,k_0)\) if~\(\beta=\beta_{\textsc{mm}}\) or~\({(\gamma,\gamma_0)}\) otherwise (where
\(\Theta_0=\gamma_0\) comes from the current proof with~\({\ell=1}\) and~\({g_0=1}\)).
Similarly,
\begin{equation}\label{eq:betadeltaR}
\maxnorm{\beta^{(\ell-1)}(\row{\mat{L}}{i}\cdot{u},\Delta_\mat{R})}\leq\Theta_{0}\Theta^{\ell-1}\textmaxnorm{\Delta_\mat{R}}\dualnorm{\row{\mat{L}}{i}}\norm{u}.
\end{equation}
Gathering~\cref{eq:deltaci,eq:deltadij,eq:deltaQ,eq:deltaM,eq:betalm1,eq:betadeltaL,eq:betadeltaR} we deduce that
\begin{multline}
\maxnorm{\comp{c_j}-c_j}\leq\textstyle\sum_{i=1}^{r} \Bigl(\Theta_{0}\Theta^{\ell-1}\bigl(\zeronorm{\row{\mat{L}}{i}}+\zeronorm{\row{\mat{R}}{i}}+\zeronorm{\row{(\Transpose{P})}{j}}\bigr)+t_{\ell-1}\Bigr)\\
\times\dualnorm{\row{\mat{L}}{i}}\dualnorm{\row{\mat{R}}{i}}|p_{i,j}|\norm{u}\norm{v}\ulp+\bbigO{\ulp^{2}},
\end{multline}
and thus that~\({\textmaxnorm{\comp{c_j}-c_j}\leq\bigl({\Theta_{0}\Theta^{\ell-1}Q_{0}+t_{\ell-1}}\bigr)\gamma\norm{u}\norm{v}\ulp+\bbigO{\ulp^2}}\).
As in~\cite{Higham:2002}, we deduce that~\(t_\ell\) must then satisfy:
\begin{equation}
\left\{\begin{array}{llll}
t_{\ell} &=& \bigl({ \Theta_{0} \Theta^{\ell-1} Q_{0}+t_{\ell-1}}\bigr) \gamma &\text{for}\ \ell>0,\\
t_{0}  &=& {k_{0}}^{\!2} & \text{for matrix product,}\\
t_{0}   &=& (1+Q_{0})\gamma_{0} & \text{otherwise}.%
\end{array}\right.
\end{equation}
This recurrence relation solves into~\({t_\ell =  \gamma^{\ell}t_0\!+ Q_0\Theta_0\Theta^\ell\sum_{i=1}^{\ell} {\left(\lfrac{\gamma}{\Theta}\right)}^i}\).
\par
In the case of a matrix multiplication operator,~\(t_\ell\) is equal to:
%
\begin{equation}
\gamma^{\ell} {k_{0}}^{\!2} + Q_0k_0 \gamma\frac{ \gamma^{\ell}-k^{\ell}}{\gamma-k}
= {\left(\frac{K}{k_0}\right)}^{\log_k \gamma}\left({{k_{0}}^{\!2} + \frac{Q_0\gamma}{\gamma-k} k_0}\right)-\frac{Q_0\gamma}{\gamma-k}K.
\end{equation}
%
%
%
%
%
In the general case, the value of~\(t_\ell\) becomes:
\({(1 + (1+\ell)Q_{0})\gamma_0\gamma^{\ell}}\), that is equal to~\({{\left(\lfrac{G}{g_0}\right)}^{\log_{g}\gamma}\gamma_0\Bigl({1+\bigl({1+\log_g(\lfrac{G}{g_0})}\bigr)Q_0}\Bigr)}\).
%
\end{proof}
\footnotetext[1]{\label{fn:balancedadd}\cite{bini:1980,demmel:2007a} reach an improved value of~\(Q_0\) by assuming all additions are performed following a balanced tree, instead of a worst case estimate as done in all other formulas.}
\footnotetext[2]{\label{fn:binibug}We applied the same~\(\gamma_{0,1,\infty}\) for~\cite{bini:1980}, as it seems to be missing a dependency in the magnitude of the coefficients in~\({\mat{L},\mat{R},\mat{P}}\), which was fixed in~\cite{demmel:2007a}.}

\cref{th:recbound} generalizes or improves on previous similar results in~\cite{brent:1970a,Higham:2002,demmel:2007a,BBDLS16,Dai:2023aa}.
In fact,~\cite{Dai:2023aa} considers a single recursive level without base case;~\cite{brent:1970a,Higham:2002} have tight bounds but only for Strassen and Winograd's algorithms in max-norm;
lastly~\mbox{\cite{demmel:2007a,BBDLS16}} has an additional logarithmic factor likely due to a looser bound on each~\(\textbigmaxnorm{\beta^{(\ell-1)}}\), not exploiting the fact that they are matrix products.
\par
Even though the choice of the max-norm produces the tightest bounds in~\cref{th:recbound}, as in most previous works, the bounds are stated there for any choice of norm, as in~\cite{Dai:2023aa}.
Alternative norms, such as the~\(2\)-norm, may give growth factor expressions more amenable to optimizations, as detailed in \Cref{sec:numericalStabilityMeasure}.
\par
