\section{Growth factor along orbits}\label{sec:numericalStabilityMeasure}
%
In the footstep of~\cite{bini:1980}, we aim to find an alternative~\(\matrixsize{2}{2}\) matrix product tensor decomposition, in the orbit of Strassen's one, with improved accuracy, hence minimizing the growth factor.
The use of the maxnorm induces an expression~\cref{eq:gfq1inf} for~\(\gamma_{1,1,\infty}\) poorly suited for optimizations.
We will instead make two relaxations: first, using the~\(2\)-norm and second, as in~\cite{Dai:2023aa}, bounding~\(\gamma_{2,1,\infty}\) by~\(\gamma_{2,1}\):
\begin{equation}
\max_{k\in\{1\ldots mn\}}\sum_{i=1}^r\twonorm{\row{\mat{L}}{i}}\twonorm{\row{\mat{R}}{i}}|p_{i,k}| \leq \sum_{i=1}^r \twonorm{\row{\mat{L}}{i}}\twonorm{\row{\mat{R}}{i}}\twonorm{\row{\mat{P}}{i}}.
\end{equation}
\Cref{thm:IsotropiesActTransitivelyOnOptimalAlgorithm} shows that all fast~\(\matrixsize{2}{2}\) matrix product algorithms are in the same orbit under isotropies action introduced in~\cref{lem:sandwiching}.
While the tensor rank is invariant under this action, the growth factor is generally not.
As its definition is based on Frobenius norm, some isotropies leave it invariant as stated in the following lemma:
\begin{lemma}\label{lem:actionLeavingGrowthFactorInvariant}
The growth factor~\(\gamma_{2,1}\) is invariant under the action of the semidirect product~${{{\textup{\textsc{so}}^{\pm}({\Field^{n}})}{}^{\times{3}}}\!\rtimes{\mathfrak{S}_{3}}}$ induced by the special orthogonal group and the permutation group~\(\mathfrak{S}_{3}\).
\end{lemma}
\begin{proof}
By~\cref{def:FrobeniusInnerProduct}, Frobenius norms are invariant under orthogonal transformations and so is~\(\gamma_{2,1}\) by \cref{def:growthfactor}.
\Cref{lem:actionLeavingGrowthFactorInvariant} is then derived from \Cref{eq:isotropy,eq:isotropyActionOnHMRepresentation}.
\end{proof}
As it is useless to consider isotropies leaving the growth factor invariant, we limit our search to isotropies of the following form:
%
%
%
%
%
%
%
%
%
\begin{lemma}\label{lem:IwasawaDecomposition}
The action of~\({{({\textup{h}}\times{\textup{p}})}^{\times{3}}}\) determines the growth factor~$\gamma_{2,1}$ for~\({\textup{h}\!=\!\Bigl\lbrace\mat{H}_{\rho}\!=\!\begin{smatrix}\rho&0\\0&\lfrac{1}{\rho}\end{smatrix}\Bigm\vert{{\rho}>{0}}\Bigr\rbrace}\) and~\({\textup{p}\!=\!\Bigl\lbrace\mat{P}_{\xi}=\begin{smatrix}1&\xi\\0&1\end{smatrix}\Bigm\vert{\xi\in\RR}\Bigl\rbrace}\).
\end{lemma}
\begin{proof}
\cref{eq:isotropyActionOnHMRepresentation} shows that the product of any action, say~\(\mat{U}\), by a non-zero scalar affects the growth factor once in~\(\mat{U}\) and once, inverted, in~\(\Inverse{\mat{U}}\), as norms are absolutely homogeneous.
Thus, it is sufficient to consider matrices with determinant~\(1\).
\cref{lem:actionLeavingGrowthFactorInvariant} states that orthogonal matrices do not have any effect.
From the \textsc{qr} decomposition of any invertible matrices, there remains just the~\(({{\textup{h}}\times{\textup{p}}})\) part of~\({\textsc{psl}^{\pm}\bigl({\RR}^{2}\bigr)}\)'s Iwasawa decomposition in~\cref{thm:IsotropiesActTransitivelyOnOptimalAlgorithm}.
\end{proof}
We should study the action of~\({{({\textup{h}}\times{\textup{p}})}^{\times{3}}}\) on Strassen tensor decomposition in order to find variants with the smaller possible~\(\gamma_{2,1}\).
Unfortunately, a direct definitive result for this question seems to be out of reach, and we present several ersatzes.
First, we perform numerical minimization on~\(\GrowthFactor{\IsotropyAction{\Isotropy{g}}{\tensor{S}}}\) with a completely generic isotropy~\(\Isotropy{g}\) in~\({{\textsc{psl}^{\pm}\bigl({\RR}^{2}\bigr)}{}^{\times{3}}}\) (involving~\(6\) indeterminates by~\cref{lem:IwasawaDecomposition}); this experiment suggests that a suitable isotropy to reach a fast matrix product tensor decomposition with minimal~\(\gamma_{2,1}\) could be of the form~\({(\mat{U}\times\mat{U}\times\mat{U})}\) (involving only~\(2\) indeterminates).
The following proposition states precisely this possibility (its proof is a simple second partial derivative test presented in~\cref{sec:ComputationalProofs}).
\begin{restatable}{propositionS}{BestGrowthFactor}\label{prop:BestGrowthFactor}
%
Consider the matrices~\({\mat{U}(\rho,\xi)=\MatrixProduct{\mat{H}_{\rho}}{\mat{P}_{\xi}}}\) and the isotropies~\(\Isotropy{g}_{\rho,\xi}\) defined by~\({{\mat{U}(\rho,\xi)}{}^{\times{3}}}\).
The minimal value on the orbit~\(\IsotropyAction{\Isotropy{g}_{\rho,\xi}}{\tensor{S}}\) of the growth factor~\(\gamma_{2,1}\bigl({\IsotropyAction{\Isotropy{g}_{\rho,\xi}}{\tensor{S}}}\bigr)\) is reached at the point~\({{(\rho,\xi)}={\bigl(\sqrt[4]{\lfrac{4}{3}},{-\lfrac{1}{2}}\bigr)}}\) and equal to~\({{\lfrac{4}{\sqrt{2}}+\lfrac{16}{\sqrt{3}}}>{12.06603}}\).
%
\end{restatable}
The algorithm corresponding to the point~\({(\rho,\xi)}\) with minimal~\(\gamma_{2,1}\) on this restricted orbit is given in~\cref{eq:asopt}.
We gather in~\cref{tab:frobenius} values for~\(\gamma_{2,1}\) of some matrix product tensor decompositions, together with the result obtained in~\cref{prop:BestGrowthFactor}.
In~\cref{sec:implem}, we compare the implementation of algorithms associated to these tensor decompositions in order to confirm that their numerical accuracy is correlated to their respective~\(\gamma_{2,1}\) growth factor.
%
\section{Upper and lower bounds}\label{sec:holder}
%
We explore in this section some bounds on the norm of each component of an \textsc{hm} representation.
By the multiplicativity of $L_{p,q}$ norms (even generalized to negative
H\"older conjugates), this will always give alternative bounds on the error, a priori less accurate, but potentially easier to apprehend.
\begin{lemma}\label{lem:equiv}
For any \textsc{hm} representation~\(\mathcal{H}\), with matrices~\({\mat{L},\mat{R},\mat{P}}\) in~\({\Field^{r{\times}n}}\), let~\({\gamma_{\mathcal{H}}}\) be its~\(\gamma_{2,1}\) growth factor~\({\gamma_{2,1}(\mathcal{H})}\), as in~\cref{def:growthfactor}.
Then for any strictly positive~\(y\) and~\(z\), we have both:
\begin{gather}\label{eq:normsgammaupper}
\gamma_{\mathcal{H}}\leq\xnorm{\mathcal{H}}{2,3}\leq\Fnorm{\mathcal{H}}\quad\quad\text{and}\\
\max\Bigl\lbrace{r^{1+3z}}\xnorm{\mathcal{H}}{2,{-\frac{1}{z}}};\xnorm{\mat{L}}{2,-\frac{1}{y}}\!{\cdot}\xnorm{\mat{R}}{2,-\frac{1}{z}}\!{\cdot}\xnorm{\mat{P}}{2,\frac{1}{1+y+z}}\Bigr\rbrace
\leq\gamma_{\mathcal{H}.}\label{eq:normsgammalower}
\end{gather}
\end{lemma}
\begin{proof}
Let~\(a_{i}\) (resp.~\({b_{i},c_{i}}\)) denotes~\(\twonorm{\mat{L}_{i}}\) (resp.~\({\twonorm{\mat{R}_{i}},\twonorm{\mat{P}_{i}}}\)).
The first right-hand side inequality is the classical H{\"o}lder's inequality~\({{\onenorm{\vectorif{a_i{\cdot}b_i{\cdot}c_i}{i}} \leq \threenorm{\vectorif{a_i}{i}} {\cdot} \threenorm{\vectorif{b_i}{i}} {\cdot} \threenorm{\vectorif{c_i}{i}}}=\xnorm{\mathcal{H}}{2,3}}\) on~\({a_i, b_i}\) and~\(c_i\) with the H\"older conjugates~\({\frac{1}{3}+\frac{1}{3}+\frac{1}{3}=1}\).
The second right-hand side inequality is a direct application of the monotonicity of norms.
Then, the left-hand side inequality is obtained by a reverse H{\"o}lder's inequality on the vectors~\({a_i, b_i, c_i}\) and~\(1\), with the H\"older conjugates~\({\frac{1}{-1/z}+\frac{1}{-1/z}+\frac{1}{-1/z}+(1+3z)=1}\).
We have indeed that the~\({(1+3z)}\)-norm~\({\xnorm{\vectorif{1}{i}}{1/(1+{3}{z})}}\) is~\({{\bigl(\sum_{i=1}^r{1}^{1/(1+{3}{z})}\bigr)}{}^{1+{3}{z}}}\).
Combined with the relation
\({\xnorm{\mathcal{H}}{2,-\frac{1}{z}}{=}\xnorm{\vectorif{a_i}{i}}{-\frac{1}{z}}{\!\cdot}\xnorm{\vectorif{b_i}{i}}{-\frac{1}{z}}{\!\cdot}\xnorm{\vectorif{c_i}{i}}{-\frac{1}{z}}}\), this shows that the inequality~\({r^{1+3z}\xnorm{\mathcal{H}}{2,-\frac{1}{z}} {\leq} \onenorm{\vectorif{a_i{\cdot}b_i{\cdot}c_i{\cdot}1}{i}}}\) holds.
%
Finally, for the other lhs, we use H{\"o}lder's inequality on~\({a_i, b_i}\) and~\(c_i\), now with H\"older conjugates~\({\frac{1}{-1/y}+\frac{1}{-1/z}+\frac{1}{1/(1+y+z)}=1}\).
\end{proof}
