\begin{restatable}{propositionS}{tencubetwonorm}\label{prop:tencubetwonorm}
The minimal product~\(\Fnorm{\mathcal{H}}\) of the three Frobenius norms of the \textsc{hm} representation of any bilinear algorithm for matrix multiplication with~\(7\) multiplications, is~\(\sqrt{10}{}^3\).
\end{restatable}
