\begin{lemma}\label{lem:minimum}
With~\({\mat{W}=\begin{smatrix}r&x\\0&r^{-1}\end{smatrix}}\),~\({\mat{V}=\begin{smatrix}s&y\\0&s^{-1}\end{smatrix}}\),~\(\mat{L}\)
the first component of Strassen's \textsc{hm} representation given
in~\Cref{eq:StrassenHMRepresentation} and any~\({z\geq{0.5171}}\),
the
point~\({\bigl(\lfrac{\sqrt[4]{3}}{\sqrt{2}},\lfrac{\sqrt[4]{3}}{\sqrt{6}},\lfrac{\sqrt[4]{3}}{\sqrt{2}},{-}\lfrac{\sqrt[4]{3}}{\sqrt{6}}\bigr)}\)
is a local minimum
of~\({\xnorm{\mat{L}\cdot(\mat{W}\otimes\mat{V})}{2,-\lfrac{1}{z}}}\)
as a function of~\({r, x, s}\) and~\(y\).
\end{lemma}
\begin{proof}
As in the proof of~\cref{prop:tencubetwonorm}, we give an explicit expression~\(f_z(r,x,s,y)\) of~\({\xnorm{\mat{L}\cdot(\mat{W}\otimes\mat{V})}{2,-\lfrac{1}{z}}}\)
%
%
%
%
%
%
%
%
%
%
%
%
%
equal to:
\begin{equation}
{\left(\!\!
\begin{array}{r}
{\bigl((r^2+x^2)(s^2+y^2)+\lfrac{(2xy+\lfrac{1}{rs})}{rs}\bigr)}^{-\lfrac{1}{2z}}+{(rs)}^{\lfrac{1}{z}}\\
+{\bigl(s^2+{(y+\lfrac{1}{s})}^2\bigr)}^{-\lfrac{1}{2z}}\bigl({{(r^2+x^2)}^{-\lfrac{1}{2z}}+{r}^{\lfrac{1}{z}}}\bigr)\\
+{\bigl(r^2+{(x-\lfrac{1}{r})}^2\bigr)}^{-\lfrac{1}{2z}}\bigl({(s^2+y^2)}^{-\lfrac{1}{2z}}+{s}^{\lfrac{1}{z}}\bigr)\\
+{\Bigl(\bigl(r^2+x^2\bigr)\bigl(s^2+y^2\bigr)\Bigr)}^{-\lfrac{1}{2z}}
\end{array}
\right)}^{-z}.
\end{equation}
Then the evaluation of its partial derivatives at the given point is zero, by inspection, for any real~\(z\).
%
Now, the roots of the characteristic polynomial of the Hessian
of~\(f_z\) at this point
are~\({\frac{n}{6z}\bigl(b_1\pm\sqrt{\delta_1}\bigr)}\)
and~\({\frac{n}{18z}\bigl(b_2\pm\sqrt{\delta_2}\bigr)}\),
with~\({\tau{=}\sqrt[2z]{3}}\) and~\({\lambda{=}\sqrt[2z]{2}}\),
for~\({n{=}{\bigl(\lambda+6\tau\bigr)}^{-1-z}}\), using
\({b_1{=}{{({32z}-{11})}\tau^{1+z}+4z\lambda\sqrt{3}}}\), and
\({b_2{=}{{({{96z}-{63}})\tau^{1+z}}+{52z\lambda\sqrt{3}}}}\),
\(\delta_1{=}24(1-16z)z\tau\lambda+(1344z^2-384z+39)\tau^2+48z^2\lambda^2\)
and finally
\({\delta_2{=}72(272z-237)z\tau\lambda+(12096z^2-20736z+8991)\tau^2+8112z^2\lambda^2}\).

First,~\(\delta_1\) and~\(\delta_2\) are positive for positive $z$, so
that the eigenvalues are then always real.
Second, both expressions~\({{b_{i}}^{\!2}-\delta_{i}}\) have the same
root, strictly less than~\(0.5171\).
Third, all four eigenvalues are thus strictly positive for~\({z\geq{0.5171}}\).
\end{proof}
\begin{corollary}\label{cor:lowerbound}
\({11.7554696<\frac{28}{9}2^{\frac{11}{14}}3^{\frac{5}{7}}}\) is a lower bound for the~\(\gamma_{2,1}\) growth factor of an \textsc{hm} formula using~\(7\) products.
\end{corollary}
\begin{proof}
Following the proof of~\cref{lem:minimum}, we have that equality~\({f_z\!\left(\frac{\sqrt[4]{3}}{\sqrt{2}},\frac{\sqrt[4]{3}}{\sqrt{6}},\frac{\sqrt[4]{3}}{\sqrt{2}},\frac{-\sqrt[4]{3}}{\sqrt{6}}\right)=\!{\left(2^{\frac{-1}{2z}} + 3^{\frac{1}{2z}}2^{\frac{-1}{z}}6\right)}^{-z}}\) holds.
Denoting this quantity by~\(\zeta_{z}\)  we thus have that~\({7^{1+3z}\zeta_z^3}\leq{7^{1+3z}\xnorm{\mathcal{H}}{2,-\lfrac{1}{z}}}\), which left-hand side limit at~\({z=\infty}\) is~\({\frac{28}{9}2^{\frac{11}{14}}3^{\frac{5}{7}}}\).
By~\cref{eq:normsgammalower}, this shows that this value is less than or equal to~\(\gamma_{2,1}\) as announced.
It is also the limit of~\({{{\zeta_{z}}^{\!2}\zeta_{{-1}-2z}}\leq{\xnorm{\mat{L}}{2,-\frac{1}{z}}{\cdot}\xnorm{\mat{R}}{2,-\frac{1}{z}}{\cdot}\xnorm{\mat{P}}{2,\frac{1}{1+z+z}}}}\) at~\({z=\infty}\).
\end{proof}
\Cref{cor:lowerbound} for instance shows that the~\(\gamma_{2,1}\) growth factor of the conventional algorithm ($8$) can not be attained by such fast algorithms.
Let us see now how this bound behaves in our experiments.
%
\section{Algorithms into practice}\label{sec:implem}
%
In this section, we present several techniques to lower the number of operations used in our algorithms and thus, lower complexity bounds and potentially obtain a better accuracy.
\par
Determining actual complexity bounds requires estimating the number of operations required to implement a given formula.
Considering an \textsc{hm} representation, a direct upper bound can be obtained by: first count the number of coefficients different from~\({0,\pm{1}}\) to upper bound the number of multiplications/divisions; second count the number of non-zero coefficients, minus the number of rows, to get an upper bound on the number of additions/subtractions.
\par
To obtain lower operation counts, we use the following techniques:
first, we select among equivalently accurate algorithms: this is presented in~\cref{ssec:rotations};
second, we factor as much as possible the computations between rows of the \textsc{hm} representations, as in~\cref{ssec:factor};
third, we use dependent rows as more opportunities for factorization, as in~\cref{ssec:kernel}.
We then present some good candidates (as well as in~\cref{app:suppl})
and we eventually look at some potential sparse alternative change of basis in~\cref{ssec:schwartz}.
%
\subsection{Sparsifying via rotations}\label{ssec:rotations}
%
We have seen in~\cref{lem:actionLeavingGrowthFactorInvariant} that orthogonal transformations leave the Frobenius norm invariant and thus, the~\(\gamma_{2,1}\) growth factor.
Therefore, one can apply~\(\matrixsize{4}{4}\) generic Kronecker products of orthogonal~\(\matrixsize{2}{2}\) (rotation) matrices using~\cref{lem:actionOnHMRepresentation} and try to optimize the considered \textsc{hm} representation for several possible goals:
%
(1) %
a smaller number of non-zero coefficients in \textsc{hm} representation components;
(2) %
a non-zero pattern better suited to factorization (see the technique of~\cref{ssec:factor});
(3) %
a triangular (sparse) subset of independent rows (see the technique of~\cref{ssec:kernel}).
%
\par
For instance, to obtain~\cref{eq:asopt}, we solve for the minimal values of the Frobenius norms as in~\cref{prop:tencubetwonorm} and then for orthogonal transformations that produce as many vectors of the canonical basis as possible.
Doing so, we found that with~\(\gamma_{2,1}\) set to~\({\lfrac{16}{\sqrt{3}}+\lfrac{4}{\sqrt{2}}}\) and \textsc{hm} representation component Frobenius norms set to~\(\sqrt{10}\), the maximal possible number of canonical vectors was~$1$.
\Cref{eq:asopt} is one of those.
Similarly, \Cref{eq:powrot} is an orthogonal optimization of~\Cref{eq:powers}, with one canonical vector in each of components of the \textsc{hm} representation.
A \textsc{c}++ implementation of these tools is available in the \plinopt~library~\cite{jgd:2024:plinopt}.
%
\subsection{Factoring heuristics}\label{ssec:factor}
%
For the implementation of a given linear operator (in this work one of the matrices in the \textsc{hm} representation) one can try to find the shortest straight-line program for its computation.
The problem is \textsc{np}-hard in general (see e.g.~\cite[\S~3.1.1]{Boyar:2013aa}); but for small matrices, and over the field with~\(2\) elements,~\cite{Boyar:2013aa} and references therein propose several heuristics that potentially reduce the number of operations.
\par
Not all of them are applicable to fields with more elements, but we use a kind of common sub-expression eliminations, the ``cancellation-free'' search, described in~\cref{alg:factoringout} and implemented in \href{https://github.com/jgdumas/plinopt/blob/main/src/optimizer.cpp}{\texttt{plinopt/optimizer\,-D}}~\cite{jgd:2024:plinopt}.
%
\subsection{Kernel computation and Tellegen's principle}\label{ssec:kernel}
%
If the rank of the linear operator is lower than its number of rows, then an additional strategy has proven useful:
compute first some independent rows, then express the dependent ones by their linear relations.
%
%
For this, \cref{alg:kernel} computes a left kernel of the linear operator and uses it to compute the dependent rows via linear combinations of the independent ones.
This is sometimes faster than directly computing the dependent rows.
Of course, if the matrix's rank is lower than the number of \emph{columns}, one can apply~\cref{alg:kernel} to the transposed matrix and then apply the \emph{Tellegen's transposition} principle to recover the transposed linear dependencies (e.g.\ see~\cite{bostan:2003} and references therein).
\begin{algorithm}[h]
\caption{Kernel decomposition of a linear operator}\label{alg:kernel}
\begin{algorithmic}[1]
\Require{\(\mat{M}\) in~\(\Field^{m{\times}n}\) such that~\({r=\MatrixRank{\mat{M}}}\).}
\Ensure{A straight line program computing~\(\vec{u}\leftarrow{\mat{M}}{\cdot}\vec{v}\).}
\State{By Gaussian elimination, compute~\({\mat{M}={\mat{P}\cdot\mat{L}\cdot\mat{U}\cdot\mat{Q}}}\) with~\(\mat{P}\) a permutation matrix,~\(\mat{L}\) in~\(\Field^{m{\times}r}\) be~\({\begin{smatrix}\mat{L}_1\\ \mat{L}_2\end{smatrix}}\) unit upper triangular and~\(\mat{L}_1\) in~\(\Field^{r{\times}r}\); choosing~\(\mat{P}\) so that~(1) the first~\(r\) rows of~\(\mat{P}^{-1}\mat{M}\) are sparsest;~(2)~\(\mat{L}_1\) is the sparsest;~(3)~\(\mat{L}_2\) is the sparsest;}
\State{Let~\(\sigma\) be the permutation represented by~\(\mat{P}\);}
\State{Apply Alg.~\ref{alg:factoringout} to~\({\Transpose{\begin{smatrix}u_{\sigma(1)}\ldots{u_{\sigma(r)}}\end{smatrix}}\leftarrow\begin{smatrix}I_r 0\end{smatrix}\cdot\mat{P}\cdot\mat{M}\cdot\vec{v}}\);}
\Statex\Comment{\(\begin{smatrix}-{\mat{L}_{2}}\cdot{{\mat{L}_{1}}^{\!{-1}}}&\mat{I}_{m-r}\end{smatrix}\) is a (sparse) left kernel of~\(\mat{M}\) and provides the linear dependencies of the remaining rows}
\State{Apply Alg.~\ref{alg:factoringout} to~\({\Transpose{\begin{smatrix}u_{\sigma(r+1)}\ldots{u_{\sigma(m)}}\end{smatrix}}\leftarrow{\mat{L}_{2}}\cdot{{\mat{L}_{1}}^{\!{-1}}}\Transpose{\begin{smatrix}u_{\sigma(1)}\ldots{u_{\sigma(r)}}\end{smatrix}}}\).}
\end{algorithmic}
\end{algorithm}
\par
\Cref{alg:kernel} is implemented in \href{https://github.com/jgdumas/plinopt/blob/main/src/optimizer.cpp}{\texttt{plinopt/optimizer\,-K}}.
The Tellegen's transposition principle applied to such \textsc{slp}s is implemented in \href{https://github.com/jgdumas/plinopt/blob/main/src/transpozer.cpp}{\texttt{plinopt/transpozer}}~\cite{jgd:2024:plinopt,jgd:2024:mFMM}.
These routines have produced the implementations for our different \textsc{hm} formulas given in the following section (e.g.\ the implementation~\cref{alg:asopt} of~\cref{eq:asopt} with only~\(24\) additions and~\(12\) multiplications/divisions).
