\subsection{Cancellation-free search}\label{app:suppl}
%
\Cref{alg:factoringout} describes a common sub-expression elimination heuristic that reduced the number of operations in our algorithms.
\begin{footnotesize}
\begin{algorithm}
\caption{Cancellation-free optimization of a linear operator}\label{alg:factoringout}
\begin{algorithmic}[1]
\Require{$\mat{M}\in\Field^{m{\times}n}$.}
\Ensure{A straight-line program computing $x\rightarrow{\mat{M}}{\cdot}x$.}
\Repeat\hfill\Comment{Precomputing all repeated pairs}
\State{In each row list all pairs of indices of non-zero coefficients;}
\State{Among all the rows, find the pair(s) with the maximal number of co-linear representatives;}
%
\State{In case of ties, exhaust all the possibilities with maximal pairs (or choose one using a score like that of~\cite[\S~3.2]{Boyar:2013aa});}
\State{Precompute the chosen pair (in a temporary variable);}
\State{Factor this pair out of all the rows: that is removing the pair from all rows but add a new column to the matrix (representing that pair) with the co-linear multiple of that temporary variable;}
\Until{no pair has more than $1$ representative}
\Statex\Comment{Multipliers by columns:}
\ForAll{equal coefficients in a column (up to sign)}
\State{Compute the product by the absolute value in a temporary variable;}
\State{Factor this coefficient out: remove it from the column, add a new column (representing that product) with a~\(\pm{1}\) in the corresponding row(s);}
\EndFor
\Statex\Comment{Multipliers by rows:}
\ForAll{equal coefficients in a row (up to sign)}
\State{Compute the sum (or subtraction) of variables with that same coefficients in a temporary variable;}
\State{Factor the coefficient out: remove it from the row, but add a new column (representing that sum/subtraction) with the coefficient in the same row;}
\EndFor
\Statex\Comment{Now the matrix has been simplified}
\State{Apply the remaining linear operations of the matrix.}
\end{algorithmic}
\end{algorithm}
%
\end{footnotesize}
