        & & NOMTO-CNO: $0.7x^3 + 4.0x$ \\
        \midrule
        \multirow{2}{*}{Nguyen-2} & \multirow{2}{*}{$x^4 + x^3 + x^2 + x$} & NOMTO-FNO: $0.92x^4 + 3.4x^{2.5} + 3.1x + 2.1$ \\
        & & NOMTO-CNO: $x^4 + 2.0x^2 + 7.6$ \\
        \midrule
        \multirow{2}{*}{Nguyen-5} & \multirow{2}{*}{$\sin(x^2)\cos(x) - 1$} & NOMTO-FNO: $-0.4 \sin(0.4 \cos^2(x - 1.0)) - 1.0$ \\
        & & NOMTO-CNO: $0.1\cos(2.0\ln(x) + 0.9) - 0.9$ \\
