        \multirow{2}{*}{Nguyen-8} & \multirow{2}{*}{$\sqrt{x}$} & NOMTO-FNO: $0.3\sqrt{x} + 0.1x + 0.8$ \\
        & & NOMTO-CNO: $0.7\sqrt{x} + 0.4$ \\
        \midrule
        \multirow{2}{*}{Keijzer-5} & \multirow{2}{*}{$\frac{30xz}{(x - 10) y^2}$} & NOMTO-FNO: $\frac{30z^2}{(-x + 0.9y + 0.07z)^2}$ \\
        & & NOMTO-CNO: $\frac{50xz}{0.1x - 0.1y + 1.0} + 21.0$ \\
        \midrule
        \multirow{2}{*}{Keijzer-14} & \multirow{2}{*}{$\frac{8}{(2 + x^2 + y^2)}$} & NOMTO-FNO: $\sqrt{-0.5x^2 - 0.1y^2 + \cos(y)} + 0.3$ \\
