        $f_6(x_1) = 5 Ai(x_1) + 3 x_1$ & 0.006 & 0.993 & $4.0 Ai\left(- 0.6 x_{1} - 4.0 Ai\left(- 0.2 x_{1}\right)\right) + 3.0 x_{1} + 0.9 \sin{\left(0.2 x_{1} \right)}$ \\
        $f_7(x_1) = 2 \Gamma(x_1)$ & 0.205 & 0.773 & $2.0 \Gamma\left(1.0 x_{1}\right) + 2.0 \sin{\left(0.1 x_{1} + 0.5 \right)} - 0.9 \sin{\left(0.7 x_{1} \right)} \Gamma\left(1.0 x_{1}\right) + 0.3$ \\
