\subsection{Differential Privacy}
All the datasets in this paper are collections of records.
A randomized function that maps input datasets to an output space is referred to as a \emph{mechanism}.
For mechanism $\cM$ and dataset $\bx$, we use $\cM(\bx)$ to denote the random variable returned over the output space of $\cM$.
Two datasets $\bx$ and $\bx'$ are said to be \emph{adjacent}, denoted $\bx \sim \bx'$, if, 
one can be obtained by adding or removing one record from the other.
We consider the following notion of $(\eps, \delta)$-\emph{differential privacy (DP)}.
\begin{definition}
    \label{def:dp}
    Let $\eps > 0$ and $\delta \in [0, 1]$. 
    A mechanism $\cM$ satisfies \emph{$(\eps, \delta)$-differentially privacy} ($(\eps, \delta)$-DP for short) if
    for all adjacent datasets $\bx \sim \bx'$, and for any (measurable) event $E$ it holds that
    $
        \Pr[\cM(\bx) \in E] \le e^{\eps} \Pr[\cM(\bx') \in E] + \delta.
    $
\end{definition}
We also say that a mechanism satisfies $\eps$-DP if it satisfies $(\eps, 0)$-DP.
To prove privacy guarantees, we will use basic properties of DP stated in \Cref{prop:dp-properties} (in \secref{apx:dp-tools}).
%\sasha{We need a clean enough user-duplication result stated.}\pritish{What does this mean?}

\paragraph{DP Clustering.} Clustering is a central primitive in unsupervised machine learning~\citep[see, e.g.,][]{IkotunEAAJ23}.%\citep{xu05clustering,aggarwal13clustering}.\pritish{Are these the best citations?}
 Abstractly speaking, a (Euclidean) clustering algorithm takes as input a dataset of vectors in $\R^d$, and returns a set $C \subseteq \R^d$ of $k$ ``cluster centers'' (for a specified parameter $k$), that are representative of the dataset; formalized for example, via the $k$-means objective~\citep{lloyd1982least}. Clustering algorithms have been well-studied in the literature for several decades, and more recently with DP guarantees as well. We discuss more related work in \secref{apx:related}.
While our framework is compatible with any DP clustering algorithm, specifically, 
we use the implementation of DP clustering in the open-source Google DP library\footnote{%
    \url{https://github.com/google/differential-privacy/tree/main/learning/clustering}
}, as described in \cite{chang21practical}; 
we denote the $(\eps, \delta)$-DP instantiation of any such algorithm producing (up to) $k$ clusters 
as $\texttt{DP\text{-}K\text{-}Means}_{k, \eps, \delta}$.

\paragraph{DP Histogram Release.}
%\pritish{Re-write paragraph to clearly say what the input and output is.}
In the private histogram release problem over a set of bins $\cB$,
the input is a multi-set $\bh := \{h_1, h_2, \ldots, h_k\}$ where each $h_i \subseteq \cB$ with $|h_i| \le k$.
The desired output is a histogram $h_* \in \Z^{\cB}$, that is desired to be as close to $\sum_i h_i$ as possible, where we abuse notation to interpret $h_i$ as an indicator vector in $\{0, 1\}^{\cB}$.

%; as before, the notion of adjacency is that $\bh$ and $\bh'$ are adjacent if one can be obtained

% In the private histogram release problem,
% given a collection of numbers,
% the goal is to release a histogram of this collection while satisfying DP.
% There are several adjacency relations that can be considered for this problem; the one we need in this setting
% is as follows: we say that two collections $\{C_i\}_{i \in I}$ and $\{C'_i\}_{i \in I}$ are adjacent iff
% $\max |C_i - C'_i| \le k$.\pritish{Change the letter $C$ here.}

There are multiple algorithms for this problem (e.g., the Laplace mechanism, Gaussian mechanism, etc.); in this paper, we use the discrete Laplace mechanism introduced by \citet{GRS12:discrete-laplace}, where
$\texttt{PHR}_{k, \eps}$ is the instantiation of this algorithm that is 
$\eps$-DP and tolerates removal of up to $k$ elements. See \secref{apx:dp-tools} for formal details.
\begin{theorem}[\cite{GRS12:discrete-laplace}]
    For all integers $k > 0$ and $\eps > 0$: $\texttt{PHR}_{k, \eps}$ satisfies $\eps$-DP.
\end{theorem}
\vspace{-.5em}
\paragraph{DP Partition Selection.}
In the private partition selection problem over a (potentially infinite) set $\cB$,
the input is a multi-set $\bh := \{h_1, h_2, \ldots, h_k\}$ where each $h_i \subseteq \cB$ with $|h_i| \le k$.
The desired output is a subset $S \subseteq \cB$ such that $S \subseteq \bigcup_i h_i$ and $S$ is as large as possible.
We use the partition selection algorithm introduced by \cite{desfontaines22differentially}; 
$\texttt{PPS}_{k, \eps, \delta}$ is the instantiation of this algorithm that is 
$(\eps, \delta)$-DP. See \secref{apx:dp-tools} for formal details.
% In the private partition selection problem, given a collection of objects, the goal is to release 
% the set of elements in the collection while satisfying DP.
% In other words, the dataset $\bx$ here is a multiset of some objects from a potentially infinite set $\Omega$; 
% and two datasets $\bx$ and $\bx'$ are adjacent if one can be obtained from another by removing an element.


%\pritish{Need to update to the version where each record contributes 3-5 keywords. \Cref{alg:partition_selection} is the version where each record only contributes 1.}
\begin{theorem}[\cite{desfontaines22differentially}]
    For all integers $k > 0$, $\eps > 0$ and $\delta \in [0, 1]$: $\texttt{PPS}_{k, \eps, \delta}$ satisfies $(\eps, \delta)$-DP.
\end{theorem}
