\section{Formal Details of DP Tools}\label{apx:dp-tools}

In this section we recall basic properties of DP as well as formally describe the tools of private partition and private histogram release as alluded to in \secref{sec:prelims}.

\begin{proposition}[Properties of DP]\label{prop:dp-properties}
\mbox{}
\begin{itemize}[nosep]
\item {\bf [Parallel Composition]}
    If $\cM : \Omega^* \to \cR$ satisfies $(\eps, \delta)$-DP, then for any disjoint collection of subsets $\Omega_1, \Omega_2, \ldots, \Omega_r \subseteq \Omega$, given a dataset $D \subseteq \Omega$, the mechanism that returns $(\cM(D \cap \Omega_1), \cM(D \cap \Omega_2), \ldots, \cM(D \cap \Omega_r))$ also satisfies $(\eps, \delta)$-DP.
\item {\bf [Basic Composition]}
    If mechanism $\cM_1$ with output space $Y$ satisfies $(\eps_1, \delta_1)$-DP and 
    the mechanism $\cM_{2, y}$ satisfies $(\eps_2, \delta_2)$-DP for all $y \in Y$. 
    Then the mechanism $\cM$ that maps $\bx$ to $(y_1 \sim \cM_1(\bx), y_2 \sim \cM_{2, y_1}(\bx))$ satisfies 
    $(\eps_1 + \eps_2, \delta_1 + \delta_2)$-DP.
\item {\bf [Postprocessing]} If $\cM$ with output space $Y$ satisfies $(\eps, \delta)$-DP, then for any function $f : Y \to Z$, the mechanism $\cM'$ that maps $\bx \mapsto f(M(\bx))$ satisfies $(\eps, \delta)$-DP.
\end{itemize}
\end{proposition}

 The (truncated) discrete Laplace distribution
$\DLap_\tau(\eps)$ is the distribution on $\Z$ such that%
\sasha{For practical purposes, one can just sample from \href{https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.dlaplace.html}{\tt scipy.stats.dlapalce} and truncate to $\log(1 / \delta) / \eps$.}
\[
    \Pr_{X \sim \DLap_\tau(\eps)}[X = x] = 
    \begin{cases}
        \beta_{\eps,\tau} \cdot e^{-\eps |x|} & \text{for } z \in [-\tau, \tau]\\
        0 & \text{otherwise}
    \end{cases},
    \qquad \text{where }
    \textstyle \beta_{\eps, \tau} := \frac{1 - e^{-\eps}}{1 + e^{-\eps} - 2 e^{-\eps (\tau + 1)}}
\]

The case of $\tau=\infty$ is simply the discrete Laplace distribution $\DLap(\eps)$.

\subsection{Private Histogram Release}
The mechanism $\texttt{PHR}_{k,\eps}(h_1, \ldots, h_n)$ simply returns a noisy histogram obtained by adding discrete Laplace noise $\DLap(\eps/k)$ to each value of the true histogram.

\begin{algorithm}
\SetKwInput{KwParams}{Parameters}
\KwParams{$\eps > 0$ and $k \in \N$.}
\KwIn{$h_1, \dots, h_n \subseteq \cB$ with $|h_i| \le k$.}
\KwOut{A histogram $\bar{h} \in \Z^{\cB}$}
\BlankLine

$h^* \gets \sum_i h_i$ \tcp*{$h_i$ interpreted as indicator vector in $\{0, 1\}^{\cB}$.}
%$c_x \gets |\{i ~:~ x_i = x\}|$ for all $x \in D$

\For{$b \in \cB$}{
    Let $\zeta_b \sim \DLap(\eps / k)$

    $\bar{h}_b \gets h^*_b + \zeta_b$
}
\Return{$\bar{h}$}
\caption{Private Histogram Release $\texttt{PHR}_{k, \eps}(x_1, \dots, x_n)$}
\label{alg:private_histograms}
\end{algorithm}


\subsection{Private Partition Selection}
% The optimal algorithm solving Private Partition Selection 
% is based on 

The mechanism $\texttt{PPS}_{k,\eps,\delta}(h_1, \ldots, h_n)$ returns a subset of elements for which the noisy count, after adding truncated discrete Laplace noise $\DLap_\tau(\eps/k)$ is more than $\tau$.\pritishinfo{For now I attributing the $k$ sized subset version of partition selection to \cite{desfontaines22differentially} itself. This if fine for now, but should be fixed eventually.}
%noisy histogram obtained by adding discrete Laplace noise $\DLap(\eps)$ to each value of the true histogram.

\begin{algorithm}
    \SetKwInput{KwParams}{Parameters}
    \KwParams{$k \in \N$, $\eps > 0$ and $\delta \in [0, 1]$.}
    \KwIn{$h_1, \dots, h_n \subseteq \Omega$ with $|h_i| \le k$.}
    %\KwIn{Elements $x_1, \dots, x_n \in \Omega$ of the multiset.}
    \KwOut{The set $R \subseteq \bigcup_i h_i$.}
    \BlankLine
    $\eps', \delta' \gets \eps/k, \delta/k$

    $\tau \gets \lceil \frac{1}{\eps'} \log(\frac{e^{\eps'} + 2 \delta' - 1}{(e^{\eps'} + 1) \delta'}) \rceil$

    $R \gets \emptyset$

    \For{$\omega \in \bigcup_i h_i$}{
        $c_\omega \gets |\{i ~:~ h_i \ni \omega\}|$
        $\zeta_\omega \sim \DLap_\tau(\eps)$

        \If{$c_\omega + z_\omega > \tau$}{
            $R \gets R \cup \{\omega\}$
        }
    }
    \Return{$R$}
    \caption{Private Partition Selection $\texttt{PPS}_{\eps, \delta}(x_1, \dots, x_n)$}
    \label{alg:partition_selection}
\end{algorithm}

