\KwOut{High Level Summaries $\bs = (s_1, \ldots, s_k) \in \cS^k$}
\BlankLine


\tcp{Step 1: Extract Embeddings from Conversations}
$\be \leftarrow \ExtractEmbeddings(x_i) : i \in [n]\}$

\tcp{Step 2: Clustering (K-means)}
$\bc, \bC \leftarrow \KMeans_k(\be)$ \tcp*{$\bc$ are centers, $\bC$ are assignments}

\tcp{Step 3: Summarize each Cluster}
$\bs \leftarrow \emptyset$ \tcp*{Initialize summaries set}
\For{$j \leftarrow 1$ \KwTo $k$}{
    $\mathbf{samples}_j \leftarrow \textsf{SampleConversations}(\bc_j,\bC_j,\bx)$ \tcp*{Draw representative samples based on the center and cluster}
    $s_j \leftarrow \LLMSummarize(\mathbf{samples}_j)$ \tcp*{Generate summary using LLM}
    $\bs \leftarrow \bs \cup \{s_j\}$
}

\Return{$\bs$}
\caption{$\SimplifiedClio_k$ : Non-Differentially Private Text Corpora Summarization}
\label{alg:non-dp-pipeline}
\end{algorithm}

