% \textbf{Compute gradient-like velocity component (as per FIPSO):}
% \begin{equation}
%     g_i^{(t),d} = \frac{1}{N_i} \sum_{j \in N_i} c_j r_j \left( p_{\text{best},j,d} - x_i^{(t),d} \right)
% \end{equation}

% \textbf{Adam First-Moment Update (Momentum):}
% \begin{equation}
%     m_i^{(t+1),d} = \beta_1 m_i^{(t),d} + (1 - \beta_1) g_i^{(t),d}
% \end{equation}

% \textbf{Adam Second-Moment Update (RMS):}
% \begin{equation}
%     v_i^{(t+1),d} = \beta_2 v_i^{(t),d} + (1 - \beta_2) \left( g_i^{(t),d} \right)^2
% \end{equation}

% \textbf{Bias-Corrected Estimates:}
% \begin{equation}
%    \hat{m}_i^{(t+1),d} = \frac{m_i^{(t+1),d}}{1 - \beta_1^{t+1}}, \quad \hat{v}_i^{(t+1),d} = \frac{v_i^{(t+1),d}}{1 - \beta_2^{t+1}} 
% \end{equation}

% \textbf{Final Velocity Update with Adam Adjustment:}
% \begin{equation}
%     v_i^{(t+1),d} = w \cdot v_i^{(t),d} + \alpha \cdot \frac{\hat{m}_i^{(t+1),d}}{\sqrt{\hat{v}_i^{(t+1),d}} + \epsilon}
% \end{equation}

% \textbf{Position Update (Remains Unchanged):}
% \begin{equation}
%     x_i^{(t+1),d} = x_i^{(t),d} + v_i^{(t+1),d}
% \end{equation}

% \textbf{where:}
% \begin{itemize}
%     \item \( \alpha \): Learning rate (step-size)
%     \item \( \beta_1 \): Exponential decay rate for the first moment estimates (\(\sim 0.9\))
%     \item \( \beta_2 \): Exponential decay rate for the second moment estimates (\(\sim 0.999\))
%     \item \( \epsilon \): Small constant for numerical stability (\(\sim 1e-8\))
%     \item \( w \): Inertia weight for velocity (usually \( \sim 0.5 - 0.9 \))
% \end{itemize}
% In the Adam-Assisted Fully Informed Particle Swarm Optimization (Adam-FIPSO) algorithm, the traditional velocity update rule of PSO is modified to incorporate the adaptive moment estimation strategy of the Adam optimizer. This adaptation enables per-dimension learning rates that are adjusted dynamically based on both the first and second moments of the estimated social influence, enhancing the stability and efficiency of convergence in complex search landscapes.

For each particle \(i\) and dimension \(d\), an influence-driven gradient component is first computed using:

\begin{equation}
    g_i^{(t),d} = \frac{1}{N_i} \sum_{j \in N_i} c_j r_j \left( p_{\text{best},j,d} - x_i^{(t),d} \right),
\end{equation}

where \(N_i\) denotes the set of neighbors influencing particle \(i\), \(c_j\) is a constant weight coefficient, and \(r_j \sim \mathcal{U}(0,1)\) is a random scalar modulating the influence from neighbor \(j\). This term is analogous to a gradient, constructed via fully informed interactions in the swarm.

The first moment estimate is updated using the following equation:

\begin{equation}
    m_i^{(t+1),d} = \beta_1 m_i^{(t),d} + (1 - \beta_1) g_i^{(t),d}.
\end{equation}

while the second moment is updated as:

\begin{equation}
    v_i^{(t+1),d} = \beta_2 v_i^{(t),d} + (1 - \beta_2) \left( g_i^{(t),d} \right)^2.
\end{equation}

To account for initialization bias in early iterations, bias-corrected estimates are computed:

\begin{equation}
    \hat{m}_i^{(t+1),d} = \frac{m_i^{(t+1),d}}{1 - \beta_1^{t+1}}, \quad
    \hat{v}_i^{(t+1),d} = \frac{v_i^{(t+1),d}}{1 - \beta_2^{t+1}}.
\end{equation}

The final velocity update combines the inertia term and the adaptive Adam step:

\begin{equation}
    v_i^{(t+1),d} = w \cdot v_i^{(t),d} + \alpha \cdot \frac{\hat{m}_i^{(t+1),d}}{\sqrt{\hat{v}_i^{(t+1),d}} + \epsilon}.
\end{equation}

Where \(w\) is the inertia weight and \(\alpha\) is the learning rate. The particle position is then updated as:

\begin{equation}
    x_i^{(t+1),d} = x_i^{(t),d} + v_i^{(t+1),d}.
\end{equation}

In these equations, \(\beta_1\) and \(\beta_2\) are exponential decay rates for the first and second moment estimates, typically set to \(0.9\) and \(0.999\), respectively. The term \(\epsilon\) is a small constant (e.g., \(10^{-8}\)) included for numerical stability during division.

In a multi-dimensional setting, each particle explores a high-dimensional parameter space, where each dimension corresponds to a variational parameter (\(\gamma\) or \(\beta\)). The particles leverage both social knowledge from neighboring particles and local gradient-like information to guide their movement. The Adam component introduces per-dimension momentum and adaptive scaling based on first and second moment estimates, allowing each particle to take appropriately sized steps in every dimension. This combination enables efficient navigation of the complex, non-convex landscapes typical of QAOA optimization.

