\begin{algorithm}
\caption{Adam-Assisted Fully Informed PSO (Adam-FIPSO)}
\begin{algorithmic}[1]
\State \textbf{Input:} Objective function $f(\boldsymbol{\theta}, \mathcal{Q}, C^*)$, bounds $[\boldsymbol{l}, \boldsymbol{u}]$, dimension $d$
\State \textbf{Parameters:} Swarm size $S$, max iterations $T$, inertia weights $w_{\max}, w_{\min}$, learning rate $\eta$, decay rates $\beta_1$, $\beta_2$, $\epsilon$

\For{$i = 1$ to $S$}
    \State Initialize position $\boldsymbol{\theta}_i \sim \mathcal{U}([\boldsymbol{l}, \boldsymbol{u}])$
    \State Initialize velocity $\boldsymbol{v}_i = \boldsymbol{0}$, moments $\boldsymbol{m}_i = \boldsymbol{0}$, $\boldsymbol{v}_i = \boldsymbol{0}$
    \State Evaluate $f_i = f(\boldsymbol{\theta}_i, \mathcal{Q}, C^*)$
    \State Set personal best: $\text{pbest}_i \gets \boldsymbol{\theta}_i$
\EndFor
\State Set global best $\boldsymbol{g}$ as best among $\text{pbest}_i$

\For{$t = 1$ to $T$}
    \State $w \gets w_{\max} - \frac{t}{T}(w_{\max} - w_{\min})$
    \For{each particle $i$}
        \State $\Delta_i \gets \sum_{j=1}^{S} \text{rand}() \cdot (\text{pbest}_j - \boldsymbol{\theta}_i)$
        \State $\boldsymbol{v}_i \gets w \cdot \boldsymbol{v}_i + \frac{c}{S} \cdot \Delta_i$
        \State $\boldsymbol{\theta}_{\text{cand}} \gets \boldsymbol{\theta}_i + \boldsymbol{v}_i$
        \State Estimate gradient $\nabla f$ at $\boldsymbol{\theta}_{\text{cand}}$
        \State $\boldsymbol{m}_i \gets \beta_1 \boldsymbol{m}_i + (1-\beta_1)\nabla f$
        \State $\boldsymbol{v}_i \gets \beta_2 \boldsymbol{v}_i + (1-\beta_2)(\nabla f)^2$
        \State $\hat{\boldsymbol{m}}_i \gets \boldsymbol{m}_i / (1 - \beta_1^t)$
        \State $\hat{\boldsymbol{v}}_i \gets \boldsymbol{v}_i / (1 - \beta_2^t)$
        \State $\boldsymbol{\theta}_{\text{cand}} \gets \boldsymbol{\theta}_{\text{cand}} - \eta \cdot \hat{\boldsymbol{m}}_i / (\sqrt{\hat{\boldsymbol{v}}_i} + \epsilon)$
        \State Clip $\boldsymbol{\theta}_{\text{cand}}$ to $[\boldsymbol{l}, \boldsymbol{u}]$
        \State Update: $\boldsymbol{v}_i \gets \boldsymbol{\theta}_{\text{cand}} - \boldsymbol{\theta}_i$
        \State $\boldsymbol{\theta}_i \gets \boldsymbol{\theta}_{\text{cand}}$
        \State Evaluate $f_i = f(\boldsymbol{\theta}_i, \mathcal{Q}, C^*)$
        \State Update $\text{pbest}_i$ and $\boldsymbol{g}$ if $f_i$ is improved
    \EndFor
\EndFor

\State \textbf{Return:} Best solution $\boldsymbol{g}$ and objective value $f(\boldsymbol{g}, \mathcal{Q}, C^*)$
\end{algorithmic}
\end{algorithm}


