% \Big[\nabla_{e_i} V_{i}^*(e_i)f(x_i)+\nabla_{e_i} V_{i}^*(e_i)g(x_i)u_{i}^*
% +r_{i}(e_i,u_{i}^*)\Big]
=0,\label{kkt1}\\
&\lambda^*_i\Big[\sum_{l\in N_i^a(t)}\Big(\nabla_{x_l}h(\bar{x}_{N_i})(f(x_l)+g(x_l)u_l)\Big)+\alpha(h(\bar{x}_{N_i}))\Big]
% \nabla_{x_i}h(\bar{x}_{N_i})
