=0,\label{kkt2}\\
&%{\rm the\; inequality}\ (\ref{N_R})
\sum_{l\in N_i^a(t)}\Big(\nabla_{x_l}h(\bar{x}_{N_i})(f(x_l)+g(x_l)u_l)\Big)+\alpha(h(\bar{x}_{N_i}))\ge0
 % \nabla_{x_i}h(\bar{x}_{N_i})\big(f(x_i)+g(x_i)u_{i}^*\big)+\sum_{j\in N_i,j\neq i}\Lambda_{ij}^{e}+\alpha(h(\bar{x}_{N_i}))\ge0
,\label{kkt3}\\
&\lambda^*_i\ge0,\label{kkt4}
\end{align}   
\end{subequations}
where $\nabla_{u_i^*}H_i(e_i,u_i^*,\nabla_{e_i} V_i^*(e_i))=\nabla_{e_i} V_{i}^{*}(e_i)g(x_i)+2u_i^{*T}R$. We slightly abuse the notation to let $u_l = u_{i}^*$ when $l=i$ in both (\ref{kkt2}) and (\ref{kkt3}) for convenience. Lastly, $\lambda^*_i$ is the state-dependent Lagrange multiplier of agent $i$.
% and $\Lambda_{ij}^{e}=\nabla_{x_j}h(\bar{x}_{N_i})\big(f(x_j)+ g(x_j)u_{j}\big)$, $j\in N_i$, $j\neq i$.

Solving \eqref{kkt1} yields the explicit form of the safe optimal controller 
\begin{align}\label{us}
u_{i}^*=-\frac{1}{2}R^{-1}g^T(x_i)\Big(\nabla_{e_i}^T V_{i}^*(e_i)-\lambda^*_i\nabla_{x_i}^T h(\bar{x}_{N_i})\Big).
\end{align}
Substituting (\ref{us}) into (\ref{kkt2}) yields the following equation for the Lagrange multiplier $\lambda^*_i$
\begin{align}
&\lambda^*_i\big(\Lambda_{i}+\lambda^*_i\vartheta_{i}\big)=0,\ \forall i\in V_a,\label{lagrange1}
\end{align}
with
\begin{subequations}\label{lagrange}
\begin{align}
% &\lambda^*_i\big(\Lambda_{i}+\lambda^*_i\vartheta_{i}\big)=0,\label{lagrange1}\\
&\Lambda_{i}=\nabla_{x_i}h(\bar{x}_{N_i})
f(x_i)-\frac{1}{2}\nabla_{x_i} h(\bar{x}_{N_i})g(x_i)R^{-1}g^T(x_i)\nabla_{e_i}^T V_{i}^*(e_i)\nonumber\\
&\qquad\ +\sum_{j\in N_i^a(t),j\neq i}\Lambda_{ij}^{e}+\alpha(h(\bar{x}_{N_i})),\label{lagrange2}\\
&\vartheta_{i}=\frac{1}{2}\nabla_{x_i} h(\bar{x}_{N_i})g(x_i)R^{-1}g^T(x_i)\nabla_{x_i}^Th(\bar{x}_{N_i}),\label{lagrange3}\\
&\Lambda_{ij}^{e}=\nabla_{x_j}h(\bar{x}_{N_i})\big(f(x_j)+ g(x_j)u_{j}\big),\ j\in N_i^a(t),\ j\neq i.\label{lagrange4}
\end{align}     
\end{subequations}
% (\ref{kkt3}), (\ref{kkt4}), (\ref{us}), 
When $\nabla_{x_i}h(\bar{x}_{N_i})g(x_i)\neq 0$ for all $\bar{x}_{N_i}\in X^M$, it follows from \eqref{lagrange3} that $\vartheta_{i}>0$ for all $i\in V_a$. Solving (\ref{lagrange1}) yields the state-dependent Lagrange multiplier $\lambda^*_i$ of agent $i$: 
\begin{align}\label{lag}
\lambda^*_i=\begin{cases}
-\frac{\Lambda_{i}}{\vartheta_{i}},&  {\rm if}\  \Lambda_{i}<0,\\
0,& {\rm if}\ \Lambda_{i}\ge0.
\end{cases}
\end{align} 
Unlike state-of-the-art safe learning control methods~\cite{Yang2024tac,Dawood2025RAL,yu2023learning,zhang2025discrete,zhang2023neural}, which rely on manually tuned static parameters to balance safety and task performance and can result in deadlocks or collisions, our framework provides a principled and systematic approach to integrate these objectives into a single design~(\ref{us}) via a state-dependent Lagrange multiplier~(\ref{lag}).
Specifically, in (\ref{us}), the term $\nabla_{e_i}^T V_{i}^*(e_i)$ corresponds to \textit{goal-reaching} and $\nabla_{x_i}^T h(\bar{x}_{N_i})$ is the \textit{safety control components} which generates the collision avoidance behaviors. The state-dependent Lagrange multiplier enables a dynamic trade-off between the safety control component and the goal-reaching control component, depending on the real-time system state and environment sensing.

The theorem below certifies both the safety and goal-reaching properties of the derived controller (\ref{us}). To state the theorem precisely, let the zero-superlevel set of the graph CBF $h$ (See Section~\ref{Section2.3}) be denoted by $C:=\big\{\tilde{x}\in X^M\ \big|\ h(\tilde{x})\ge0\big\}.$
% \begin{align}\label{cm}
% C=\big\{\tilde{x}\in X^M\ \big|\ h(\tilde{x})\ge0\big\}.
% \end{align}
% Under a chosen controller, a graph control barrier function $h$ can certify forward invariance of its zero-superlevel set. 
For each agent $i$, let $H_{N,i}$ denote the set of the corresponding MAS states $\bar{x}$ where the neighborhood state $\bar{x}_{N_i}$ of agent $i$ is in set $C$, that is, $H_{N,i}:=\big\{\bar{x}\in X^N\ |\ \bar{x}_{N_i}\in C \big\}.$ 
Denote their intersection as $H_{N}:=\bigcap_{i=1}^N H_{N,i}.$
Clearly, $H_{N,i}\subseteq S_i$ for all $i\in V_a$ implies $H_N\subseteq S$. We have:

\begin{theorem}\label{the1}
Consider an arbitrarily sized MAS (\ref{mas}). Suppose that there exist $C^1$ positive definite functions $V_{i}^*$, $i\in V_a$ satisfying (\ref{optimal-V}), and a graph CBF $h: X^M\to\mathbb{R}$ satisfying $H_{N,i}\subseteq S_i$ for all $i\in V_a$. Then, for any initial condition $\bar{x}(t_0)\in H_N$, the safe optimal controllers $u_i^*,\ i\in V_a$ in (\ref{us}) with the state-dependent Lagrange multipliers $\lambda_i^*,\ i\in V_a$ in (\ref{lag}) ensure that the MAS state remains in the safe set, i.e., 
\[
\bar{x}(t) \in S \quad \text{for all } t \ge t_0,
\]
and that each agent reaches its goal position as $t\to+\infty$, i.e., 
\[
\lim_{t \to +\infty} e_i(t) = 0.
\]
\end{theorem}
\emph{Proof:} We first prove that each agent reaches its goal position, then proves safety of the MAS (\ref{mas}). From (\ref{hjb-opt}) and the definition $r_i(e_i,u_i^*)=e_i^TQe_i+u_i^{*T}Ru_i^*$, the time derivative of $V_{i}^*$ satisfies
\begin{align}\label{t1.1}
&\frac{d  V_i^*(e_i(t))}{d t}\nonumber\\
=&
\nabla_{e_i(t)} V_i^*(e_i(t))f(x_i(t))
+\nabla_{e_i(t)} V_i^*(e_i(t))g(x_i(t))u_i^*(t)\nonumber\\
=&-r_{i}(e_i(t),u_i^*(t))
\leq-e_i^T(t)Qe_i(t).
\end{align}
Since the functions $V_i^*$, $i\in V_a$ are positive definite and $C^1$, we immediately have from the Lyapunov stability theory \cite{khalil1996nonlinear} that $\lim_{t\to+\infty} e_i(t)=0$, i.e., each agent can reach its goal position as $t\to+\infty$. 


To prove safety, we show the satisfaction of the graph CBF constraint \eqref{kkt3}. Note that the condition $\nabla_{x_i}h(\bar{x}_{N_i})g(x_i)\neq 0$ for all $\bar{x}_{N_i}\in X^M$ ensures $\vartheta_{i}>0$ in \eqref{lagrange3} for all $i\in V_a$. If $\Lambda_{i}\ge0$, then by \eqref{lagrange1} and $\lambda^*_i=0$ in (\ref{lag}), thus 
\begin{align*}
\dot{h}(\bar{x}_{N_i}(t))+\alpha(h(\bar{x}_{N_i}(t))=\Lambda_{i}+\lambda^*_i\vartheta_{i}\ge0.
\end{align*}
% $\dot{h}(\bar{x}_{N_i}(t))+\alpha(h(\bar{x}_{N_i}(t))=\Lambda_{i}+\lambda^*_i\vartheta_{i}\ge0$. 
If $\Lambda_{i}<0$, then by \eqref{lagrange1} and $\lambda^*_i=-\Lambda_{i}/\vartheta_{i}$ in (\ref{lag}), thus 
\begin{align*}
\dot{h}(\bar{x}_{N_i}(t))+\alpha(h(\bar{x}_{N_i}(t))=\Lambda_{i}+\lambda^*_i\vartheta_{i}=0.
\end{align*}
% $\dot{h}(\bar{x}_{N_i}(t))+\alpha(h(\bar{x}_{N_i}(t))=\Lambda_{i}+\lambda^*_i\vartheta_{i}=0$. 
In both cases, the graph CBF constraint \eqref{kkt3} is satisfied for any $t\ge t_0$. Since the function $h(\bar{x}_{N_i}(t)$ is $C^1$, it follows from the comparison lemma~\cite{khalil1996nonlinear} that 
\begin{align}\label{t1.2}
h(\bar{x}_{N_i}(t_0)\ge0\Rightarrow   h(\bar{x}_{N_i}(t)\ge0, \ t\ge t_0,
\end{align}
for any $i\in V_a$. Recall that $H_{N,i}\subseteq S_i$ for all $i\in V_a$ implies $H_N\subseteq S$. 
% Since the initial MAS state s that $H_N\subseteq S$. 
Therefore, for any $\bar{x}(t_0)\in H_N\subseteq S$, i.e., $h(\bar{x}_{N_i}(t_0)\ge0$ for all $i\in V_a$, it follows from (\ref{t1.2}) that the MAS state remains in the safe set, i.e., $\bar{x}(t)\in H_N \subseteq S$ for all $t\ge t_0$. \hfill $\square$
