      \node[gn] (n2) at (1,0) {$2$}; 
      \draw[gedge] (n1) to (n2);
  }
  \leftarrow \fcGraph{n1}{
      \node[gn] (n1) at (0,0) {$1$};
      \node[gn] (n2) at (0.8,0) {$2$};
  }
  \dotFalse
  \\
\append & = \Big(
  \tikz[remember picture,baseline=(a.base)]{
