      \node[gn] (n2) at (1,0) {$2$};
      \draw[gedge] (n1) to (n2)
                   (n2) edge[exaloop right] (n2);
      \saveBboxSouthAs{reasys motiv example R} }
   \leftarrow
      \tikz[remember picture,baseline=(a.base)]{
        \node (a) at (0,0) {$\emptyset$};
        \saveBboxSouthAs{reasys motiv example R0} }
  ,\ \condtrue
  \Big)
  % explaining arrows
  \begin{tikzpicture}[remember picture, overlay]
    \draw[cospanarr] (reasys motiv example L0) to[bend right=29] node[below,pos=0.65]{$\ell$} ($(reasys motiv example I)+(-4pt,-7pt)$);
    \draw[cospanarr] (reasys motiv example R0) to[bend left=29] node[below,pos=0.65]{$r$} ($(reasys motiv example I)+(4pt,-7pt)$);
