      \draw[->] (sqtr) -- node[right]{$\alpha$} (sqbr);
      \draw[->] (sqbl) -- node[overlay,below]{$\beta$} (sqbr);
    \end{tikzpicture}
  \]
  Shifting of existential conditions is performed analogously.
\end{definition}

% It is easy to see that shift distributes over conjunction and
% disjunction:
% $\big( \bigland_{i \in I} \forall f_i.\mathcal A_i \big)_{\downarrow
%   c} = \bigland_{i \in I} \big( \forall f_i.\mathcal A_i
% \big)_{\downarrow c}$.

While the
representation of the shifted condition may differ depending on the
chosen class of representative squares, the resulting conditions are
equivalent. Since we assume that each set $\kappa(f_i,c)$ is finite,
shifting a finite condition will again result in a finite condition.
